local config = {
  ui_story_5075_50750100_1_dialog_content = "（蜃風号の航海は危険続きだったけど、なんとか海を越えて、\n龍州大陸の土を踏むことができた）",
  ui_story_5075_50750100_2_dialog_content = "（ユエとシュウさんたちは、商会の荷の護送で、あと2日は忙しい）",
  ui_story_5075_50750100_3_dialog_content = "（リン家商会からは、街を案内すると熱心に誘われたけど…）",
  ui_story_5075_50750100_4_dialog_content = "（僕にはアストラ大陸の使者としての務めがある。\nまずはタンドウたちと済の都に行かないと）",
  ui_story_5075_50750100_5_dialog_content = "龍女様ァ、おたのんまさァ――",
  ui_story_5075_50750100_6_dialog_content = "どうかァシケはやめてくだせェ\n明日干し豆腐をお供えしますからァ――",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>ザバーン！</color>",
  ui_story_5075_50750100_8_dialog_content = "うわっ！",
  ui_story_5075_50750100_9_dialog_content = "PlayerName、気をつけるのじゃ。",
  ui_story_5075_50750100_10_dialog_content = "異国の景色に見とれてしまうのは分かるが、\n川を行く舟は蜃風号とは違うのじゃ。",
  ui_story_5075_50750100_11_dialog_content = "景色に気を取られていると、うっかり落ちてしまうぞよ。",
  ui_story_5075_50750100_12_dialog_content = "苦労して招いた、アストラ大陸の大切な使者が…",
  ui_story_5075_50750100_13_dialog_content = "暗鬼と海賊に襲われながらも、\n無事に大海原を渡り、ようやく龍州に到着したというに――",
  ui_story_5075_50750100_14_dialog_content = "王宮の目と鼻の先の川で落水したとなれば、\nわらわの罪は重大じゃ。",
  ui_story_5075_50750100_15_dialog_content = "あはは…ごめん、気を付けるよ。",
  ui_story_5075_50750100_16_dialog_content = "船頭さんの歌に聞き入っちゃって、\n舟の上だってことを忘れてた。",
  ui_story_5075_50750100_17_dialog_content = "港を出てからずっと、同じような歌だけど…",
  ui_story_5075_50750100_18_dialog_content = "この軽快な調子の歌詞は、地元の言葉なのかな？\nどういう歌なの？",
  ui_story_5075_50750100_19_dialog_content = "舟歌じゃ。",
  ui_story_5075_50750100_20_dialog_content = "済の国は河川や湖沼の多い国でのう。\n民は水と共に生き、船乗りや漁師も多い。",
  ui_story_5075_50750100_21_dialog_content = "そうした風土と歴史が舟歌を生み出したのじゃ。",
  ui_story_5075_50750100_22_dialog_content = "山の緑や澄んだ水を歌うものもあれば、\n水面に垂れる柳や満開の花を歌うものもある。",
  ui_story_5075_50750100_23_dialog_content = "他にも、今お主の聴いたような、神の加護を願う歌もあるのじゃよ。",
  ui_story_5075_50750100_24_dialog_content = "「龍女様。船が無事に航行できるよう、天気が崩れたりしないようお守りください」",
  ui_story_5075_50750100_25_dialog_content = "「家まで無事にたどり着くことができたら、\nおいしい干し豆腐を差し上げましょう」",
  ui_story_5075_50750100_26_dialog_content = "――おおかた、かような意味じゃ。",
  ui_story_5075_50750100_27_dialog_content = "あ、龍女様か！",
  ui_story_5075_50750100_28_dialog_content = "確か以前、双閣港で君がバイスに教えてた踊りは、\n<color=#FFB400>「鎮海の龍女の舞」</color>っていったよね？",
  ui_story_5075_50750100_29_dialog_content = "龍女様っていうのは、\n龍州の沿岸部に住む人たちが信仰してる神だったはず…",
  ui_story_5075_50750100_30_dialog_content = "…神様って、干し豆腐が好きなの？",
  ui_story_5075_50750100_31_dialog_content = "ホホホ、そうではない。\nお供え物の部分の歌詞は、特に決まっておらぬのじゃ。",
  ui_story_5075_50750100_32_dialog_content = "龍女様も自ら何かをご所望なさることはないしのう。\nゆえに皆、己のお供えしたいと思う物を歌詞にして歌うのじゃ。",
  ui_story_5075_50750100_33_dialog_content = "あの船頭が「干し豆腐」と歌ったのはおそらく、\nたまたま家で干し豆腐を作っているからじゃろ。",
  ui_story_5075_50750100_34_dialog_content = "そうなの？ずいぶん気さくな神様なんだね。",
  ui_story_5075_50750100_35_dialog_content = "龍州の文化は、双閣港で十分分かったつもりだったけど…",
  ui_story_5075_50750100_36_dialog_content = "実際に来てみると、見るもの聞くもの全てが新鮮だよ。",
  ui_story_5075_50750100_37_dialog_content = "バイスとカレンにも見せてあげたいなぁ。",
  ui_story_5075_50750100_38_dialog_content = "その願い、すぐにかなうかもしれぬぞ。",
  ui_story_5075_50750100_39_dialog_content = "そうだね。僕たちの任務は二大陸間の交流を強化することだもんね。",
  ui_story_5075_50750100_40_dialog_content = "順調にいけば、アストラの皆も龍州に旅行に来られるかもしれない！",
  ui_story_5075_50750100_41_dialog_content = "暗鬼に立ち向かう方策と技術の向上も忘れてはならぬぞ。",
  ui_story_5075_50750100_42_dialog_content = "互いに切磋琢磨すれば、2つの大陸の民が\n安寧な暮らしを送れる日もそう遠くはないじゃろう。",
  ui_story_5075_50750100_43_dialog_content = "それを実現するために、アストラの使者殿のお力を\nお貸しくださいませ…というわけじゃな。",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>ドン</color>",
  ui_story_5075_50750100_45_dialog_content = "殿下、PlayerName様、到着いたしました。\nこのすぐ先が目的地でございます。",
  ui_story_5075_50750100_46_dialog_content = "入城前に、こちらで上陸手続きを。",
  ui_story_5075_50750100_47_dialog_content = "PlayerName、しばし待たれよ。",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>タンドウは先に船を下り、岸辺に立つと、\n微笑みながら手を組み、軽く礼をした</color>",
  ui_story_5075_50750100_49_dialog_content = "わらわは済王の勅命を受けし者、灼華郡主と申す。\n使者としてアストラ大陸に遣わされた。",
  ui_story_5075_50750100_50_dialog_content = "そしてこの度、貴殿は当方の招きに応じ、\n使者として遠路はるばる龍州に渡ってこられた。",
  ui_story_5075_50750100_51_dialog_content = "ここに改めて敬意と謝意を表する。",
  ui_story_5075_50750100_52_dialog_content = "ようこそ<color=#FFB400>済の国の都</color>――",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>皓津（こうしん）</color>へ。",
  ui_story_5075_50750100_54_dialog_content = "うん、ありがとう！こちらこそよろしく！",
  ui_story_5075_50750100_55_dialog_content = "今度は僕がこの龍州で、アストラ大陸の使者としての務めを果たす番だね。",
  ui_story_5075_50750100_56_dialog_content = "殿下、侍従がお迎えにきております。\n宮廷に戻り、済王にご報告いたしましょう。",
  ui_story_5075_50750100_57_dialog_content = "ならば、PlayerNameは…",
  ui_story_5075_50750100_58_dialog_content = "郡主殿下、使者様、お初にお目にかかります。",
  ui_story_5075_50750100_59_dialog_content = "私は迎賓館の管理官でございます。\n使者様のお迎えに上がりました。",
  ui_story_5075_50750100_60_dialog_content = "済の国での使者様の日常のお世話および護衛は\n私ども迎賓館が承ります。",
  ui_story_5075_50750100_61_dialog_content = "どうやら、行動は共にできぬようじゃのう。",
  ui_story_5075_50750100_62_dialog_content = "務めが終われば、ユエ船長たちも戻ってくる。\nその時にまた会うとしよう。皓津を案内するぞ。",
  ui_story_5075_50750100_63_dialog_content = "龍州が最も大切にしている祝日である春新節も近い。",
  ui_story_5075_50750100_64_dialog_content = "春新節には提灯で龍を模して舞うんじゃが、それがまるで龍が街に舞い降りたかのように\n見えてのう。縁日には露店が並び、様々な食べ物も楽しめる…",
  ui_story_5075_50750100_65_dialog_content = "必ずや、よき思い出となるじゃろう。",
  ui_story_5075_50750100_66_dialog_content = "うん、楽しみにしてるね！",
  ui_story_5075_50750100_67_dialog_content = "（そう、この時の僕たちはまだ、そんなごく普通の約束が、\n波乱に満ちたものになるとは思ってもいなかった…）",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>迎賓館</color>",
  ui_story_5075_50750100_69_dialog_content = "どうぞお茶をお召し上がりください。",
  ui_story_5075_50750100_70_dialog_content = "新鮮な山の水で淹れた紫笋（しじゅん）茶でございます。\nすっきりとした甘みが特徴でございます。",
  ui_story_5075_50750100_71_dialog_content = "すごくおいしいです！ありがとう！",
  ui_story_5075_50750100_72_dialog_content = "どのような味がお好みか存じ上げなかったので、\n数種類を少量ずつご用意いたしました。",
  ui_story_5075_50750100_73_dialog_content = "荷花酥（かかそ）、七重餅、玉露羹…他にお召し上がりになりたいものがございましたら、\n何でもお申しつけください。",
  ui_story_5075_50750100_74_dialog_content = "こ、これで…「少量」ですか！？",
  ui_story_5075_50750100_75_dialog_content = "お着換えとお風呂をお手伝いいたします。",
  ui_story_5075_50750100_76_dialog_content = "い、いえ！大丈夫ですっ！自分でやります！",
  ui_story_5075_50750100_77_dialog_content = "ず、ずいぶん手厚くもてなしてくれるんですね…",
  ui_story_5075_50750100_78_dialog_content = "何だか緊張してきちゃいました…ちょっとでもヘマをすれば、\nアストラの印象を台無しにしちゃいそうで…はは…",
  ui_story_5075_50750100_79_dialog_content = "ダメだダメだ、明日は宮廷でしっかり話をしますね。長居するわけでもないですから。",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5075_50750100_81_dialog_content = "あ！宮廷の人が僕を呼びにきたのかな？",
  ui_story_5075_50750100_82_dialog_content = "使者様が海の向こう側から遠路はるばるいらしたと聞き、\n大王様も心から喜んでいらっしゃいます。",
  ui_story_5075_50750100_83_dialog_content = "銘茶と果物、お召し物と絹織物、および数種類のお香です。\nお納めください。",
  ui_story_5075_50750100_84_dialog_content = "これを全部僕に？でも…",
  ui_story_5075_50750100_85_dialog_content = "贈り物は確かにお届けいたしました。",
  ui_story_5075_50750100_86_dialog_content = "使者様にとって幸福な滞在となり、\n灼華郡主殿下にもご満足いただけるようお祈り申し上げております。",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>3日目</color>",
  ui_story_5075_50750100_88_dialog_content = "…どうしてまだ、宮廷に呼ばれないんだろう？",
  ui_story_5075_50750100_89_dialog_content = "使者様、退屈でいらっしゃいますか？\n観劇はお好きですか？",
  ui_story_5075_50750100_90_dialog_content = "よろしければ、ユーリという名高い俳優を招き、\n披露してもらいましょう。",
  ui_story_5075_50750100_91_dialog_content = "いや、そうじゃなくて…",
  ui_story_5075_50750100_92_dialog_content = "観劇はお好きではありませんか？\nでは、評弾という弾き語りや、雑技はいかがでしょう？",
  ui_story_5075_50750100_93_dialog_content = "芝居や音楽にご興味がなければ、\n闘蟋（とうしつ）や闘鶉（とうじゅん）もございます。\n皓津には、たくさんの娯楽があるのですよ。",
  ui_story_5075_50750100_94_dialog_content = "いや、今は娯楽とかそういうのは必要ありません…",
  ui_story_5075_50750100_95_dialog_content = "外に出たいんです！済王様に会わなきゃいけないんです！",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>4日目</color>",
  ui_story_5075_50750100_97_dialog_content = "ふぅ…やっと外に出られた。",
  ui_story_5075_50750100_98_dialog_content = "でも、ここはどこですか？木の札がいっぱい…\n済王様はここにはいないですよね。",
  ui_story_5075_50750100_99_dialog_content = "ここ数日、使者様は食事ものどを通らないご様子でしたが、\nおそらく気分がふさいでいらしたのでしょう。",
  ui_story_5075_50750100_100_dialog_content = "そこで、管理官に頼み、外出を楽しんでいただくことにしたのです。",
  ui_story_5075_50750100_101_dialog_content = "初めて皓津にいらしたならば、\nまずはこちらの南山龍女廟をご覧になるとよいでしょう。",
  ui_story_5075_50750100_102_dialog_content = "ここは、景色が美しい山に奇岩が趣を加え、\nさらには、かつて龍女が降臨したという伝説もございます。",
  ui_story_5075_50750100_103_dialog_content = "どうぞ心の赴くまま拝観、参拝なさってくださいませ。\n人払いも済ませております。邪魔者はおりません。",
  ui_story_5075_50750100_104_dialog_content = "え？僕のために人払いをしたんですか？\nどうりで、静かだと思いました…",
  ui_story_5075_50750100_105_dialog_content = "僕にそんなことしてもらう必要はないですよ。\n他の皆と一緒で大丈夫です。",
  ui_story_5075_50750100_106_dialog_content = "何をおっしゃいます！使者様は済の国の大切なお客様です。\n人払いは当然のことでございます。",
  ui_story_5075_50750100_107_dialog_content = "では、存分にお楽しみください。",
  ui_story_5075_50750100_108_dialog_content = "（まぁ、いいか…せっかく来たんだし、色々見て回ろう！）",
  ui_story_5075_50750100_109_dialog_content = "（正殿の真ん中にまつられてるのが龍女様かな？\n荘厳な空気が漂ってる）",
  ui_story_5075_50750100_110_dialog_content = "（タンドウの言ってたように、いろんなものがお供えしてある。\n果物や野菜、お茶の葉にお菓子…）",
  ui_story_5075_50750100_111_dialog_content = "あれ？誰かいる！人払いしたんじゃなかったの？",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>チャリン――</color>",
  ui_story_5075_50750100_113_dialog_content = "これは…侍女の誰かが落としたのかな？\nそれとも今気配がした人のかな？",
  ui_story_5075_50750100_114_dialog_content = "使者様――",
  ui_story_5075_50750100_115_dialog_content = "幾度も調べましたが、境内には他に参拝客はおりませんでした。",
  ui_story_5075_50750100_116_dialog_content = "でも、確かに人影が見えて、\n落とし物をしたみたいなんです…",
  ui_story_5075_50750100_117_dialog_content = "人影など、私は見かけ…あっ！",
  ui_story_5075_50750100_118_dialog_content = "お供え物がすべてなくなっております！",
  ui_story_5075_50750100_119_dialog_content = "ど、どうしたことでしょう…",
  ui_story_5075_50750100_120_dialog_content = "どうかお許しくださいませ。私どもの落ち度です。\nまさか、こそ泥が忍び込んでいたとは。",
  ui_story_5075_50750100_121_dialog_content = "妖魔は、龍女廟には近づこうとしません。\nきっとまた、祟霊たちでしょう…",
  ui_story_5075_50750100_122_dialog_content = "祟霊がどうかしたんですか？",
  ui_story_5075_50750100_123_dialog_content = "い、いいえ、大したことではございません。\n使者様はどうかお気になさらず。",
  ui_story_5075_50750100_124_dialog_content = "本日は私どもの落ち度で興をさましてしまい、申し訳ございません。\n先に護衛と下山なさってください。私は管理官に報告して参ります。",
  ui_story_5075_50750100_125_dialog_content = "護衛！使者様を迎賓館にお連れしなさい！",
  ui_story_5075_50750100_126_dialog_content = "かしこまりました！",
  ui_story_5075_50750100_127_dialog_content = "えええ！？ちょ、ちょっと待ってください…\nもう少しだけ、新鮮な空気を味わせてください――",
  ui_story_5075_50750100_128_dialog_content = "（その後数日間、また前と同じような日々を過ごした）",
  ui_story_5075_50750100_129_dialog_content = "（食べて、寝て、遊んで…至れり尽くせりのもてなしを受けて、\nちょっと散歩するのにも、護衛が付いてきた）",
  ui_story_5075_50750100_130_dialog_content = "（その一方で、宮廷に上がる件はいつまで経っても\n明確な返答を得られず、時間だけが過ぎていった）",
  ui_story_5075_50750100_131_dialog_content = "このままじゃダメだ。直接管理官さんに聞いてみよう。",
  ui_story_5075_50750100_132_dialog_content = "でなきゃ、いつ済王に謁見して、\nタンドウの言ってた二大陸間の交流について話せるか分からない。",
  ui_story_5075_50750100_133_dialog_content = "護衛に見つからないようにしないと…",
  ui_story_5075_50750100_134_dialog_content = "…灼華郡主よ。",
  ui_story_5075_50750100_135_dialog_content = "（あれ？今、誰かがタンドウの話をしてた？）",
  ui_story_5075_50750100_136_dialog_content = "それ、本当なの！？",
  ui_story_5075_50750100_137_dialog_content = "ハハハ。火のない所に煙は立たぬとはよく言ったものね。",
  ui_story_5075_50750100_138_dialog_content = "済の国のお世継ぎがあの郡主に夢中になっちゃって、\n他の女性には目もくれないらしいわよ。",
  ui_story_5075_50750100_139_dialog_content = "郡主は返事してないらしいけど、\n宮廷に仕えてる友だちの話じゃ、大王様は2人を結婚させるつもりらしいわ。",
  ui_story_5075_50750100_140_dialog_content = "あらら～、なるほどね。\nそれで宮廷は忙しくて、他の事に構っていられないのね。",
  ui_story_5075_50750100_141_dialog_content = "人質がお世継ぎとご成婚とは、玉の輿もいいとこだわ。\n確かあの郡主って、借金の担保だったわよね？",
  ui_story_5075_50750100_142_dialog_content = "！？",
  ui_story_5075_50750100_143_dialog_content = "あの…今皆さんが話してたのって…",
  ui_story_5075_50750100_144_dialog_content = "使者様、こちらにいらしたのですか。\nずいぶんお探しいたしました。",
  ui_story_5075_50750100_145_dialog_content = "大王様よりお達しがございました。本日使者様を宴にお招きし、\n異邦の話をお聞きになりたいとのことです。",
  ui_story_5075_50750100_146_dialog_content = "急ぎご準備くださいませ。宮廷まで私がご案内いたします。",
  ui_story_5075_50750100_147_dialog_content = "よりによってこのタイミングですか！？\n一体今日まで何してたんですか！？",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>壮麗な宮殿が立ち並び、優雅な音楽が鳴り響いている</color>",
  ui_story_5075_50750201_2_dialog_content = "続いてのお客様は、アストラ大陸からの使者――",
  ui_story_5075_50750201_3_dialog_content = "西の大陸の方は、やはり私たちとは違いますね。",
  ui_story_5075_50750201_4_dialog_content = "珍しい服装ですが、惜しいことに、\n布地を細かく裁断しすぎて、優雅さに欠けています。",
  ui_story_5075_50750201_5_dialog_content = "あの方は空の末裔だそうですぞ。\n西の大陸でも珍しい一族だとか。",
  ui_story_5075_50750201_6_dialog_content = "（皆して僕の話をしてる気がするけど…）",
  ui_story_5075_50750201_7_dialog_content = "（よかった、タンドウもいる。おかしな扱いをうけてないよね？なんだか表情が硬いかな）",
  ui_story_5075_50750201_8_dialog_content = "そなたがPlayerNameか？二大陸間の航路再開のため\n力を尽くしたとのこと、余も聞き及んでおるぞ。",
  ui_story_5075_50750201_9_dialog_content = "噂に聞くがごとく、前途有望な若者と見える。",
  ui_story_5075_50750201_10_dialog_content = "とんでもありません。蜃風号が無事に帰航できたのは、\n船上の全員が力を合わせたからこそです…",
  ui_story_5075_50750201_11_dialog_content = "謙遜せずともよい。\nさ、使者殿を席にお連れしろ。",
  ui_story_5075_50750201_12_dialog_content = "海の向こう側からの客人は珍しい。\n皆にも異邦の話を聞かせてやってはくれぬか？",
  ui_story_5075_50750201_13_dialog_content = "海の向こうの大陸には戦いに長けた鉄の巨人がいると聞く。",
  ui_story_5075_50750201_14_dialog_content = "戦士が中に入り、心で操ると、その目は雷光のごとく光り、\nその力は山川をも割くという。真か？",
  ui_story_5075_50750201_X14_option_content = "それは…ずいぶんと話が誇張されて伝わっているようです。",
  ui_story_5075_50750201_15_dialog_content = "少し…尾ひれがついているようです。",
  ui_story_5075_50750201_16_dialog_content = "アストラ大陸の機械技術も現段階ではまだ、\nそこまで発達していません。",
  ui_story_5075_50750201_17_dialog_content = "巨像というものは存在しますが、\n大王様のおっしゃったような兵器ではありません。",
  ui_story_5075_50750201_18_dialog_content = "巨像自体の数も少なく、操縦できる者もごくわずかです。",
  ui_story_5075_50750201_X18_option_content = "将来は可能かもしれませんが――",
  ui_story_5075_50750201_X19_dialog_content = "今のところ、そこまで強大な力は存在しません…",
  ui_story_5075_50750201_X20_dialog_content = "でも、軍用機械の開発研究に長けた啓光連邦や\n術や儀式に長けた白夜城という勢力がいます。",
  ui_story_5075_50750201_X21_dialog_content = "ですから、将来アストラにも\n大王様のおっしゃるような巨人ができるかもしれません。",
  ui_story_5075_50750201_X22_dialog_content = "さようか…つまり、存在せぬということだな。",
  ui_story_5075_50750201_19_dialog_content = "ならば、兵士はいかにして妖魔と戦っておるのだ？",
  ui_story_5075_50750201_20_dialog_content = "軍が様々な兵器を開発していますし、\n肉体を保護するアーマーもあります。",
  ui_story_5075_50750201_21_dialog_content = "それに光力術を組み合わせれば、暗鬼と…\nもとい、妖魔と戦うことができるんです。",
  ui_story_5075_50750201_22_dialog_content = "ふむ…肉体で戦うことには変わらぬというわけか。",
  ui_story_5075_50750201_23_dialog_content = "ならば…海の向こうの大陸も広かろう。\n不死や昇天の術は存在するのか？",
  ui_story_5075_50750201_24_dialog_content = "たぶん…存在しないと思います。",
  ui_story_5075_50750201_25_dialog_content = "少数ではありますが、各地に普通より長く生きている人がいて、\n特に北境の君主はいつまでも若いことで有名ですが…",
  ui_story_5075_50750201_26_dialog_content = "本当の意味での不老不死は…聞いたことがありません。\n少なくとも僕は、聞いたことありません。",
  ui_story_5075_50750201_27_dialog_content = "さようか。どうやら大海原の対岸も、\nこの龍州とさして変わらぬようだな。",
  ui_story_5075_50750201_28_dialog_content = "そうとも言い切れ…",
  ui_story_5075_50750201_29_dialog_content = "オッホン。",
  ui_story_5075_50750201_30_dialog_content = "（急いてはなりませぬ）",
  ui_story_5075_50750201_31_dialog_content = "…",
  ui_story_5075_50750201_32_dialog_content = "さようなことより、\nPlayerNameは変わった力を持つと聞く。",
  ui_story_5075_50750201_33_dialog_content = "本来の力を幾倍にも強めることができるとか。",
  ui_story_5075_50750201_34_dialog_content = "官職に就き、わが済に留まってはどうか？",
  ui_story_5075_50750201_35_dialog_content = "ここ幾日かで、そなたも皓津の繁栄ぶりを見たであろう？",
  ui_story_5075_50750201_36_dialog_content = "わが済は河川と肥沃な土地に恵まれ、海も山も有し、産業も栄えておる。\nまさにこの世の天宮と言えよう。",
  ui_story_5075_50750201_37_dialog_content = "妖魔がのさばる西の大陸より、居心地が良かったのではないか？",
  ui_story_5075_50750201_38_dialog_content = "ありがたいお言葉に感謝いたします。\nでも、アストラ大陸は僕の故郷です。僕の帰るべき場所はアストラです。",
  ui_story_5075_50750201_39_dialog_content = "それに、僕は今回大陸間の交流を深める使者としてここに来ました。\n自分のために来たわけではないんです。",
  ui_story_5075_50750201_40_dialog_content = "アストラ大陸には、暗鬼に有効な科学技術がたくさんあります。\n啓光や白夜城だけでなく…",
  ui_story_5075_50750201_41_dialog_content = "ふむ。申したいことは分かる。\nだが、さような些細な事は船舶府に任せておけばよい。",
  ui_story_5075_50750201_42_dialog_content = "宴の席でかような無粋を語っては、\nこの美しい時と眺めに申し訳が立たぬというもの。",
  ui_story_5075_50750201_43_dialog_content = "済の国は繁栄し、富にあふれ、めずらしきものには事欠かない。\nまもなく春新節である。共に今を祝おうではないか。",
  ui_story_5075_50750201_44_dialog_content = "皆の者、盃を持て――",
  ui_story_5075_50750201_45_dialog_content = "いや、まだ…",
  ui_story_5075_50750201_46_dialog_content = "大王様の万寿をお祈り申し上げます！",
  ui_story_5075_50750201_47_dialog_content = "済の国の益々の繁栄をお祈り申し上げます！",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>グラッグラッ！</color>",
  ui_story_5075_50750201_49_dialog_content = "地震だ！",
  ui_story_5075_50750201_50_dialog_content = "急いで大王様をお守りするのだ！",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>卓や椅子が大きく揺れ、食器がすべり落ちて割れた。\n揺れはしばらく続いた</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>宴たけなわだった宮殿が混乱一色となり、\n人々が駆け回り、命令を伝える声だけが響いている</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>ついさっきまで悠々としていた役人たちも、\n今は慌てふためいている</color>",
  ui_story_5075_50750201_54_dialog_content = "ふぅ…うまく知らせが伝わったおかげで、民たちは無事だったようじゃ。",
  ui_story_5075_50750201_55_dialog_content = "思うような話はできなんだが、\n今宵の宴はここでお開きとするしかなさそうじゃのう。",
  ui_story_5075_50750201_56_dialog_content = "タンドウ？",
  ui_story_5075_50750201_57_dialog_content = "PlayerName、行こう。静かな所で話そうではないか。",
  ui_story_5075_50750201_58_dialog_content = "ヘアバンドが何かに引っ掛かっちゃったみたいだ…",
  ui_story_5075_50750201_59_dialog_content = "タンドウ、ごめん。外してもらえるかな？",
  ui_story_5075_50750201_60_dialog_content = "このつぼみ、すごくきれいだ。きっと大切にされてる木なんだろうね。\n力いっぱい引っ張ったら、花をダメにしちゃいそうだよ。",
  ui_story_5075_50750201_61_dialog_content = "ホホッ、そうでもない…梅の花は庭のあちこちに咲いておる。\nかように梅の木をいたわる者は、おそらくお主が初めてじゃろうのう。",
  ui_story_5075_50750201_62_dialog_content = "動くでない。わらわが外してやろう。",
  ui_story_5075_50750201_63_dialog_content = "…",
  ui_story_5075_50750201_64_dialog_content = "フフ、外れたぞ。",
  ui_story_5075_50750201_65_dialog_content = "しばらく会っておらんかったが、\nここでの暮らしには慣れたかのう？",
  ui_story_5075_50750201_66_dialog_content = "うーん、身に余るもてなしに戸惑ってるよ。",
  ui_story_5075_50750201_67_dialog_content = "コップで水を飲むのも自分ではやらせてもらえなくて、\nまるで要人にでもなったような気分だよ。",
  ui_story_5075_50750201_68_dialog_content = "その通りであろう？",
  ui_story_5075_50750201_69_dialog_content = "からかわないでよ。",
  ui_story_5075_50750201_70_dialog_content = "慣れないもてなしを受けて、恥をかいてないだけまだマシだよ。",
  ui_story_5075_50750201_71_dialog_content = "それに、使者の務めもきちんと果たせなかったし…",
  ui_story_5075_50750201_72_dialog_content = "ようやく宮廷に上がれたと思えば、交流の話どころか、\nアストラを紹介することさえままならなかった。",
  ui_story_5075_50750201_73_dialog_content = "…すまぬ、PlayerName。",
  ui_story_5075_50750201_74_dialog_content = "わらわのせいじゃ。",
  ui_story_5075_50750201_75_dialog_content = "西の大陸からわざわざ来てもろうたというに、\nきちんとした話の場も設けられず…",
  ui_story_5075_50750201_76_dialog_content = "タンドウのせいじゃないよ。僕が事前にもっと準備していれば、\nこんなにあたふたすることもなかったんだから。",
  ui_story_5075_50750201_77_dialog_content = "いや、やはりわらわの…",
  ui_story_5075_50750201_78_dialog_content = "プッ…",
  ui_story_5075_50750201_79_dialog_content = "あはは…2人して自分のせいにしようとして、\nなんだかおかしいね。",
  ui_story_5075_50750201_80_dialog_content = "過ぎたことを言っても仕方ないか。帰ったら、ちゃんと準備することにするよ。\n次に宮廷に上がれた時にまた頑張ればいいんだ。",
  ui_story_5075_50750201_81_dialog_content = "…1つ聞いてもいいかな？",
  ui_story_5075_50750201_82_dialog_content = "なんじゃ？",
  ui_story_5075_50750201_83_dialog_content = "ここに来る前、迎賓館の侍女たちが話してたんだけど…\nタンドウって済の国のお世継ぎと婚約してるの？",
  ui_story_5075_50750201_84_dialog_content = "あまりいい雰囲気じゃなくて…\n君が借金の担保だとか言ってたし…",
  ui_story_5075_50750201_85_dialog_content = "それを良く思わない人に何かされたりしてない？",
  ui_story_5075_50750201_86_dialog_content = "PlayerName…",
  ui_story_5075_50750201_87_dialog_content = "心配は…無用じゃ。",
  ui_story_5075_50750201_88_dialog_content = "噂になっておるのは知っておったが、\nまさか、お主の耳にも入るとはのう。",
  ui_story_5075_50750201_89_dialog_content = "大王様はそのつもりだったようじゃが、わらわが断ったからには、\n大王様とて無理強いできぬのじゃ。",
  ui_story_5075_50750201_X89_dialog_content = "担保については…鄴の国の借金の形として、\n済の国に参ったことは真じゃ。",
  ui_story_5075_50750201_X90_dialog_content = "とはいえ、召使いがとやかく言うことではない。\n今度わらわがその者たちを正すとしよう。",
  ui_story_5075_50750201_X91_dialog_content = "タンドウ…",
  ui_story_5075_50750201_90_dialog_content = "心配はいらぬ。この国も長いからのう。\n孤立無援というわけでもないのじゃ。",
  ui_story_5075_50750201_91_dialog_content = "宮廷広しといえど、わらわに手出しできる者はおらぬ。",
  ui_story_5075_50750201_92_dialog_content = "だったら、お世継ぎも無理矢理には？",
  ui_story_5075_50750201_93_dialog_content = "ハッハッハ、もちろんじゃ。そもそもお世継ぎはまだ…",
  ui_story_5075_50750201_94_dialog_content = "タンドウ！タンドウ！無事だったか！？",
  ui_story_5075_50750201_95_dialog_content = "…お世継ぎ！？夜更けに、なにゆえここに？",
  ui_story_5075_50750201_96_dialog_content = "タンドウのことが心配だったのだ。",
  ui_story_5075_50750201_97_dialog_content = "先刻はずいぶんと激しく揺れたが、無事か？\nケガはないか？怖くなかったか？",
  ui_story_5075_50750201_98_dialog_content = "フフ、ありがとうございます。\nどこもケガしておりませぬ。",
  ui_story_5075_50750201_99_dialog_content = "それよりも、お世継ぎ、護衛もつけずに歩き回っていたことを大王様に知られれば、\nまたお仕置きを受けることになりますぞ。",
  ui_story_5075_50750201_100_dialog_content = "ぼ、僕はもう大人だ！お仕置きなど恐れぬ！",
  ui_story_5075_50750201_101_dialog_content = "それに男子たる者、危機が迫りし時、\n許嫁の側におらぬなど恥だ！",
  ui_story_5075_50750201_102_dialog_content = "プッ――",
  ui_story_5075_50750201_103_dialog_content = "また、さようなことを――",
  ui_story_5075_50750201_104_dialog_content = "おやおや、「男子たる者」とは、なんとご立派な。\n私も存じあげませんでした。",
  ui_story_5075_50750201_105_dialog_content = "お世継ぎの学業はこれまで、童の基準で進めてまいりましたが、\nすでに男子となられたとあれば…",
  ui_story_5075_50750201_106_dialog_content = "量が少なすぎるゆえ、今後は倍にするよう、\n先生方にお願いいたしましょう。",
  ui_story_5075_50750201_107_dialog_content = "待て…やめた！男子などやめる！",
  ui_story_5075_50750201_108_dialog_content = "た、高い志は持っているが、身も心もまだ未熟だ。\n男子の任は重すぎる！",
  ui_story_5075_50750201_109_dialog_content = "…ふぅ、疲れたな。帰って休む。",
  ui_story_5075_50750201_110_dialog_content = "タンドウ、明日また会おう！",
  ui_story_5075_50750201_111_dialog_content = "宮廷に新しく、鄴の国の料理が得意な料理人が入ったのだ。\n明日はそなたも食事に来るよう父上がおっしゃっていた。",
  ui_story_5075_50750201_112_dialog_content = "必ず来るのだぞ！",
  ui_story_5075_50750201_113_dialog_content = "ふぅ…",
  ui_story_5075_50750201_114_dialog_content = "助け船に感謝いたします。\nお陰様で大人しく寝所に戻ってくださりました。",
  ui_story_5075_50750201_115_dialog_content = "PlayerName、この方は済の国の国師殿じゃ。\n大王様のおそばで政を輔けていらっしゃる。",
  ui_story_5075_50750201_116_dialog_content = "そして、わらわの師でもある。",
  ui_story_5075_50750201_117_dialog_content = "先生の教えと計らいのおかげで、\nわらわはこの済でも、ずっと無事にやってこられたのじゃ。",
  ui_story_5075_50750201_118_dialog_content = "（そんなにすごい人なのか！あ、待って…\n龍州では、どうするのが礼儀だっけ？）",
  ui_story_5075_50750201_119_dialog_content = "お初にお目にかかります！",
  ui_story_5075_50750201_120_dialog_content = "先生、こちらはアストラから来たPlayerName殿でございます。\n先程の宴でお会いになったかと。",
  ui_story_5075_50750201_121_dialog_content = "ふむ。深く印象に残っておりますぞ。",
  ui_story_5075_50750201_122_dialog_content = "（さすがは国師さんだな…こうやってまじまじと見られると、\nさっきの宴で注目を集めてた時よりも緊張する…）",
  ui_story_5075_50750201_123_dialog_content = "おや？先生、その文の印は…",
  ui_story_5075_50750201_124_dialog_content = "「巡検司」からの急報です。",
  ui_story_5075_50750201_125_dialog_content = "もしや…少し前妖魔が増えたゆえに、\n急きょ城外の湾岸防御に当てられた隊でございますか？",
  ui_story_5075_50750201_126_dialog_content = "相手は今や、妖魔だけではないようですな。",
  ui_story_5075_50750201_127_dialog_content = "急報によれば、先刻の地震の後、\n突如として近海に狂暴化した祟霊が現れ、人を襲ったようです。",
  ui_story_5075_50750201_128_dialog_content = "巡回の者がすぐに押さえましたが、\n他でも同じことが起こっているやもしれませぬ。",
  ui_story_5075_50750201_129_dialog_content = "祟霊が狂暴化したと？なにゆえ、そのようなことが…\nもしや、さきほどの地震は天災ではなく、他に理由があると？",
  ui_story_5075_50750202_1_dialog_content = "いかにも。ついてはこの件の調査を郡主にお願いしたいのです。",
  ui_story_5075_50750202_2_dialog_content = "かしこまりました。さっそく明日にも――",
  ui_story_5075_50750202_3_dialog_content = "明日は大王様に代わって、子どものおもりをするのでは？",
  ui_story_5075_50750202_4_dialog_content = "それは…",
  ui_story_5075_50750202_5_dialog_content = "僕が…手伝ってもいいかな？",
  ui_story_5075_50750202_6_dialog_content = "タンドウは忙しいでしょ？\n僕はどうせヒマだし、調査だけなら大丈夫だと思うよ。",
  ui_story_5075_50750202_7_dialog_content = "そうはいかぬ。そもそも無理を言って、\n急きょ使者として龍州まで来てもろうたのじゃ。",
  ui_story_5075_50750202_8_dialog_content = "済の国の事でまで、お主を煩らわすわけにはいかぬ。",
  ui_story_5075_50750202_9_dialog_content = "私はよい方法だと思いますが。",
  ui_story_5075_50750202_10_dialog_content = "先生？",
  ui_story_5075_50750202_11_dialog_content = "郡主のお書きになった2大陸間交流の計画を拝見しました。",
  ui_story_5075_50750202_12_dialog_content = "しかし、先ほどのご様子からすると、\n大王様には、今すぐ進める気がないことは明らかでしたな。",
  ui_story_5075_50750202_13_dialog_content = "実に残念です。",
  ui_story_5075_50750202_14_dialog_content = "PlayerName殿、あなたも使者として、\n大王様ともう少しお話ししたいと思っていらっしゃるのでは？",
  ui_story_5075_50750202_15_dialog_content = "そうなんです。",
  ui_story_5075_50750202_16_dialog_content = "僕は多くの人の期待を背負い、そして多くの人に助けられながらここまで来ました。\n手ぶらで帰るわけにはいきません。",
  ui_story_5075_50750202_17_dialog_content = "ならば、いい機会でございますな。",
  ui_story_5075_50750202_18_dialog_content = "まもなく春新節を迎える今の時期、\n城内の人の行き来は増え、さまざまな催し物も行われます。",
  ui_story_5075_50750202_19_dialog_content = "このような時に妖魔や祟霊に騒がれては、\n民にも被害が及び、深刻な事態となりかねませぬ。",
  ui_story_5075_50750202_20_dialog_content = "ゆえに、もし早期解決できたならば、その者の功は大きい――",
  ui_story_5075_50750202_21_dialog_content = "大王様も必ずや褒賞をお与えになることでしょう。",
  ui_story_5075_50750202_22_dialog_content = "迎賓館にはもう、使い方も分からない物がたくさんあるので、\n褒美はいりませんが…",
  ui_story_5075_50750202_23_dialog_content = "これで功を挙げて、済王殿下にぜひ計画を聞いてもらいたいです！",
  ui_story_5075_50750202_24_dialog_content = "国師さん、その任務、僕に任せてください。",
  ui_story_5075_50750202_25_dialog_content = "ただ1つお願いがございます。\nそれを承諾していただけるのなら、お任せするといたしましょう。",
  ui_story_5075_50750202_26_dialog_content = "どんなことですか？",
  ui_story_5075_50750202_27_dialog_content = "…できるかぎり、内密に事を進めてください。\nこの件は、朝廷の者には決して話さぬように。",
  ui_story_5075_50750202_28_dialog_content = "先生、PlayerNameは異邦から参られたのですぞ。\n済の国ではそもそも動きが取りにくいのに、独りで行動させるなど無謀ではありませぬか？",
  ui_story_5075_50750202_29_dialog_content = "PlayerName殿に単独行動させるとは言っておりませぬ。",
  ui_story_5075_50750202_30_dialog_content = "早合点はよくありませぬぞ。\n郡主、急いてはなりませぬ。",
  ui_story_5075_50750202_31_dialog_content = "…",
  ui_story_5075_50750202_32_dialog_content = "タンドウ、心配しないで。",
  ui_story_5075_50750202_33_dialog_content = "アストラ大陸でも、よく知らない土地で依頼を受けてたんだ。\nそれなりに経験は豊富なんだ。",
  ui_story_5075_50750202_34_dialog_content = "それはすばらしい。",
  ui_story_5075_50750202_35_dialog_content = "郡主、PlayerName殿をお送りしてください。",
  ui_story_5075_50750202_36_dialog_content = "…はい。",
  ui_story_5075_50750202_37_dialog_content = "PlayerName――",
  ui_story_5075_50750202_38_dialog_content = "「すまぬ」とか「やめておくのじゃ」とかそういう話なら聞かないよ。",
  ui_story_5075_50750202_39_dialog_content = "じゃが、お主だけを走り回らせて、\nわらわは宮廷でのうのうとしているのが…",
  ui_story_5075_50750202_40_dialog_content = "宴で出てきた料理、おいしかったね。",
  ui_story_5075_50750202_41_dialog_content = "？",
  ui_story_5075_50750202_42_dialog_content = "タンドウはそう思わなかった？\n双閣港で食べたものよりも、ずっと手が込んでておいしかった。",
  ui_story_5075_50750202_43_dialog_content = "そうじゃな。宮廷の料理人が作っておるからのう。",
  ui_story_5075_50750202_44_dialog_content = "つまり、僕たちが自分で作った料理じゃないってことだよね。\nじゃあ、お米は僕たちが作ったの？",
  ui_story_5075_50750202_45_dialog_content = "むろん、農民が育てたのじゃ。",
  ui_story_5075_50750202_46_dialog_content = "それを僕たちが城内まで運んできたの？",
  ui_story_5075_50750202_47_dialog_content = "いや、商家が運んだのじゃ。",
  ui_story_5075_50750202_48_dialog_content = "だったら、買ったのは僕たち？",
  ui_story_5075_50750202_49_dialog_content = "それも違う。宮中の調達司じゃ。",
  ui_story_5075_50750202_50_dialog_content = "だよね。じゃあ、タンドウはその人たちに面倒を掛けたって思うの？\n自分が代わりに皆の仕事をしなきゃって思う？",
  ui_story_5075_50750202_51_dialog_content = "…人にはそれぞれ役目というものがある。\nわらわもそこまでできるとは思っておらん。",
  ui_story_5075_50750202_52_dialog_content = "だったら、今回の調査も同じだよ。",
  ui_story_5075_50750202_53_dialog_content = "誰だって何もかも1人で出来るわけじゃない。タンドウは他に用があって、\n僕はその役目を代われる。だったら、僕がやればいいだけのことでしょ？",
  ui_story_5075_50750202_54_dialog_content = "皆、他人に面倒を掛けたり、他人に頼ったりしながら、\nこの世界は回ってるんだ。",
  ui_story_5075_50750202_55_dialog_content = "あ…もちろん、僕じゃ頼りないって言うなら…",
  ui_story_5075_50750202_56_dialog_content = "さようなわけなかろう！",
  ui_story_5075_50750202_57_dialog_content = "…まったく…使者よりも弁論家の方が\nPlayerNameには向いておるのかのう。",
  ui_story_5075_50750202_58_dialog_content = "お主がそこまで言うなら、わらわもこれ以上言う事はない。",
  ui_story_5075_50750202_59_dialog_content = "あはは…",
  ui_story_5075_50750202_60_dialog_content = "よかった、PlayerNameの顔色がよくなったようじゃ。",
  ui_story_5075_50750202_61_dialog_content = "コホン。そんなにはっきり顔に出てたかな…？",
  ui_story_5075_50750202_62_dialog_content = "わらわのせいで、PlayerNameには気苦労を掛けるのう。\n使者の務めやら、先刻の地震やら…",
  ui_story_5075_50750202_63_dialog_content = "おまけに、わらわがこの国で辛い思いをしてはいないかと心配までさせて…\nそれでは、気分が晴れぬのも当然じゃ。",
  ui_story_5075_50750202_64_dialog_content = "余計なお世話だったかな？",
  ui_story_5075_50750202_65_dialog_content = "いや、PlayerNameのおかげで、気分が晴れてきた。",
  ui_story_5075_50750202_66_dialog_content = "わらわも奮い立たねばのう。\n一刻も早く、諸々解決するとしよう。",
  ui_story_5075_50750202_67_dialog_content = "そうだね。一緒に頑張ろう！\n一緒に行動することはできなくても…",
  ui_story_5075_50750202_68_dialog_content = "心は一つじゃ。力を合わせ、望みをかなえよう！",
  ui_story_5075_50750202_69_dialog_content = "使者様、お迎えに上がりました。",
  ui_story_5075_50750202_70_dialog_content = "あ、わざわざ迎えに来てくれたんですか？",
  ui_story_5075_50750202_71_dialog_content = "もちろんでございます。済の国にいらっしゃるかぎり、\nあなた様は賓客でございます。手抜かりがあってはなりません。",
  ui_story_5075_50750202_72_dialog_content = "じゃあ、僕はこれで。何かあったら、また連絡するよ。",
  ui_story_5075_50750202_73_dialog_content = "宮中で、よい知らせを待っておるぞ。",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5075_50750202_75_dialog_content = "殿下？なぜお1人で、このような場所にいらっしゃるのですか？",
  ui_story_5075_50750202_76_dialog_content = "キュウ、戻ったか。先に申し付けたことは順調か？",
  ui_story_5075_50750202_77_dialog_content = "申し訳ございません。まだ真相をつかめておりません。",
  ui_story_5075_50750202_78_dialog_content = "ただ、多くの密偵がいまだ密かに皓津で動いております。",
  ui_story_5075_50750202_79_dialog_content = "私がおそばにいられない時、どうか十分にお気をつけください。",
  ui_story_5075_50750202_80_dialog_content = "分かっておる。大儀じゃったな。",
  ui_story_5075_50750202_81_dialog_content = "とはいうものの、しばらくわらわは宮中に留まることになりそうじゃ。\nおそらく危険はあるまい。",
  ui_story_5075_50750202_82_dialog_content = "そうじゃ。寝所に戻ったら、\n文を書くのを忘れぬよう声を掛けてくれぬか。",
  ui_story_5075_50750202_83_dialog_content = "ユエ船長らも荷を送り届け、皓津に戻ったというに――",
  ui_story_5075_50750202_84_dialog_content = "あの「璇璣卿」ときたら、まったく音沙汰がないのじゃ。\n訳の分からぬ言葉を残したまま…",
  ui_story_5075_50750202_85_dialog_content = "どうやら、わらわ自ら筆を執り、問いたださねばならぬようじゃ。",
  ui_story_5075_50750202_86_dialog_content = "…おや？",
  ui_story_5075_50750202_87_dialog_content = "殿下、どうなさいましたか？",
  ui_story_5075_50750202_88_dialog_content = "何でもない。ちと驚いただけじゃ。",
  ui_story_5075_50750202_89_dialog_content = "知らぬ間に梅のつぼみが開いておるのう…",
  ui_story_5075_50750202_90_dialog_content = "殿下は、カイドウがお好きだったのではありませんか？",
  ui_story_5075_50750202_91_dialog_content = "じゃが、今日の梅の花は格別に美しい。",
  ui_story_5075_50750301_1_dialog_content = "（自信満々に任務を受けちゃったけど…）",
  ui_story_5075_50750301_2_dialog_content = "（思わぬ障害があった！）",
  ui_story_5075_50750301_3_dialog_content = "あの…ちょっと街を歩くだけで、\nこれはちょっと大げさなんじゃ…？",
  ui_story_5075_50750301_4_dialog_content = "使者様は特別なご身分なのですよ。\n護衛6名など最低限の警護にすぎません。",
  ui_story_5075_50750301_5_dialog_content = "現在護衛を9名増やすよう願い出ております。\nそれでようやく安心できるというもの。",
  ui_story_5075_50750301_6_dialog_content = "まだ増やすんですか！？",
  ui_story_5075_50750301_7_dialog_content = "まあ、いいか…それはさておき…",
  ui_story_5075_50750301_8_dialog_content = "どうして、街に人がいないんですか？",
  ui_story_5075_50750301_9_dialog_content = "それはもちろん、人払いをしたからです。\n使者様の街歩きのお邪魔になってはいけませんから。",
  ui_story_5075_50750301_10_dialog_content = "これじゃ街歩きした気になりませんよ…",
  ui_story_5075_50750301_11_dialog_content = "困ったな…護衛、護衛って…あまりにも度が過ぎてる！",
  ui_story_5075_50750301_12_dialog_content = "（このままじゃ調査どころか、龍州の人と話すことさえもできない…）",
  ui_story_5075_50750301_13_dialog_content = "…あなたの手を煩わすまでもありません。\n私がお渡ししましょう。",
  ui_story_5075_50750301_14_dialog_content = "（あれ？外で何を話してるんだろう？）",
  ui_story_5075_50750301_15_dialog_content = "ですが、宮中より直接使者様に手渡すようにと申し付かっているのです。\nどうか、お通し願えませんか？",
  ui_story_5075_50750301_16_dialog_content = "そうですか、では中へ。",
  ui_story_5075_50750301_17_dialog_content = "使者様、ごきげんよう。",
  ui_story_5075_50750301_18_dialog_content = "こちらは新しく入った宮廷料理人の作った菓子でございます。\n貴人方の間でも、おいしいと評判でございます。",
  ui_story_5075_50750301_19_dialog_content = "使者様のためにお持ちいたしました。",
  ui_story_5075_50750301_20_dialog_content = "ありがとうございます。あれ？\nまだ温かいですね。",
  ui_story_5075_50750301_21_dialog_content = "皓津は穏やかな気候に恵まれているとはいえ、\n今は冬でございます。",
  ui_story_5075_50750301_22_dialog_content = "おいしく召し上がっていただけるよう、\nおかもちの底に炉を入れて温めているのでございます。",
  ui_story_5075_50750301_23_dialog_content = "こうした炉は鄴の国から伝わったものでございます。",
  ui_story_5075_50750301_24_dialog_content = "宮廷様式の炉の内側に、さらに彫刻を施し、\n置物としても用いられるようになっております。",
  ui_story_5075_50750301_25_dialog_content = "内側に？見えない所に彫刻を施してあるんですか？",
  ui_story_5075_50750301_26_dialog_content = "ある貴人がおっしゃっていました…\n見えないからこそ、何をするにも都合がよいと。",
  ui_story_5075_50750301_27_dialog_content = "え？",
  ui_story_5075_50750301_28_dialog_content = "ただの独り言でございます。\nそれでは、ゆっくりとお召し上がりくださいませ。",
  ui_story_5075_50750301_29_dialog_content = "今すぐお召し上がりになりますか？\n他にも何かお作りいたしましょうか？",
  ui_story_5075_50750301_30_dialog_content = "いや、大丈夫です。ちょっと眠いので昼寝することにします。\n皆さんも戻っていいですよ。",
  ui_story_5075_50750301_31_dialog_content = "あ、お菓子は置いていってください。\n起きたら食べるので。",
  ui_story_5075_50750301_32_dialog_content = "かしこまりました。",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>炉からかすかに煙があがり、\n重なり合う銅片の隙間からは揺れる炎が垣間見える</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>カチャ。</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>炎が消えたかと思うと、重なり合っていた銅片が突如ハラハラと開き――</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>卓上に小さな美しいカイドウの花が咲いた。</color>",
  ui_story_5075_50750301_37_dialog_content = "中に札と紙切れがあるみたい？",
  ui_story_5075_50750301_38_dialog_content = "使者様にとって幸福な滞在となり、\n灼華郡主殿下にもご満足いただけるようお祈り申し上げております。",
  ui_story_5075_50750301_39_dialog_content = "侍女頭さんはタンドウからの伝言を伝えに来たんだ！",
  ui_story_5075_50750301_40_dialog_content = "（札には「巡検司」って書いてある…何に使うんだろう？）",
  ui_story_5075_50750301_41_dialog_content = "（紙切れは…地図だ！しかも印が付けてある！）",
  ui_story_5075_50750301_42_dialog_content = "（ちょうど侍女の皆には下がってもらったところだし、\n今のうちに抜け出そう！）",
  ui_story_5075_50750301_43_option_content = "感知",
  ui_story_5075_50750301_44_dialog_content = "（近くにいる護衛は…東側に2人、南側に3人…西側から抜け出そう！）",
  ui_story_5075_50750301_45_dialog_content = "おい、大変だ！使者様がいないぞ！",
  ui_story_5075_50750301_46_dialog_content = "お前はここに残れ。俺はあっちを探してくる！",
  ui_story_5075_50750301_47_dialog_content = "（あっという間に見つかっちゃった…\nでももう庭の端まで来てるから、あとは塀を越えれば…）",
  ui_story_5075_50750301_48_dialog_content = "…高っっ！",
  ui_story_5075_50750301_49_dialog_content = "使者様！どちらですか、使者様――",
  ui_story_5075_50750301_50_dialog_content = "（まずい、囲まれちゃう…何とかしないと…）",
  ui_story_5075_50750301_51_dialog_content = "かくれんぼをしておるのか？",
  ui_story_5075_50750301_52_dialog_content = "誰！？",
  ui_story_5075_50750301_53_dialog_content = "ここじゃ、ここじゃ。",
  ui_story_5075_50750301_54_dialog_content = "上じゃよ。",
  ui_story_5075_50750301_55_dialog_content = "え？子ども？どうして塀の上に…危ないよ！",
  ui_story_5075_50750301_56_dialog_content = "危なくなどないぞ。\nわらわは綱の上でも難なく歩けるのじゃ。",
  ui_story_5075_50750301_57_dialog_content = "おぬし、問いに答えぬか。\nかくれんぼをしておるのか？わらわも入れてたも。",
  ui_story_5075_50750301_58_dialog_content = "いや、遊んでるわけじゃないんだ…",
  ui_story_5075_50750301_59_dialog_content = "使者様？そこにいらっしゃるのですか？",
  ui_story_5075_50750301_60_dialog_content = "まずい！ごめん、今時間ないんだ！行くね――",
  ui_story_5075_50750301_61_dialog_content = "！",
  ui_story_5075_50750301_62_dialog_content = "あ、その…ちょっと散歩しに出てきただけで…",
  ui_story_5075_50750301_63_dialog_content = "使者様？どこにいらっしゃるのですか？",
  ui_story_5075_50750301_64_dialog_content = "？",
  ui_story_5075_50750301_65_dialog_content = "こっちにもいないぞ。いったいどこへ行かれたんだ？",
  ui_story_5075_50750301_66_dialog_content = "使者様――",
  ui_story_5075_50750301_67_dialog_content = "やはり、かくれんぼをしておるではないか。",
  ui_story_5075_50750301_68_dialog_content = "今…護衛たちには僕が見えてなかったみたいだけど…\nまさか君がやったの？",
  ui_story_5075_50750301_69_dialog_content = "ふふっ、ちと戯れてみたのじゃ。",
  ui_story_5075_50750301_70_dialog_content = "？",
  ui_story_5075_50750301_71_dialog_content = "？",
  ui_story_5075_50750301_72_dialog_content = "何をしておるんじゃ？",
  ui_story_5075_50750301_73_dialog_content = "かような時は、シンゲイ様の勇ましい行いに感激のあまり涙を流し、\n頭を垂れて敬服を表すものじゃろ。",
  ui_story_5075_50750301_74_dialog_content = "勇ましい…？",
  ui_story_5075_50750301_75_dialog_content = "コホン。どうして、こんなことを？",
  ui_story_5075_50750301_76_dialog_content = "ここへ来る途中、橋のたもとの語り部が話しておったのじゃ。",
  ui_story_5075_50750301_77_dialog_content = "今、流行っておるのじゃろう？",
  ui_story_5075_50750301_78_dialog_content = "その物語の中で流行ってたってだけだと思うけど…",
  ui_story_5075_50750301_79_dialog_content = "それはそうと、君って――",
  ui_story_5075_50750301_80_dialog_content = "確かにこの辺りで音がしたんだが…",
  ui_story_5075_50750301_81_dialog_content = "しかし、さっき探したばかりだ…\nいやいや、念のためもう一度探しておこう。",
  ui_story_5075_50750301_82_dialog_content = "そ、そうなんだ！実はかくれんぼしてるんだ！",
  ui_story_5075_50750301_83_dialog_content = "勇ましいシンゲイ様、お願いだから、\n逃げるのを手伝ってくれないかな？",
  ui_story_5075_50750301_84_dialog_content = "ふむ。おぬし、なかなか口がうまいのう。",
  ui_story_5075_50750301_85_dialog_content = "安心するがよい。かくれんぼは得意じゃ。",
  ui_story_5075_50750301_86_dialog_content = "秘訣は、一気に片をつけることじゃ。",
  ui_story_5075_50750302_1_dialog_content = "はぁ…はぁ…はぁ…",
  ui_story_5075_50750302_2_dialog_content = "き、君は…か、かくれんぼを…誤解してるね…",
  ui_story_5075_50750302_3_dialog_content = "あり得ぬ。",
  ui_story_5075_50750302_4_dialog_content = "無事外へ出られたではないか。",
  ui_story_5075_50750302_5_dialog_content = "途中気づかれんかったしのう。",
  ui_story_5075_50750302_6_dialog_content = "そうじゃなくて…堂々と一気に飛び出してくるのは、\nかくれんぼとは言わないんだよ…",
  ui_story_5075_50750302_7_dialog_content = "それに、誰にも僕たちのことが見えてないなんて、\nかくれんぼとしてはズルだよ。",
  ui_story_5075_50750302_8_dialog_content = "…あ、でも…よく考えてみたら、本当に助かったよ。",
  ui_story_5075_50750302_9_dialog_content = "ありがとう、シンゲイ…様？",
  ui_story_5075_50750302_10_dialog_content = "ハハハ、共に遊んだ仲ではないか。\n「様」などつけずともよい。",
  ui_story_5075_50750302_11_dialog_content = "うん、分かった。僕はPlayerName。実は僕…",
  ui_story_5075_50750302_12_dialog_content = "空の末裔であろう？",
  ui_story_5075_50750302_13_dialog_content = "知っておるぞ。",
  ui_story_5075_50750302_14_dialog_content = "えっ？",
  ui_story_5075_50750302_15_dialog_content = "使者様？こちらにいらしたのですか！？",
  ui_story_5075_50750302_16_dialog_content = "早くここから離れなきゃ。",
  ui_story_5075_50750302_17_dialog_content = "使者様！やはり使者様でいらっしゃいましたか！",
  ui_story_5075_50750302_18_dialog_content = "護衛も連れず、なぜお独りなのです？\n危険ではありませんか。",
  ui_story_5075_50750302_19_dialog_content = "誰か！",
  ui_story_5075_50750302_20_dialog_content = "待ってください。護衛は必要――",
  ui_story_5075_50750302_21_dialog_content = "チュー！",
  ui_story_5075_50750302_22_dialog_content = "きゃあっ――！ネズミ！た…助けて！",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>シュッ！</color>",
  ui_story_5075_50750302_24_dialog_content = "きゅああああ！祟霊よ…祟霊に咬みつかれた！",
  ui_story_5075_50750302_25_dialog_content = "…シーッ。大きな声を出すでない。",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>ドン</color>",
  ui_story_5075_50750302_27_dialog_content = "何をしたの？",
  ui_story_5075_50750302_28_dialog_content = "ちと眠らせただけじゃ。",
  ui_story_5075_50750302_29_dialog_content = "それと、こやつもな。",
  ui_story_5075_50750302_30_dialog_content = "チュー…",
  ui_story_5075_50750302_31_dialog_content = "どう見ても、普通のネズミじゃないよね…",
  ui_story_5075_50750302_32_dialog_content = "リンセイたちが前に話してくれた、人の姿になってない祟霊かな？",
  ui_story_5075_50750302_33_dialog_content = "それに…なんだか嫌な感じがする…\nまさか、狂暴化してるの？",
  ui_story_5075_50750302_X33_dialog_content = "急報によれば、先刻の地震の後、\n突如として近海に狂暴化した祟霊が現れ、人を襲ったようです。",
  ui_story_5075_50750302_34_dialog_content = "ほう、分かるのか？",
  ui_story_5075_50750302_35_dialog_content = "ならば、これも分かるであろ？",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>シンゲイが倒れていた祟霊の身体の上の宙をさっと指で撫でると、\n祟霊の身体の中から、黒い気の塊のようなものが出てきた</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>混濁した煙のようでもあり、\n凝縮した悪意の気配がかすかに伝わってくる。</color>",
  ui_story_5075_50750302_38_option_content = "感知を試す",
  ui_story_5075_50750302_39_dialog_content = "…ニクイ…",
  ui_story_5075_50750302_40_dialog_content = "うっ――",
  ui_story_5075_50750302_41_dialog_content = "感知してみたけど、腐食した液体に触れた時みたいな痛みがあった…\nそれは、いったい何なの？",
  ui_story_5075_50750302_42_dialog_content = "執念深き、悪しきものじゃ。",
  ui_story_5075_50750302_43_dialog_content = "気を付けて！動き出したよ！たぶん、逃げる気だ！",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>しかし、少女は顔色一つ変えず――</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>軽く指をすり合わせると、あれほど荒れ狂った様子だった黒い気が、\nまるでロウソクの火のように跡形もなく消えてしまった</color>",
  ui_story_5075_50750302_46_dialog_content = "まったく。わらわが一睡もせず城内へ駆け付けたのは、\nかようなものを片付けるためではないというに。",
  ui_story_5075_50750302_47_dialog_content = "PlayerName、おぬしは1人でかくれんぼでもしておれ。\nわらわは他に用があるのじゃ。",
  ui_story_5075_50750302_48_dialog_content = "待って――",
  ui_story_5075_50750302_49_dialog_content = "倒れてる1人と1匹はどうしたら…？",
  ui_story_5075_50750302_50_dialog_content = "おやおや、あと片付けを忘れてしもうた。",
  ui_story_5075_50750302_51_dialog_content = "よいしょ。",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>少女は侍女の肩を起こすと、迎賓館まで「飛ばし」届けた</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>次に祟霊の尻尾を持ったかと思うと、\n空の彼方へ飛ばしてしまった</color>",
  ui_story_5075_50750302_54_dialog_content = "だ、大丈夫かな！？",
  ui_story_5075_50750302_55_dialog_content = "大丈夫じゃ。祟霊はおぬしの思うほど弱くはないぞ。",
  ui_story_5075_50750302_56_dialog_content = "これしきのことに耐えられぬようなら、修行などやめて、\n生涯動物として生きればよいのじゃ。",
  ui_story_5075_50750302_57_dialog_content = "さっき感知した時、似てるって思ったんだけど、\nその変わった風貌からして…",
  ui_story_5075_50750302_58_dialog_content = "君も、祟霊だよね？",
  ui_story_5075_50750302_59_dialog_content = "あれ？どこ行ったの？",
  ui_story_5075_50750302_60_dialog_content = "黒い気のことを聞きたかったんだけど…まぁ、仕方ないか。",
  ui_story_5075_50750302_61_dialog_content = "調査を続けていれば、また会えるかもしれない。",
  ui_story_5075_50750302_62_dialog_content = "まずは、紙に書いてあった住所の場所へ行ってみよう。",
  ui_story_5075_50750302_63_dialog_content = "…",
  ui_story_5075_50750401_1_dialog_content = "春新節に、ポンカンはいかがですか～？",
  ui_story_5075_50750401_2_dialog_content = "どうぞ試食していってくださ～い！\n甘くなかったら、お代は入りませんよ！",
  ui_story_5075_50750401_3_dialog_content = "ゴマおこしはいかがですか～？\n昔ながらの懐かしい味ですよ。お兄さん、見て行きませんか？",
  ui_story_5075_50750401_4_dialog_content = "にぎやかだなぁ。\nやっぱり自由に見て歩くのは楽しいな。",
  ui_story_5075_50750401_5_dialog_content = "すみません、「魚林街」には、どうやって行けばいいんですか？",
  ui_story_5075_50750401_6_dialog_content = "魚林街か。ずいぶん距離があるね。\nまずはあの人の集まってる橋に向かって進んで、角を過ぎたらまた誰かに聞くといいよ。",
  ui_story_5075_50750401_7_dialog_content = "ありがとうございます。本当に人が多いですね。",
  ui_story_5075_50750401_8_dialog_content = "君はよそから来たのかい？皓津では毎年春新節の間、\n縁日が開かれるからね。人がたくさん集まるんだ。",
  ui_story_5075_50750401_9_dialog_content = "ほら、そこの通りだよ。",
  ui_story_5075_50750401_10_dialog_content = "もう少しすれば、有名な役者の芝居も始まる。\n時間があるなら観ていくといい。",
  ui_story_5075_50750401_11_dialog_content = "ありがとうございます。時間があれば、観てみます。",
  ui_story_5075_50750401_12_dialog_content = "でも、まあ惜しかったね。例年はもっとにぎやかなんだよ。",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5075_50750401_14_dialog_content = "何の音？",
  ui_story_5075_50750401_15_dialog_content = "ああ、子どもたちが爆竹を鳴らして遊んでるんだよ。",
  ui_story_5075_50750401_16_dialog_content = "これじゃ足りないよ。もっと鳴らそう！",
  ui_story_5075_50750401_17_dialog_content = "祟獣も悪運も、飛んでけ～！",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>バンッ！バンッ！</color>",
  ui_story_5075_50750401_19_dialog_content = "ハハハハハ！",
  ui_story_5075_50750401_20_dialog_content = "チュー…",
  ui_story_5075_50750401_21_dialog_content = "遊んでる？道でこんなことしたら、危ないですよ！",
  ui_story_5075_50750401_22_dialog_content = "それに、あの祟霊は暴れてないし…\n人を襲う気はまったくありませんよ。",
  ui_story_5075_50750401_23_dialog_content = "だとしても、構わないじゃないか。そもそも春新節には、\n爆竹を鳴らして、祟霊を祓うのが伝統だからね。",
  ui_story_5075_50750401_24_dialog_content = "ただ、普通は商家が演者を雇って儀式をするんだが、\nあの子たちは実際の祟霊を祓ってるってだけのことさ。",
  ui_story_5075_50750401_25_dialog_content = "今までは、あんなのただの儀式だと思ってたが、\nここのところ、世の中穏やかじゃないしなぁ。",
  ui_story_5075_50750401_26_dialog_content = "祟霊ってのは、本当に不吉なモンなんだろうな。",
  ui_story_5075_50750401_27_dialog_content = "あんたはよそ者らしいが、ああいう生き物には関わらないのが一番だよ。\nおっと、俺はそろそろ行かないと。",
  ui_story_5075_50750401_28_dialog_content = "あれ、動かなくなっちゃったよ？死んじゃったのかな…？",
  ui_story_5075_50750401_29_dialog_content = "もっと爆竹を鳴らす？",
  ui_story_5075_50750401_30_dialog_content = "こんなの良くないよ。いくらなんでもひどすぎる。",
  ui_story_5075_50750401_31_dialog_content = "！",
  ui_story_5075_50750401_32_dialog_content = "（黒い気だ…しかも、あの祟霊の方に集まってる！）",
  ui_story_5075_50750401_33_dialog_content = "あぶない！",
  ui_story_5075_50750401_34_dialog_content = "え？何するのよ！",
  ui_story_5075_50750401_35_dialog_content = "…",
  ui_story_5075_50750401_36_dialog_content = "こいつ…なんか、様子がおかしいよ？",
  ui_story_5075_50750401_37_dialog_content = "チュー！",
  ui_story_5075_50750401_38_dialog_content = "大変だ、間に合わない――",
  ui_story_5075_50750401_39_dialog_content = "頭突きを食らえ！",
  ui_story_5075_50750401_40_dialog_content = "チューッ――",
  ui_story_5075_50750401_41_dialog_content = "頭突きって…本当に頭で祟霊を突き飛ばしちゃった？",
  ui_story_5075_50750401_42_dialog_content = "気を付けろ、戻ってきたぞ！",
  ui_story_5075_50750402_1_dialog_content = "チュー…",
  ui_story_5075_50750402_2_dialog_content = "よし、これでもう大丈夫だ。\nおい、大人しくしてろ。それ以上ケガしたらどうすんだ。",
  ui_story_5075_50750402_3_dialog_content = "チューチューッ！",
  ui_story_5075_50750402_4_dialog_content = "さっきはあんたが助けてくれたんだな？\nすごいじゃないか、感謝するよ。",
  ui_story_5075_50750402_5_dialog_content = "見てたぞ。あんた、この祟霊を助けようとしてたな。\nいい奴じゃないか！",
  ui_story_5075_50750402_6_dialog_content = "あはは…僕は何もしてないよ。その子を捕まえたのは君だし。",
  ui_story_5075_50750402_7_dialog_content = "それにしても、君は動きが速いね。\n見てた人たちはたぶん、何が起きたのか分からなかったんじゃないかな。",
  ui_story_5075_50750402_8_dialog_content = "これが俺の生業だからな。",
  ui_story_5075_50750402_9_dialog_content = "そういや、自己紹介してなかったな。俺はラショウだ。\n各地を行脚する道士さ。",
  ui_story_5075_50750402_10_dialog_content = "チュー！",
  ui_story_5075_50750402_11_dialog_content = "普段はあちこちを巡りながら、妖魔退治をしてる。",
  ui_story_5075_50750402_12_dialog_content = "チューチューッ！",
  ui_story_5075_50750402_13_dialog_content = "ここんとこ、この辺りの祟霊が何かっつーと理性を失って、\n暴れ出してはヒトを傷つけてるんだ。",
  ui_story_5075_50750402_14_dialog_content = "原因を探ろうと、城内までやってきたんだが、\nまさか、防御の堅い皓津まで…",
  ui_story_5075_50750402_15_dialog_content = "チューチューッ！！",
  ui_story_5075_50750402_16_dialog_content = "あの…その祟霊、何か様子がおかしくないかな？",
  ui_story_5075_50750402_17_dialog_content = "ああ、確かにな。捕まってからずっと、\n暴れまくって俺に咬みつこうとしてやがる。",
  ui_story_5075_50750402_18_dialog_content = "気を付けて。",
  ui_story_5075_50750402_19_dialog_content = "なぁに大丈夫さ。俺は祟霊でメシを食ってるんだ。",
  ui_story_5075_50750402_20_dialog_content = "こういう祟霊はな、人差し指と親指で首根っこをつかんで、\n爪をこうして、それから…",
  ui_story_5075_50750402_21_dialog_content = "力入れてつかんでりゃ、逃げやしないさ！",
  ui_story_5075_50750402_22_dialog_content = "そうだったんだ。さすが専門家だね。",
  ui_story_5075_50750402_23_dialog_content = "…いや、違う。問題はそこじゃない。",
  ui_story_5075_50750402_24_dialog_content = "ちょっと感知してみる…",
  ui_story_5075_50750402_25_dialog_content = "やっぱり…あのおかしな黒い気が\nこの祟霊の身体の中に残ったままだ。",
  ui_story_5075_50750402_26_dialog_content = "おかしな黒い気？",
  ui_story_5075_50750402_27_dialog_content = "うん、僕にはそういうものが見えるんだよ。\nたぶん、祟霊たちはその黒い気のせいで狂暴化してるんだと思う。",
  ui_story_5075_50750402_28_dialog_content = "だったら、まさに俺の専門分野じゃねーか。\n偉いお方を呼ばなきゃならないかもしれないな。",
  ui_story_5075_50750402_29_dialog_content = "その黒い気ってのは、力いっぱい殴れば出ていくのか？",
  ui_story_5075_50750402_30_dialog_content = "たぶん、無理だよ。",
  ui_story_5075_50750402_31_dialog_content = "ただ、ちょっと前にある女の子に会ったんだけど――",
  ui_story_5075_50750402_32_dialog_content = "ちょっと！突然飛び出してきて、\n何をごちゃごちゃ話してるんだよ！？",
  ui_story_5075_50750402_33_dialog_content = "おっと、忘れてた。ガキどもがいたな。",
  ui_story_5075_50750402_34_dialog_content = "それと…あんたの名前は？",
  ui_story_5075_50750402_35_dialog_content = "僕？僕はPlayerNameっていうんだ。",
  ui_story_5075_50750402_36_dialog_content = "そうか、PlayerNameか。ちょっとこいつを捕まえててくれないか？",
  ui_story_5075_50750402_37_dialog_content = "えっ？",
  ui_story_5075_50750402_38_dialog_content = "チュー！",
  ui_story_5075_50750402_39_dialog_content = "うわあっ！祟霊を投げないでよ…ううっ、すごい暴れようだ。",
  ui_story_5075_50750402_40_dialog_content = "（ラショウが捕まえてた時はあんなに大人しかったのに…\nいったいどれだけ力が強いんだろう…あ、動かないで！）",
  ui_story_5075_50750402_41_option_content = "強制感知！",
  ui_story_5075_50750402_42_dialog_content = "チュー…",
  ui_story_5075_50750402_43_dialog_content = "ふぅ…やっと大人しくなってくれた。",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>パチンッ！パチンッ！</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>ラショウは罰として、子どもたちにデコピンを食らわせた。</color>",
  ui_story_5075_50750402_46_dialog_content = "（ただのデコピンだけど、ラショウの力でやられたら…\nどれだけ痛いんだろう…）",
  ui_story_5075_50750402_47_dialog_content = "うわあああ――",
  ui_story_5075_50750402_48_dialog_content = "なんだよっ！なんで急にデコピンするんだよ！痛いじゃないか！",
  ui_story_5075_50750402_49_dialog_content = "俺は逃げも隠れもしない、道士ラショウだ。",
  ui_story_5075_50750402_50_dialog_content = "正々堂々、正しく生きているから、\n恐れるものなど何もない。",
  ui_story_5075_50750402_51_dialog_content = "だが、お前たちは正々堂々名乗れるか？\nお前たちの親に話をしに行きたいんだが。",
  ui_story_5075_50750402_52_dialog_content = "ガキどもが街なかで爆竹を鳴らし、\n弱い者いじめをするのを放っておくとは何事だってな。",
  ui_story_5075_50750402_53_dialog_content = "ぼ、僕は…",
  ui_story_5075_50750402_54_dialog_content = "いや…なんで名乗らなきゃいけないんだよ？",
  ui_story_5075_50750402_55_dialog_content = "父さんと母さんが言ってたんだ。祟霊たちが悪いものを運んできたから、\n最近妖魔があちこちに出るようになったんだって。",
  ui_story_5075_50750402_56_dialog_content = "お前は祟霊の仲間だ、悪い奴に決まってる！",
  ui_story_5075_50750402_57_dialog_content = "ンなのは、ただの迷信だろ。",
  ui_story_5075_50750402_58_dialog_content = "どうあろうと、やっちゃいけねーことはやっちゃいけねーんだ。\n他人の言ったことを、言い分けに使うな。",
  ui_story_5075_50750402_59_dialog_content = "お前はその目で、祟霊が妖魔を連れて来たのを見たのか？",
  ui_story_5075_50750402_60_dialog_content = "それは…見てないけど、\nあの祟霊は僕たちのお菓子を盗ったんだよ！",
  ui_story_5075_50750402_61_dialog_content = "みんなでお小遣いを集めて買ったのに、\nちょっと目を離したスキになくなってたんだ。",
  ui_story_5075_50750402_62_dialog_content = "そうよ、そうよ！",
  ui_story_5075_50750402_63_dialog_content = "モノを盗るのは悪いヤツよ。\nあたしたちは悪者を成敗したんだから！",
  ui_story_5075_50750402_64_dialog_content = "「目を離した隙に」ってことは、\nあいつが盗ったとこを見たわけじゃないんだな。",
  ui_story_5075_50750402_65_dialog_content = "でも、あの時近くをあいつが通り過ぎたんだ。\nあいつ以外に犯人はいないじゃないか！",
  ui_story_5075_50750402_66_dialog_content = "PlayerName。",
  ui_story_5075_50750402_67_dialog_content = "その祟霊の口元に蜜がついてないか見てくれないか？",
  ui_story_5075_50750402_68_dialog_content = "ええと…ついてないよ。",
  ui_story_5075_50750402_69_dialog_content = "身体にも傷口と泥しかついてない。他には何もないね。",
  ui_story_5075_50750402_70_dialog_content = "だからって、犯人じゃないってことにはならないよ！",
  ui_story_5075_50750402_71_dialog_content = "法術を使って、シュッてお菓子をどこかに運んじゃったのかもしれない。",
  ui_story_5075_50750402_72_dialog_content = "うーん、そんなことができるなら、\nわざわざ盗む必要ないんじゃないかな？",
  ui_story_5075_50750402_73_dialog_content = "お菓子って、どんなお菓子だ？",
  ui_story_5075_50750402_74_dialog_content = "どんなって…白くて、丸くて、まるで…",
  ui_story_5075_50750402_75_dialog_content = "皮をむいたポンカンみたいなやつか？",
  ui_story_5075_50750402_76_dialog_content = "そうだよ！見るからにおいしそうなお菓子だ。\n祟霊もきっとそう思うに決まってる。",
  ui_story_5075_50750402_77_dialog_content = "この近くの、あの爺さんの店で買ったんだろ？",
  ui_story_5075_50750402_78_dialog_content = "小遣いを持ち寄って買ったってなら、\n他のもんは買えないはずだ。",
  ui_story_5075_50750402_79_dialog_content = "だが、ガキってのは食いしん坊だからな。\nちょうど菓子売りの隣じゃ、ポンカンの試食ができる。",
  ui_story_5075_50750402_80_dialog_content = "食いに行ったろ？",
  ui_story_5075_50750402_81_dialog_content = "行ったよ。だからなんだっていうの？",
  ui_story_5075_50750402_82_dialog_content = "ポンカンを食ってる時、菓子はどこに置いたんだ？",
  ui_story_5075_50750402_83_dialog_content = "もちろん、果物屋さんの…あ！",
  ui_story_5075_50750402_84_dialog_content = "本当だ、あたしたちのお菓子だよ。\n皮をむいたポンカンの中にあった！",
  ui_story_5075_50750402_85_dialog_content = "…",
  ui_story_5075_50750402_86_dialog_content = "そういうことだ。",
  ui_story_5075_50750402_87_dialog_content = "お前たち、何か言う事はないのか？",
  ui_story_5075_50750402_88_dialog_content = "ごめんなさい…",
  ui_story_5075_50750402_89_dialog_content = "今度同じようなことがあったら、\nまずはよく自分たちの行動を振り返るんだぞ。",
  ui_story_5075_50750402_90_dialog_content = "何でも祟霊のせいにすりゃいいわけじゃないんだ。",
  ui_story_5075_50750402_91_dialog_content = "祟霊を傷つければ、菓子が戻ってくんのか？",
  ui_story_5075_50750402_92_dialog_content = "迷信や偏見にとらわれると、\nよく知らねーもんに悪意を抱き、勝手に悪者に仕立てあげちまう…",
  ui_story_5075_50750402_93_dialog_content = "そうなると、ただ騒ぎ立てるしか能がなくなるんだよ。",
  ui_story_5075_50750402_94_dialog_content = "そんなの悪者成敗でも何でもない、ただの卑怯者だ。分かったか？",
  ui_story_5075_50750402_95_dialog_content = "うん…",
  ui_story_5075_50750402_96_dialog_content = "分かったなら、家に帰れ。\n父さんと母さんにも、今日の事を話しておけよ。",
  ui_story_5075_50750402_97_dialog_content = "わかった…",
  ui_story_5075_50750402_98_dialog_content = "あの子たち、本当に親に話すかな？",
  ui_story_5075_50750402_99_dialog_content = "たぶん、話さないだろ。",
  ui_story_5075_50750402_100_dialog_content = "俺だってあんな話したって、\n何の解決にもならねーってことは分かってるさ。",
  ui_story_5075_50750402_101_dialog_content = "だが「祟霊は不吉だ」ってウソも、\nそう口にする奴らが増えれば、信じる奴が出てくる。",
  ui_story_5075_50750402_102_dialog_content = "だが、俺の言ったことは本当だ。\n言い続ければ、いつか信じる奴が必ず出てくる。",
  ui_story_5075_50750402_103_dialog_content = "何しろ、本当のことだからな。ウソは所詮ウソだ。",
  ui_story_5075_50750402_104_dialog_content = "ラショウはすごいね。",
  ui_story_5075_50750402_105_dialog_content = "お菓子がどこにあるのかも、あっという間に当てちゃったし。\nまるで、現場を見てたみたいだったよ。",
  ui_story_5075_50750402_106_dialog_content = "ははは、それはな…",
  ui_story_5075_50750402_107_dialog_content = "実際見てたんだよ。俺じゃないがな。",
  ui_story_5075_50750402_108_dialog_content = "そうだ…あんた、俺の妖魔退治の仲間に会ってみたくないか？",
  ui_story_5075_50750402_109_dialog_content = "ガオー！",
  ui_story_5075_50750402_110_dialog_content = "仲間って、祟霊なの？",
  ui_story_5075_50750402_111_dialog_content = "アテイっていうんだ。",
  ui_story_5075_50750402_112_dialog_content = "さっきのガキどもが菓子を忘れてったとこをこいつが見てて、\n俺に教えてくれたんだ。",
  ui_story_5075_50750402_113_dialog_content = "最初は菓子をガキどもに返して、本当のことを教えてしまいに\nしようと思ったんだが、アメ細工の職人に止められてな。",
  ui_story_5075_50750402_114_dialog_content = "今、城内の奴らは祟霊を敵視してるから、\nアテイを連れて行ったら、大変なことになるかもしれねーってな。",
  ui_story_5075_50750402_115_dialog_content = "それで、アテイをここで待たしといたんだ。",
  ui_story_5075_50750402_116_dialog_content = "さっきの推理も、その職人が教えてくれたのさ。",
  ui_story_5075_50750402_117_dialog_content = "今思えば、その通りだったな。",
  ui_story_5075_50750402_118_dialog_content = "礼を言いに行かなきゃな。ついでにアメ細工でも買って、\n隠れてるアテイの仲間にやるとするか。",
  ui_story_5075_50750402_119_dialog_content = "まさかとは思うけど…\nラショウの言うアメ細工の職人さんって、あそこにいるあの人？",
  ui_story_5075_50750402_120_dialog_content = "ああ、そうだよ。",
  ui_story_5075_50750402_121_dialog_content = "あんたはここで待っててくれ。\n俺はちっこいのに挨拶したら、すぐ戻ってくる。",
  ui_story_5075_50750402_122_dialog_content = "…",
  ui_story_5075_50750402_123_dialog_content = "アメ細工の職人さん？",
  ui_story_5075_50750402_124_dialog_content = "おや旦那、アメ細工はいかがです？",
  ui_story_5075_50750500_1_dialog_content = "…占い師じゃなかったの？",
  ui_story_5075_50750500_2_dialog_content = "まさか、このキラキラした透明なアメを見てくださいよ。",
  ui_story_5075_50750500_3_dialog_content = "そして、この精巧な細工！",
  ui_story_5075_50750500_4_dialog_content = "先祖代々伝わる技でしてねぇ。\n何年も修行して、ようやく習得した妙技です。",
  ui_story_5075_50750500_5_dialog_content = "正真正銘、アメ細工職人ですよ。",
  ui_story_5075_50750500_6_dialog_content = "それにしても蜃風号でお別れしてから、ずいぶん経ちますねぇ。",
  ui_story_5075_50750500_7_dialog_content = "ここで会えたのも何かの縁です。\nアメ細工を一つ、お贈りしましょう。",
  ui_story_5075_50750500_8_dialog_content = "疑ってるわけじゃないんだけど…",
  ui_story_5075_50750500_9_dialog_content = "君からは、滅多に物をもらっちゃいけない気がする…",
  ui_story_5075_50750500_10_dialog_content = "おや、それはそれは…",
  ui_story_5075_50750500_11_dialog_content = "知り合って日も浅いというのに、\n僕のことをよくご存じですねぇ。",
  ui_story_5075_50750500_12_dialog_content = "そこまでお見通しってなら、隠すこともありませんねぇ。\nこれ、ちと持っていていただけますか？",
  ui_story_5075_50750500_13_dialog_content = "これは…装飾品だよね。しかも女の子のものだ。",
  ui_story_5075_50750500_14_dialog_content = "旦那が来る少し前に、アメ細工を買ったお客さんが\n落としていったもんです。",
  ui_story_5075_50750500_15_dialog_content = "でも、ここの商売が繁盛してましてねぇ。\n返しに行く時間がないんです。旦那にお願いできませんかねぇ。",
  ui_story_5075_50750500_16_dialog_content = "でも、僕も大事な用事があるんだ。",
  ui_story_5075_50750500_17_dialog_content = "安心してください。占ったところ、お二人は縁があります。",
  ui_story_5075_50750500_18_dialog_content = "旦那は旦那の用を済ませればいいんです。\n途中、必ず会えますよ。",
  ui_story_5075_50750500_19_dialog_content = "やっぱり占い師なんだね。",
  ui_story_5075_50750500_20_dialog_content = "あ、ちょっと待って。よく見ると、これって…\n龍女廟で拾ったのと同じだ。",
  ui_story_5075_50750500_21_dialog_content = "しかも、誰かが付けてたような…",
  ui_story_5075_50750500_22_dialog_content = "まさか…",
  ui_story_5075_50750500_23_dialog_content = "そうだ、テンカンは<color=#FFB400>祟霊</color>について知ってる？",
  ui_story_5075_50750500_24_dialog_content = "もちろんですよ。前にお話しした、我流の八卦<color=#FFB400>「万類天斗卦」</color>を覚えてますか？",
  ui_story_5075_50750500_25_dialog_content = "源をたどれば、龍州で最も崇拝されている<color=#FFB400>13大祟霊</color>と関係があるんですよ。",
  ui_story_5075_50750500_26_dialog_content = "動物じゃなくて？",
  ui_story_5075_50750500_27_dialog_content = "動物、祟霊、神…いずれも具象の仕方が違うだけで同じもんです。",
  ui_story_5075_50750500_28_dialog_content = "シュウの旦那も話してたでしょう？土地を守った祟霊が朝廷から官位を授けられ、\n崇められるようになったって話を。",
  ui_story_5075_50750500_29_dialog_content = "その13名の祟霊ってのは、\n龍州で最も大切にされている13の神でもあるんです。",
  ui_story_5075_50750500_30_dialog_content = "旦那もご存じの<color=#FFB400>「鎮海の龍女」</color>の<color=#FFB400>龍女</color>様もその1人ですよ。",
  ui_story_5075_50750500_31_dialog_content = "ただ、時代も変わり、今や自分たちの祀っている神が\n祟霊だったってことを忘れてしまっただけのことです。",
  ui_story_5075_50750500_32_dialog_content = "少々話がそれましたね。先程の話に戻りましょうか。",
  ui_story_5075_50750500_33_dialog_content = "祟霊ってのは、様々な法術を使うんですが、\n大祟霊、もしくは神ともなると――",
  ui_story_5075_50750500_34_dialog_content = "特に巧妙な法術を使うもんで、\n「神通力」なんて呼ばれるんです。",
  ui_story_5075_50750500_35_dialog_content = "雨を降らすやら、霧や風を起こすなんてことばかりじゃなく、\n身を隠すのも、変身するのも、思うがままにできるらしいですよ。",
  ui_story_5075_50750500_36_dialog_content = "実にうらやましいですねぇ。",
  ui_story_5075_50750500_37_dialog_content = "ということは、あの女の子も…あれ？待って。\n僕さっき祟霊の能力について聞いたっけ？",
  ui_story_5075_50750500_38_dialog_content = "もちろん、聞きましたよ。",
  ui_story_5075_50750500_39_dialog_content = "そう…ただ、その神通力っておそらく高度な光力術ってことだよね。\n僕に感知できるレベルかな？",
  ui_story_5075_50750500_40_dialog_content = "それは、旦那がご自分で<color=#FFB400>神</color>に聞くしかありませんね。",
  ui_story_5075_50750500_41_dialog_content = "実は…神通力とはいきませんがね。\n旦那にも使える呪文を知ってるんです。",
  ui_story_5075_50750500_42_dialog_content = "龍州に古くから伝わるもんでしてね。\n今ちょうど役に立ちますよ。",
  ui_story_5075_50750500_43_dialog_content = "さあ、僕に続いて唱えてみてください。",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>年越しなんだから</color>",
  ui_story_5075_50750500_45_dialog_content = "年越しなんだから。",
  ui_story_5075_50750500_46_dialog_content = "そう、その通りですよ。きっと役に立ちますよ。",
  ui_story_5075_50750500_47_dialog_content = "今の呪文を唱えれば、どんな争いごとも、\nあっという間に円満解決できますよ。",
  ui_story_5075_50750500_48_dialog_content = "こんな簡単な言葉に、そんな効力があるの？",
  ui_story_5075_50750500_49_dialog_content = "古くから伝わる呪文ですからねぇ。甘く見ちゃいけません。",
  ui_story_5075_50750500_50_dialog_content = "この呪文は全部で4つあるんですがね。\n残りの3つは、今の旦那にはちと難しいでしょう。",
  ui_story_5075_50750500_51_dialog_content = "今後機会があれば、その時にゆっくりお教えしますよ。",
  ui_story_5075_50750500_52_dialog_content = "うん、ありがとう！",
  ui_story_5075_50750500_53_dialog_content = "どういたしまして。ただのついでですから。",
  ui_story_5075_50750500_54_dialog_content = "旦那の他のお悩みについては、占って差し上げたいところですが…",
  ui_story_5075_50750500_55_dialog_content = "待たせたな、PlayerName。",
  ui_story_5075_50750500_56_dialog_content = "――時間がありません。",
  ui_story_5075_50750500_57_dialog_content = "占わないの？",
  ui_story_5075_50750500_58_dialog_content = "何の話だ？",
  ui_story_5075_50750500_59_dialog_content = "あ、そうだ！ラショウって各地を行脚する道士なんだよね？\n君も占いができるの？",
  ui_story_5075_50750500_60_dialog_content = "なに？PlayerName、だまされるなよ。",
  ui_story_5075_50750500_61_dialog_content = "運命だ、縁だ、因果だなんてもんは、\nいかにも大そうに聞こえるが――",
  ui_story_5075_50750500_62_dialog_content = "実際には、手品に巧妙な話術を乗せたものにすぎないんだ。",
  ui_story_5075_50750500_63_dialog_content = "えっ？",
  ui_story_5075_50750500_64_dialog_content = "良心に背くことなく、正しい行いをしていれば、\n自然と結果はついてくる。",
  ui_story_5075_50750500_65_dialog_content = "訳の分からねー占いより、自分の拳の方がよっぽど確実だ。",
  ui_story_5075_50750500_66_dialog_content = "（テンカン…）",
  ui_story_5075_50750500_67_dialog_content = "（僕はただのアメ細工職人ですよ）",
  ui_story_5075_50750500_68_dialog_content = "愚かな道士だ。",
  ui_story_5075_50750500_69_dialog_content = "頭が固い。",
  ui_story_5075_50750500_70_dialog_content = "何も分かっちゃいない。",
  ui_story_5075_50750500_71_dialog_content = "面倒なヤツだ。",
  ui_story_5075_50750500_72_dialog_content = "おやおや、なに訳の分からないことを言ってるんでしょうね。\nはははは。",
  ui_story_5075_50750500_73_dialog_content = "…",
  ui_story_5075_50750500_74_dialog_content = "アメ細工がちょうど出来上がりましたよ。",
  ui_story_5075_50750500_75_dialog_content = "ありが…あれ？これは梅の花だよね！？\nアメ細工って人の形を作るんじゃないの？",
  ui_story_5075_50750500_76_dialog_content = "すみませんねぇ。アメが足りなくなりましてねぇ。",
  ui_story_5075_50750500_77_dialog_content = "でも、焦ることはありませんよ。\n詩にもあるでしょう――",
  ui_story_5075_50750500_78_dialog_content = "美人よ美人、暮雨たるか朝雲たるか知れず。\n相い思うこと一夜、梅花発き、忽ち窓前に至りて、疑うらくは是れ君かと。",
  ui_story_5075_50750500_79_dialog_content = "この<color=#FFB400>梅の花</color>も、<color=#FFB400>美人</color>に見えませんか？",
  ui_story_5075_50750500_80_dialog_content = "どう考えても屁理屈でしょ。",
  ui_story_5075_50750500_81_dialog_content = "時には風情ってもんも必要ですよ。",
  ui_story_5075_50750500_82_dialog_content = "とにかく、急ぎ用事を済ませてきてください。\n僕は商売を続けるとします。",
  ui_story_5075_50750500_83_dialog_content = "覚えておいてくださいね。何か迷った時には、\n<color=#FFB400>神様に拝んでみる</color>といいですよ。",
  ui_story_5075_50750500_84_dialog_content = "縁日の舞台では、「鎮海の龍女」をやるそうです。",
  ui_story_5075_50750500_85_dialog_content = "でも、舞台の神様は本物の神様じゃないでしょ？",
  ui_story_5075_50750500_86_dialog_content = "あれ？あれは…黒い気！？",
  ui_story_5075_50750500_87_dialog_content = "ちょっと見てくる！",
  ui_story_5075_50750500_88_dialog_content = "PlayerName、待て！俺も行く――",
  ui_story_5075_50750500_89_dialog_content = "厄介者が去ったところで、これからのことを占ってみましょうかねぇ。",
  ui_story_5075_50750500_90_dialog_content = "おや。",
  ui_story_5075_50750500_91_dialog_content = "舞台の上の神が本物かどうか、\n分からなくなってきたようですねぇ。",
  ui_story_5075_50750601_1_dialog_content = "チュチュッ！",
  ui_story_5075_50750601_2_dialog_content = "静かにしろ。気づかれるぞ。",
  ui_story_5075_50750601_3_dialog_content = "あ、目を覚ましたんだね。",
  ui_story_5075_50750601_4_dialog_content = "縁日に近づけば近づくほど、暴れ出してるみたいだね…",
  ui_story_5075_50750601_5_dialog_content = "あんたの言う黒い気に近づいてるからだろ。",
  ui_story_5075_50750601_6_dialog_content = "思うに、その黒い気にはおそらく浸食性がある。",
  ui_story_5075_50750601_7_dialog_content = "毒みてえに、祟霊の理性をむしばむんだ。",
  ui_story_5075_50750601_8_dialog_content = "だが、残念なことに俺にはそれを祓う手段がない。",
  ui_story_5075_50750601_9_dialog_content = "城外で出くわした同じような祟霊たちも回復してなくてな。\n人のいない所に隠すしかない。",
  ui_story_5075_50750601_10_dialog_content = "この祟霊もそうだ…",
  ui_story_5075_50750601_11_dialog_content = "あんたの話だと、黒い気を抜き取れる女の子がいるそうじゃないか。\nその子を訪ねられないか？",
  ui_story_5075_50750601_12_dialog_content = "実は今日知り合ったばかりで、\n「シンゲイ」って名前だってことくらいしか知らないんだ。",
  ui_story_5075_50750601_13_dialog_content = "でも、すごい力をもった祟霊みたいだった。",
  ui_story_5075_50750601_14_dialog_content = "それ以外の手がかりは、その子が落とした飾りしかなくて。",
  ui_story_5075_50750601_15_dialog_content = "あんな高そうなものを2つも落とすなんて…",
  ui_story_5075_50750601_16_dialog_content = "もしや、金の腕輪か、足輪みたいなものか？",
  ui_story_5075_50750601_17_dialog_content = "え、どうして知ってるの？",
  ui_story_5075_50750601_18_dialog_content = "俺も見たからだ。",
  ui_story_5075_50750601_19_dialog_content = "あんたも受け取ったのかい？\nちょうど今、子どもがうちの肉まんを買ってったんだが――",
  ui_story_5075_50750601_20_dialog_content = "たった1つの肉まんにこんなもんを払って行ったんだよ。",
  ui_story_5075_50750601_21_dialog_content = "これって金だろう？もらえないよって言おうとしたら、\nその子はもういなかったんだ。",
  ui_story_5075_50750601_22_dialog_content = "うちもだ。ただ、俺は姿さえ見なかった。",
  ui_story_5075_50750601_23_dialog_content = "芋の蜜漬けが1杯なくなってると思ったら、\nこの金が置いてあったんだよ。",
  ui_story_5075_50750601_24_dialog_content = "まさか、財運の神様が現れたのか？",
  ui_story_5075_50750601_25_dialog_content = "うーん…それはきっと財運の神様じゃない。",
  ui_story_5075_50750601_26_dialog_content = "重要なのは、そこじゃないでしょ！？",
  ui_story_5075_50750601_27_dialog_content = "お代を金で払う子どもかい？レンコンの蜜漬けを金で払った子なら見たぞ。\n確か奥の方へ行ったよ。",
  ui_story_5075_50750601_28_dialog_content = "そこのお兄さんたち、年画を見て行かないかい？\nどれもこれも手が込んでるよ。",
  ui_story_5075_50750601_29_dialog_content = "金でお代を払う子ども？ああ、覚えてるよ。",
  ui_story_5075_50750601_30_dialog_content = "私の年画をずいぶん気に入ってくれてね。\n特に「鎮海の龍女」は、何枚も買ってくれたな。",
  ui_story_5075_50750601_31_dialog_content = "ちょうどその子が絵を買い終わったくらいの時に、\n舞台の方から声がしたから――",
  ui_story_5075_50750601_32_dialog_content = "舞台でも観に行ったんじゃないかな。",
  ui_story_5075_50750601_33_dialog_content = "さっき別れる時、用事があるって言ってたけど、\n縁日のことだったんだね。",
  ui_story_5075_50750601_34_dialog_content = "しかも、一通り楽しんでる。",
  ui_story_5075_50750601_35_dialog_content = "どのお店もおいしかった！",
  ui_story_5075_50750601_36_dialog_content = "この凍米糖なんて、アストラのお菓子ほど甘くないから、\nかえってもっと食べたくなっちゃう。",
  ui_story_5075_50750601_37_dialog_content = "確かにさすがだな。レンコンの蜜漬けを売ってる店はたくさんあるが、\nこれは甘みも歯ごたえもよくて、絶品だ！",
  ui_story_5075_50750601_38_dialog_content = "アテイ、お前も気にったろ？",
  ui_story_5075_50750601_39_dialog_content = "ガオ～。",
  ui_story_5075_50750601_40_dialog_content = "それはそうと、僕たち何しに来たんだっけ？",
  ui_story_5075_50750601_41_dialog_content = "…",
  ui_story_5075_50750601_42_dialog_content = "…",
  ui_story_5075_50750601_43_dialog_content = "え、縁日って本当に楽しいね。",
  ui_story_5075_50750601_44_dialog_content = "そうだな、ははは…",
  ui_story_5075_50750601_45_dialog_content = "ところで、あんたは気づいたか？",
  ui_story_5075_50750601_46_dialog_content = "あの祟霊だが、さっきから暴れなくなった。\nどうやら、落ち着いたようだ。",
  ui_story_5075_50750601_47_dialog_content = "感知してみるね…",
  ui_story_5075_50750601_48_dialog_content = "周りにあった黒い気もなくなってる！消えたのかな？",
  ui_story_5075_50750601_49_dialog_content = "いや、悪い兆しって可能性もあるぞ。",
  ui_story_5075_50750601_50_dialog_content = "たとえば、どこかに集まっちまったとかな。\n急いで、女の子を探さねーと…",
  ui_story_5075_50750601_51_dialog_content = "あ！PlayerName！",
  ui_story_5075_50750601_52_dialog_content = "あ、よかった！やっと…",
  ui_story_5075_50750601_53_dialog_content = "よいところで会った！友も連れておるのじゃの！",
  ui_story_5075_50750601_54_dialog_content = "ちょうどよい！急いで舞台へ上がるのじゃ！",
  ui_story_5075_50750601_55_dialog_content = "え？どこに上がるって？",
  ui_story_5075_50750601_56_dialog_content = "お前は…いや、あんたは…あ、そうだ。この祟霊が――",
  ui_story_5075_50750601_57_dialog_content = "またか。",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>前回と同様、シンゲイは何気ない様子でさっと軽く手を払うと――</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>祟霊の体内から抜けた黒い気をつぶし、すると黒い気は、\n今まで存在すらしていなかったように消えてしまった</color>",
  ui_story_5075_50750601_60_dialog_content = "チュー！",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>祟霊はシンゲイの足下まで軽快に飛び跳ねていくと、\nお礼を言うかのように頭を下げた</color>",
  ui_story_5075_50750601_62_dialog_content = "やはり、あんたは――",
  ui_story_5075_50750601_63_dialog_content = "われらの番じゃ。急ぐのじゃ！",
  ui_story_5075_50750601_64_dialog_content = "すごい人だ！",
  ui_story_5075_50750601_65_dialog_content = "訳も分からず付いてきちゃったけど、\nこれから、いったい何をするの？",
  ui_story_5075_50750601_66_dialog_content = "<color=#FFB400>鎮海の龍女の舞</color>を舞うのじゃ。",
  ui_story_5075_50750601_67_dialog_content = "皆さん、今日は名優の芝居を楽しみにお集りいただいたことと思います。",
  ui_story_5075_50750601_68_dialog_content = "しかし、ご存じの通り、龍女の舞を最も得意とする役者が、\n足をケガしてしまい、舞台に上がれなくなりました。",
  ui_story_5075_50750601_69_dialog_content = "とはいえ、縁日の間、舞台を空にしておくわけにも参りません。\nそこで、新しい催しを考えました。",
  ui_story_5075_50750601_70_dialog_content = "これから、数名の龍女が順番に舞台に上がり、\nお集りの皆さんに「鎮海の龍女」の舞を披露します。",
  ui_story_5075_50750601_71_dialog_content = "それをご覧になり、皆さんが今年の春新節の龍女を選ぶというのはいかがでしょうか？",
  ui_story_5075_50750601_72_dialog_content = "賛成！",
  ui_story_5075_50750601_73_dialog_content = "PlayerNameが友を連れてきたおかげで、\n人数がそろったわい。",
  ui_story_5075_50750601_74_dialog_content = "おぬしの友には、海を荒らし、\n人を襲うクロミズチを演じてもらおう。",
  ui_story_5075_50750601_75_dialog_content = "わらわは龍女じゃ。",
  ui_story_5075_50750601_76_dialog_content = "じゃあ、僕は？",
  ui_story_5075_50750601_77_dialog_content = "PlayerName、心して演じるのじゃぞ。\nおぬしの役柄が一番の要じゃ。",
  ui_story_5075_50750601_78_dialog_content = "<size=50>海じゃ！</size>",
  ui_story_5075_50750601_79_dialog_content = "海って…必要あるかな？",
  ui_story_5075_50750601_80_dialog_content = "何を言うておる！？重要ではないか！",
  ui_story_5075_50750601_81_dialog_content = "音曲が始まった、舞うのじゃ！",
  ui_story_5075_50750601_82_dialog_content = "ららら～。",
  ui_story_5075_50750601_83_dialog_content = "「天命を受けし龍女は降臨し、兆を生む」",
  ui_story_5075_50750601_84_dialog_content = "「万里の海は広く、煙波は浩渺なり」",
  ui_story_5075_50750601_85_dialog_content = "（おい、海よ。おぬしの広大さと霧の漂う水面を示さぬか！）",
  ui_story_5075_50750601_86_dialog_content = "（目配せしたって無理なものは無理なんだけど！\nと、とにかく…波のマネをしなきゃ…）",
  ui_story_5075_50750601_87_dialog_content = "「天命を受けし龍女は…」",
  ui_story_5075_50750601_88_dialog_content = "…",
  ui_story_5075_50750601_89_dialog_content = "（あれ…？まさか…台詞を忘れた！？）",
  ui_story_5075_50750601_90_dialog_content = "「百禄多福なり」だよ！次は「百禄多福なり」！",
  ui_story_5075_50750601_91_dialog_content = "（ああ、ダメだ。もう音楽が過ぎちゃった…\nどうしよう…この後の台詞も覚えてないだろうし…）",
  ui_story_5075_50750601_92_dialog_content = "「災いの蛟世に降りて、日月に光なし」",
  ui_story_5075_50750601_93_dialog_content = "（ラショウ！？）",
  ui_story_5075_50750601_94_dialog_content = "「霹靂が轟き、雷光走る」",
  ui_story_5075_50750601_95_dialog_content = "（身体の動きは固いし、台詞も違うけど、\nなんとかつないでくれた！よかった！）",
  ui_story_5075_50750601_96_dialog_content = "（ただ…どうして止まっちゃうの？）",
  ui_story_5075_50750601_97_dialog_content = "（さあ、来い！霹靂と雷光！）",
  ui_story_5075_50750601_98_dialog_content = "（僕の番ってこと！？）",
  ui_story_5075_50750601_99_dialog_content = "（と、とにかく、雷のマネをしなきゃ！）",
  ui_story_5075_50750601_100_dialog_content = "ゴロゴロゴロ――！",
  ui_story_5075_50750601_101_dialog_content = "「妖魔が横行し、罪なき人々は苦しみに悶える」",
  ui_story_5075_50750601_102_dialog_content = "「幸いにも龍女あり、民のため悪を祓う」",
  ui_story_5075_50750601_103_dialog_content = "「その力は強く、その志は堅し」",
  ui_story_5075_50750601_104_dialog_content = "「その拳で、天下を鎮める！」",
  ui_story_5075_50750601_105_dialog_content = "（どこの龍女が拳で世を鎮めるっていうの！？）",
  ui_story_5075_50750601_106_dialog_content = "（それに、君はクロミズチだよ。役がごちゃ混ぜになってる！）",
  ui_story_5075_50750601_107_dialog_content = "グガァ！",
  ui_story_5075_50750601_108_dialog_content = "（災害級にひどい演技だ…でも、暗鬼だけは迫真の演技だなぁ…）",
  ui_story_5075_50750601_109_dialog_content = "（いや、そうじゃない！）",
  ui_story_5075_50750601_110_dialog_content = "本物の暗鬼だ！",
  ui_story_5075_50750602_1_dialog_content = "ありがとうございました。その…なんとも…",
  ui_story_5075_50750602_2_dialog_content = "個性的と申しますか…風変わりな…鎮海の龍女でございました。",
  ui_story_5075_50750602_3_dialog_content = "座長さん、ひどい顔色だね…\n僕たちの演技、そんなにひどかったかな。",
  ui_story_5075_50750602_4_dialog_content = "いや、妖魔に舞台の半分を壊された衝撃の方がでかいんだろう。",
  ui_story_5075_50750602_5_dialog_content = "龍州では、城内に暗鬼が現れることは\nほとんどないんじゃなかったの？",
  ui_story_5075_50750602_6_dialog_content = "狂暴化した祟霊、城内に現れた暗鬼、それから奇妙な黒い気…",
  ui_story_5075_50750602_7_dialog_content = "皓津城で今、何が起こってるんだろう？",
  ui_story_5075_50750602_8_dialog_content = "おぬしら2人して、何を苦い顔をしておるのじゃ？",
  ui_story_5075_50750602_9_dialog_content = "おぬしらの芝居、よかったぞ。\nしかも妖魔まで退治しおった。",
  ui_story_5075_50750602_10_dialog_content = "殊にPlayerNameの演技は気に入ったぞ！",
  ui_story_5075_50750602_11_dialog_content = "あれで本当に演技って言えるのかな…",
  ui_story_5075_50750602_12_dialog_content = "しかも途中から、鎮海の龍女とはまったく関係ない話になってたよね。",
  ui_story_5075_50750602_13_dialog_content = "俺が聞いたのは、ああいう話だったんだよ。",
  ui_story_5075_50750602_14_dialog_content = "800年前、クロミズチが現れ、\n人々の暮らしは立ち行かなくなった。",
  ui_story_5075_50750602_15_dialog_content = "幸い、龍女が降臨し、海面に立って、\n空を飛んでいたクロミズチに向かって拳を振り上げたんだ。",
  ui_story_5075_50750602_16_dialog_content = "その拳は重く、クロミズチは驚く間もないまま、\n拳の起こした風に10数里先までふっ飛ばされちまったんだ。",
  ui_story_5075_50750602_17_dialog_content = "龍女は反撃の間も与えず、\n数十回も続けて拳を振り、クロミズチをぼこぼこにした。",
  ui_story_5075_50750602_18_dialog_content = "ふむふむ、それで？その後どうなったのじゃ？",
  ui_story_5075_50750602_19_dialog_content = "クロミズチはくらくらする頭をもたげ、\n沸き上がる怒りに任せ――",
  ui_story_5075_50750602_20_dialog_content = "いや、その時の状況は、俺よりあんたの方が詳しいはずだ。\nだって、あんたは…",
  ui_story_5075_50750602_21_dialog_content = "心優しき龍王様――シンゲイ様だろ？",
  ui_story_5075_50750602_22_dialog_content = "ええ！？ちょっと待って…テンカンから話は聞いてたけど、\nシンゲイが神様だなんて、心の準備ができてないよ…",
  ui_story_5075_50750602_23_dialog_content = "シンゲイが…龍女様！？",
  ui_story_5075_50750602_24_dialog_content = "龍女とは、確かにわらわのことじゃ。",
  ui_story_5075_50750602_25_dialog_content = "心優しき龍王様！",
  ui_story_5075_50750602_26_dialog_content = "拝むの早っ！",
  ui_story_5075_50750602_27_dialog_content = "俺たちの目の前にいるのは、正真正銘の神様だぞ？\n拝んで当然だろが。",
  ui_story_5075_50750602_28_dialog_content = "龍王様、皓津には何の用で降臨したんだ？",
  ui_story_5075_50750602_29_dialog_content = "鎮海の封印を破り、わらわの安眠を妨げる者が現れた。\nゆえに問い詰めに来たのじゃ。",
  ui_story_5075_50750602_30_dialog_content = "そ、それは…大変じゃねーか！",
  ui_story_5075_50750602_31_dialog_content = "このところ妖魔がのさばり、祟霊が騒ぎだしてたのは、\nクロミズチの封印が破られたからだったのか！？",
  ui_story_5075_50750602_32_dialog_content = "クロミズチも実在してたの！？",
  ui_story_5075_50750602_33_dialog_content = "ああ。鎮海の龍女の話は何通りもあるが、\nどれも実際の歴史を題材にしてる。",
  ui_story_5075_50750602_34_dialog_content = "だから、話の筋自体にそう違いはないのさ。",
  ui_story_5075_50750602_35_dialog_content = "どの話も、クロミズチが現れたことに始まり、龍女様自らそれを海底に封じて、\n人々の安寧を取り戻したって結末で終わるんだ。",
  ui_story_5075_50750602_36_dialog_content = "でも、その「鎮海のシンゲイ」の話も、\nもう800年も前のことでしょ？",
  ui_story_5075_50750602_37_dialog_content = "何百年も経ってるのに、そのクロミズチがまだ生きてるの？",
  ui_story_5075_50750602_38_dialog_content = "クロミズチの身体はとうの昔に朽ちておる。\n心配することはない。",
  ui_story_5075_50750602_39_dialog_content = "ただ、当時の災いは、わが同族の罪ではない。",
  ui_story_5075_50750602_40_dialog_content = "海中の奥深き洞窟には、大魔が葬られておったのじゃが、\nその亡骸には深い恨みの念がこもっておった。",
  ui_story_5075_50750602_41_dialog_content = "そこにわが同族が誤って入り、怨念に憑りつかれた末、\n災いを起こしたのじゃ。",
  ui_story_5075_50750602_42_dialog_content = "今や封印は破られてしもうたが、わらわの力は残っておる。\n怨念が放たれたとて、憑りつく器がなければ、災いは起こせぬ。",
  ui_story_5075_50750602_43_dialog_content = "器を得たとしても、まずは一体化せねばならぬゆえ、\nすぐに自在に動くこともかなわぬ。",
  ui_story_5075_50750602_44_dialog_content = "（ということは、前に感知した時、さっと一瞬走った影は、\nかつての大魔だったってこと？）",
  ui_story_5075_50750602_45_dialog_content = "（何となく違和感があるけど…ハッキリ見えなかったから、分からないな。\n幸い、シンゲイの話では、まだ時間があるみたいだ）",
  ui_story_5075_50750602_46_dialog_content = "とにかく、シンゲイと僕たちの目的は一致してるみたいだね。",
  ui_story_5075_50750602_47_dialog_content = "だったら仲間だね。1つ質問してもいいかな？",
  ui_story_5075_50750602_48_dialog_content = "よいぞ。",
  ui_story_5075_50750602_49_dialog_content = "僕たちが初めて会ったのは、龍女廟だったよね？",
  ui_story_5075_50750602_50_dialog_content = "つまり、龍女様本人が…お供え物を盗んだの？",
  ui_story_5075_50750602_51_dialog_content = "…盗んでなどおらぬ。",
  ui_story_5075_50750602_52_dialog_content = "わらわに捧げられたものをもらうことが、\nなにゆえ盗みになるのじゃ？",
  ui_story_5075_50750602_53_dialog_content = "あはは、そうだね。僕が言い間違えた。\n盗んだんじゃなくて、取ったんだね。",
  ui_story_5075_50750602_54_dialog_content = "やっぱり、今のシンゲイの方が親しみやすいな。",
  ui_story_5075_50750602_55_dialog_content = "それと、この金の飾りはシンゲイのものだよね。",
  ui_story_5075_50750602_56_dialog_content = "1つは龍女廟で拾ったもので、もう1つはテンカン…\nいや、アメ細工職人が拾ったんだ。返すよ。",
  ui_story_5075_50750602_57_dialog_content = "ならば、1つだけ返してもらおう。",
  ui_story_5075_50750602_58_dialog_content = "それはPlayerNameが廟で拾ったのじゃ。\nであれば、おぬしのものじゃ。",
  ui_story_5075_50750602_59_dialog_content = "この先願い事ができた時、それを捧げ、わらわに祈るとよい。",
  ui_story_5075_50750602_60_dialog_content = "願い事…？",
  ui_story_5075_50750602_61_dialog_content = "皆さん、失礼いたします。",
  ui_story_5075_50750602_62_dialog_content = "あれ、座長さん？さっきは本当にすみませんでした。",
  ui_story_5075_50750602_63_dialog_content = "いいえ、とんでもない。\nあなた方のおかげで、舞台以外の損失が出ず、幸いでした。",
  ui_story_5075_50750602_64_dialog_content = "ただ、龍女選びが中止になったので、賞品はございませんが、\nぜひこちらをお持ちください。",
  ui_story_5075_50750602_65_dialog_content = "我が家で作った菓子です。\n店で買うものほど、手は込んでいませんが…",
  ui_story_5075_50750602_66_dialog_content = "先祖代々受け継がれてきた作り方で、他にはない菓子です。\n物珍しさを楽しむとでも思って、お召し上がりください。",
  ui_story_5075_50750602_67_dialog_content = "それじゃ！",
  ui_story_5075_50750602_68_dialog_content = "わらわはその菓子の香りに誘われて、技比べに出たのじゃ。\nなんじゃ、賞品ではなかったのか。",
  ui_story_5075_50750602_69_dialog_content = "お菓子のため！？",
  ui_story_5075_50750602_70_dialog_content = "あぐっ。",
  ui_story_5075_50750602_71_dialog_content = "うーむ、これじゃ！この味じゃ！\nおぬしの作った菓子、おぬしの爺様の作った味そのままじゃ！",
  ui_story_5075_50750602_72_dialog_content = "ふふふ、これで縁日も満喫できたのう。",
  ui_story_5075_50750602_73_dialog_content = "行くぞ。",
  ui_story_5075_50750602_74_dialog_content = "祖父の作った味そのまま…？しかし、祖父はもう何年も前に亡くなっているし、\n菓子を売ったこともないんだが…",
  ui_story_5075_50750602_75_dialog_content = "まさか…！！",
  ui_story_5075_50750602_76_dialog_content = "PlayerName、ラショウ、アテイ。\nおぬしらも食べてみよ。",
  ui_story_5075_50750602_77_dialog_content = "真に美味じゃぞ。ただ惜しいことに、あの座長の一族しか作れぬのじゃ。",
  ui_story_5075_50750602_78_dialog_content = "ガオ～。",
  ui_story_5075_50750602_79_dialog_content = "それはありがたい、シンゲイ様！",
  ui_story_5075_50750602_80_dialog_content = "ラショウも共に遊んだ仲じゃ。\nシンゲイでよい。",
  ui_story_5075_50750602_81_dialog_content = "分かった。神様の言う通りにするよ！",
  ui_story_5075_50750602_82_dialog_content = "PlayerName、なにゆえ食わぬのじゃ？",
  ui_story_5075_50750602_83_dialog_content = "これでいいのかな？",
  ui_story_5075_50750602_84_dialog_content = "どういう意味じゃ？",
  ui_story_5075_50750602_85_dialog_content = "あの座長さんは、シンゲイの昔の知り合いのお孫さんなんだよね？",
  ui_story_5075_50750602_86_dialog_content = "何か話さなくていいの？",
  ui_story_5075_50750602_87_dialog_content = "うむ…",
  ui_story_5075_50750602_88_dialog_content = "わらわは龍であり、大祟霊じゃ。\nみなに海の神としてあがめられ、人と違うて、寿命も長い。",
  ui_story_5075_50750602_89_dialog_content = "ゆえに多くの人と出会う。",
  ui_story_5075_50750602_90_dialog_content = "あの座長も、かつてわらわによく菓子をくれた者の孫じゃ。",
  ui_story_5075_50750602_91_dialog_content = "東の街の、かつてわらわと共に舟遊びをした者の孫娘は\n今婚礼を挙げておる。",
  ui_story_5075_50750602_92_dialog_content = "南の川の対岸の小道では、闘しつでわらわがどうしても\n勝てなんだ者の甥っ子の葬儀が行われておる。",
  ui_story_5075_50750602_93_dialog_content = "――彼の者の最後の血縁じゃ。",
  ui_story_5075_50750602_94_dialog_content = "みな寿命が短すぎるのじゃ。\nゆえに何をするにも急いてばかりいる。",
  ui_story_5075_50750602_95_dialog_content = "そして、たびたび儀式を行っては、生きた証を残す。",
  ui_story_5075_50750602_96_dialog_content = "もし、かつての知り合いの縁者だからと、\nその子孫とまで関わりを持てば――",
  ui_story_5075_50750602_97_dialog_content = "わらわは日々儀式に駆け回らねばならぬ。",
  ui_story_5075_50750602_98_dialog_content = "でも、寂しくないの？",
  ui_story_5075_50750602_99_dialog_content = "寿命が長いから、君はいつだって友だちを見送らなきゃいけない。",
  ui_story_5075_50750602_100_dialog_content = "寂しくはない。これも悪くはない。",
  ui_story_5075_50750602_101_dialog_content = "PlayerNameも、己の幸運を喜ぶがいい。",
  ui_story_5075_50750602_102_dialog_content = "おぬしは寿命の長いわらわと知り合えたのじゃ。\nわらわはずっと覚えておる。",
  ui_story_5075_50750602_103_dialog_content = "何かあっても、おぬしはわらわの心の中で生き続ける。\nわらわと共に永い時を生きるのじゃ。",
  ui_story_5075_50750602_104_dialog_content = "（シンゲイの言ってることは分かる。\nでも…やっぱりよく分からない）",
  ui_story_5075_50750602_105_dialog_content = "（シンゲイは曇りのない笑顔で、そう言うけど――）",
  ui_story_5075_50750602_106_dialog_content = "（今急に分かった気がする…僕とシンゲイは、違うんだって）",
  ui_story_5075_50750701_1_dialog_content = "ワタシタチハ、チガウ。",
  ui_story_5075_50750701_2_dialog_content = "ダカラ…",
  ui_story_5075_50750701_3_dialog_content = "アイ、イレナイ。",
  ui_story_5075_50750701_4_dialog_content = "ッ…",
  ui_story_5075_50750701_5_dialog_content = "大丈夫か？少し休むか？",
  ui_story_5075_50750701_6_dialog_content = "あんたずっと、黒い気を感知してるだろ？\nそんなことして身体が持つのか？",
  ui_story_5075_50750701_7_dialog_content = "大丈夫だよ。そこまでひ弱じゃないから。",
  ui_story_5075_50750701_8_dialog_content = "それに感知を続けて分かってきたんだ。\nこの黒い気は、本質的には暗力と変わらない。",
  ui_story_5075_50750701_9_dialog_content = "ただ、感染力と浸食性を持ってるから、\n暗力に対抗する方法を使っても、取り除くことができないんだ。",
  ui_story_5075_50750701_10_dialog_content = "でも、その感染力や浸食性がシンゲイの言う怨念から来るものだとすれば、\n一種の意識だってことになる。",
  ui_story_5075_50750701_11_dialog_content = "意識なら、感知能力で干渉できる！",
  ui_story_5075_50750701_12_dialog_content = "何度か試してみたけど、感知能力を使えば、\n浸食性を遮断できるみたいなんだ。",
  ui_story_5075_50750701_13_dialog_content = "何度も練習すれば、僕にも憑りつかれた祟霊を助けられるかもしれない。",
  ui_story_5075_50750701_14_dialog_content = "わらわに任せてもよいのじゃぞ。",
  ui_story_5075_50750701_15_dialog_content = "ダメだよ。僕たちは仲間でしょ？\nだったら、何もかも君1人にやらせるわけにはいかないよ。",
  ui_story_5075_50750701_16_dialog_content = "そういう細かい仕事のほかに、\n拳が必要な時は、いつでも言ってくれ。",
  ui_story_5075_50750701_17_dialog_content = "ガオ――",
  ui_story_5075_50750701_18_dialog_content = "そうそう、アテイもいるしな！",
  ui_story_5075_50750701_19_dialog_content = "ガオー！",
  ui_story_5075_50750701_20_dialog_content = "チュー！",
  ui_story_5075_50750701_21_dialog_content = "お？こいつは、あの祟霊じゃねーか。\nなんだって、ここにいるんだ？",
  ui_story_5075_50750701_22_dialog_content = "アテイ、こいつはお前の仲間のとこへ行かせろって言わなかったか？",
  ui_story_5075_50750701_23_dialog_content = "ガォ…",
  ui_story_5075_50750701_24_dialog_content = "言うことを聞かなかった？",
  ui_story_5075_50750701_25_dialog_content = "感知の練習してる時も、この子はずっと付かず離れず付いてきてたよ。",
  ui_story_5075_50750701_26_dialog_content = "黒い気に浸食されておびえてるんじゃないかな？\n僕たちといれば、安心だって思ってるのかも。",
  ui_story_5075_50750701_27_dialog_content = "だが、俺たちの近くにいた方が危険だろ。\n何しろ、これから…",
  ui_story_5075_50750701_28_dialog_content = "ってか、俺たちはどこへ向かってるんだ？",
  ui_story_5075_50750701_29_dialog_content = "魚林街だよ。",
  ui_story_5075_50750701_30_dialog_content = "嫌な気配のする方じゃ。",
  ui_story_5075_50750701_31_dialog_content = "えっ？",
  ui_story_5075_50750701_32_dialog_content = "目的地は別だったのか！？",
  ui_story_5075_50750701_33_dialog_content = "？",
  ui_story_5075_50750701_34_dialog_content = "いや、もし別の所を目指してたなら、\nもっと早くに気づいてたはずだよ。",
  ui_story_5075_50750701_35_dialog_content = "別に構わぬであろう。",
  ui_story_5075_50750701_36_dialog_content = "PlayerNameは目的地に着いたしのう。",
  ui_story_5075_50750701_37_dialog_content = "俺の目がおかしくなったか？\nここの店は、どこも高級そうだぞ。",
  ui_story_5075_50750701_38_dialog_content = "ここが魚林街か…縁日ほどにぎやかじゃないけど、\n確かに豪華な感じの街だね。",
  ui_story_5075_50750701_39_dialog_content = "わらわは知っておるぞ。ここに住む者はみな金持ちじゃ。",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>澄んだ川が街を貫き、その両岸には立派な建物がそびえている。\n冬だというのに、街はきらびやかに彩られていた。</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>建物の間には色とりどりの細い布が風になびき、\n銀の鈴の音が鳴り響いている。</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>地上には美しく着飾った人々が行き交い、\n水路を行き交う商いの船は巨万の富を運ぶ。</color>",
  ui_story_5075_50750701_43_dialog_content = "道の端にあるのは何の彫像だろう？",
  ui_story_5075_50750701_44_dialog_content = "船に魚が群がってるね。\nそれにあの船と魚の尻尾、どこか見覚えがあるんだけど…",
  ui_story_5075_50750701_45_dialog_content = "どこで見たんだっけ？",
  ui_story_5075_50750701_46_dialog_content = "ミズチウオじゃ。ミズチウオは泳ぎが得意での。\nいつでも群れになって泳ぎ回っておるのじゃ。",
  ui_story_5075_50750701_47_dialog_content = "しかし、いかに遠くまで泳ごうと、\n冬になれば、必ず龍州の近海に戻り、産卵する。",
  ui_story_5075_50750701_48_dialog_content = "ゆえに、多くの者がミズチウオを航海の案内役にするのじゃ。",
  ui_story_5075_50750701_49_dialog_content = "お魚に？",
  ui_story_5075_50750701_50_dialog_content = "そうじゃ。人は己にできぬことがあると贈り物をし、\n動物や祟霊に助けを乞うのじゃ。",
  ui_story_5075_50750701_51_dialog_content = "古より、そういうものであろう？",
  ui_story_5075_50750701_52_dialog_content = "でも、今はそうでもなさそうだけど…",
  ui_story_5075_50750701_53_dialog_content = "この彫像はだいぶ年季が入ってるみたいだ。\n汚れやキズも多いし、手入れしてくれる人がいないんじゃないかな。",
  ui_story_5075_50750701_54_dialog_content = "昔はいい関係だったのかもしれないけど、たぶん今は…",
  ui_story_5075_50750701_55_dialog_content = "終わったわ。",
  ui_story_5075_50750701_56_dialog_content = "ユエ！皓津に戻ってたんだね。",
  ui_story_5075_50750701_57_dialog_content = "数日前にはもう戻っていたの。\nただリン家でまた色々とあったものだから、会いに行けなかったわ。",
  ui_story_5075_50750701_58_dialog_content = "でも、今会えたよ。",
  ui_story_5075_50750701_59_dialog_content = "リン家でまた事件でもあったの？",
  ui_story_5075_50750701_60_dialog_content = "事件ではないわ。",
  ui_story_5075_50750701_61_dialog_content = "間違いを犯したの。",
  ui_story_5075_50750701_62_dialog_content = "ミズチウオのことで、リン家が間違いを犯したの。",
  ui_story_5075_50750701_63_dialog_content = "それは…「終わった」って言ったことと関係があるの？",
  ui_story_5075_50750701_64_dialog_content = "ええ。",
  ui_story_5075_50750701_65_dialog_content = "あの…尻尾に触らないでくださいますか？",
  ui_story_5075_50750701_66_dialog_content = "さ、触ってないよ！",
  ui_story_5075_50750701_67_dialog_content = "あなたじゃないわ。",
  ui_story_5075_50750701_68_dialog_content = "おや、見つかってしもうたか。",
  ui_story_5075_50750701_69_dialog_content = "ミズチウオの血を引く光霊は珍しいからのう。\nつい触れたくなってしもうた。",
  ui_story_5075_50750701_70_dialog_content = "ミズチウオは龍の縁戚という。ならば、われらは親戚じゃのう。",
  ui_story_5075_50750701_71_dialog_content = "滅相もないことです。",
  ui_story_5075_50750701_72_dialog_content = "どうりで、このお魚に見覚えがあったわけだね。\nユエの尻尾と同じだったからだ。",
  ui_story_5075_50750701_73_dialog_content = "しかも、よく見ると、船も蜃風号に似てる！",
  ui_story_5075_50750701_74_dialog_content = "あれは蜃風号の元になった船よ。",
  ui_story_5075_50750701_75_dialog_content = "大海原を越え、アストラ大陸へ渡ることに成功した、\nリン家の最初の商船なの。",
  ui_story_5075_50750701_76_dialog_content = "そうだったんだ。\nでも、どうしてリン家の商船の彫像がここに？",
  ui_story_5075_50750701_77_dialog_content = "あら、知らなかったの？",
  ui_story_5075_50750701_78_dialog_content = "この商店街は、以前リン家のものだったのよ。",
  ui_story_5075_50750701_79_dialog_content = "ぜ、全部！？",
  ui_story_5075_50750701_80_dialog_content = "近年は取引やら抵当やら、それに少し前の事件もあったから、\n一部はすでに手放してしまって――",
  ui_story_5075_50750701_81_dialog_content = "今リン家名義の店は半分しか残っていないけれど…",
  ui_story_5075_50750701_82_dialog_content = "その残りの半分も、最終的に誰のものになるかは、\n今後の状況次第ね。",
  ui_story_5075_50750701_83_dialog_content = "半分でもすごいよ。",
  ui_story_5075_50750701_84_dialog_content = "チューッ！",
  ui_story_5075_50750701_85_dialog_content = "うわっ。",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>突然飛び掛かってきた祟霊に押し倒されたかと思うと、\n一筋の真っ黒な暗力がちょうど足元の地面を突いた</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName！大丈夫か？",
  ui_story_5075_50750701_89_dialog_content = "うん、大丈夫。その子が助けてくれたんだ。",
  ui_story_5075_50750701_90_dialog_content = "チュー…",
  ui_story_5075_50750701_91_dialog_content = "どうしたんだろう？急に苦しみだしたよ。",
  ui_story_5075_50750701_92_dialog_content = "…この子、いつの間にか、また黒い気に感染してるよ！",
  ui_story_5075_50750701_93_dialog_content = "アテイ！？",
  ui_story_5075_50750701_94_dialog_content = "ガォ…",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>アテイは苦しそうにうめき声をあげると、\n安定していたはずの光力が乱れ始めた。</color>",
  ui_story_5075_50750701_96_dialog_content = "この症状は、まさか…",
  ui_story_5075_50750701_97_dialog_content = "強制感知！",
  ui_story_5075_50750701_98_dialog_content = "ひとまず黒い気の浸食は遮断したけど、\n急いで源を探さないと本当の解決にはならない。",
  ui_story_5075_50750701_99_dialog_content = "周りにも突然、広範囲にわたって黒い気が現れた…\nいったいどこから…",
  ui_story_5075_50750701_100_dialog_content = "わらわは封印を破りし者を探しておるのじゃ、おぬしではない。\n落ち着かぬか、惑わされるな。",
  ui_story_5075_50750701_101_dialog_content = "シンゲイ？誰と話してるの？",
  ui_story_5075_50750701_102_dialog_content = "魚じゃ。",
  ui_story_5075_50750701_103_dialog_content = "魚…？あの彫像のこと？",
  ui_story_5075_50750701_104_dialog_content = "感知！",
  ui_story_5075_50750701_105_dialog_content = "ここは…海の中かな？",
  ui_story_5075_50750701_106_dialog_content = "ダレ、ダ？",
  ui_story_5075_50750701_107_dialog_content = "君のその尻尾は、ミズチウオの尻尾だね？",
  ui_story_5075_50750701_108_dialog_content = "リン家と関係あるの？",
  ui_story_5075_50750701_109_dialog_content = "リン、ケ。",
  ui_story_5075_50750701_110_dialog_content = "ヒキョウモノノ、アツマリ。",
  ui_story_5075_50750701_111_dialog_content = "ニクイ！",
  ui_story_5075_50750701_112_dialog_content = "！",
  ui_story_5075_50750701_113_dialog_content = "ううっ…",
  ui_story_5075_50750701_114_dialog_content = "PlayerName、しっかりして。",
  ui_story_5075_50750701_115_dialog_content = "僕は大丈夫だよ。ただ、今感知した場所は、\n今まで感知したどこよりも黒い気の浸食がひどかった。",
  ui_story_5075_50750701_116_dialog_content = "それと、誰かいた。たぶん…リン家と関係のある人だ。",
  ui_story_5075_50750701_117_dialog_content = "イヨウね。",
  ui_story_5075_50750701_118_dialog_content = "どうして分かったの？",
  ui_story_5075_50750701_119_dialog_content = "イヨウはかつてリン家に協力していた祟霊よ。",
  ui_story_5075_50750701_120_dialog_content = "少し前、当主様が妖魔の異常について、海に入って調べてもらえないか、\nイヨウに頼んだのだけど、その後戻ってきていないの。",
  ui_story_5075_50750701_121_dialog_content = "…器だ…イヨウはさっきシンゲイの言ってた器にされたんだ！\n最悪の事態になっちゃったよ！",
  ui_story_5075_50750701_122_dialog_content = "封印されてた力が新しい憑依体を見つけたんだ。",
  ui_story_5075_50750701_123_dialog_content = "チューッ！",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>祟霊が突然飛び出し、\n道の隅にいた見知らぬ人の腕に力一杯咬みついた。</color>",
  ui_story_5075_50750701_125_dialog_content = "うわあっ…この畜生が！",
  ui_story_5075_50750701_126_dialog_content = "うせろ！",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>祟霊は男に振り飛ばされ、\n地面の上をしばらく転がったかと思うと、動かなくなった。</color>",
  ui_story_5075_50750701_128_dialog_content = "ネズ公！",
  ui_story_5075_50750701_129_dialog_content = "ふん。",
  ui_story_5075_50750701_130_dialog_content = "こ、この人…黒い気が漂ってる！懐に何を持ってるの？",
  ui_story_5075_50750701_131_dialog_content = "お前、何者だ！？",
  ui_story_5075_50750701_132_dialog_content = "お前たちに話す筋合いはない。",
  ui_story_5075_50750701_133_dialog_content = "大変だ、急いでつかまえて！",
  ui_story_5075_50750701_134_dialog_content = "間に合わない！",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>見知らぬ男が懐に抱えていたものを力いっぱい投げつけ壊すと、\n中から大量の黒い気があふれ出した。</color>",
  ui_story_5075_50750701_136_dialog_content = "（さっき感知した時に感じた海の中の力と同じだ…！）",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>今はもう感知能力を使うまでもなく――</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>今はもう感知能力を使うまでもなく――</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>黒い気が濃い暗力をまといながら、\n沸騰した水のごとく、うねりながら無尽蔵に湧き出してくるのが見えた。</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>ありとあらゆる不安定なエネルギーが一つとなり、最後に…。</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>爆発した！</color>",
  ui_story_5075_50750701_142_dialog_content = "させるか！",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>金色の影が天雷をまとって飛び出し、\n黒い気の波を阻んだが、気は依然広がっていく</color>",
  ui_story_5075_50750701_145_dialog_content = "ふん…封印を破りし者はおぬしらと見た。\n大人しく罪に服するがいい！",
  ui_story_5075_50750701_146_dialog_content = "ゴホッゴホッ…",
  ui_story_5075_50750701_147_dialog_content = "どういうこと？シンゲイは？",
  ui_story_5075_50750701_148_dialog_content = "黒い気を阻んだ後、あの男を追って行った。",
  ui_story_5075_50750701_149_dialog_content = "そんな、無鉄砲な！",
  ui_story_5075_50750701_150_dialog_content = "たぶん、シンゲイなら大丈夫だとは思うけど…",
  ui_story_5075_50750701_151_dialog_content = "こっちは？誰もケガしてない？",
  ui_story_5075_50750701_152_dialog_content = "ヒトはケガしてない…アテイ！ネズ公！",
  ui_story_5075_50750701_153_dialog_content = "ガォ…",
  ui_story_5075_50750701_154_dialog_content = "さっきの爆発で黒い気が散っちまって、\nこいつらの症状もひどくなった。",
  ui_story_5075_50750701_155_dialog_content = "それだけじゃないわ。妖魔も引き寄せられてきたわよ。",
  ui_story_5075_50750701_156_dialog_content = "みんな、戦う準備を！",
  ui_story_5075_50750701_157_dialog_content = "グア！",
  ui_story_5075_50750702_1_dialog_content = "ここはリン家の興った地よ、妖魔の勝手は許さないわ！",
  ui_story_5075_50750702_2_dialog_content = "グアアア――",
  ui_story_5075_50750702_3_dialog_content = "ユエのおかげで、ここに集まってきた暗鬼は片付けられたね。",
  ui_story_5075_50750702_4_dialog_content = "ただ、さっきの黒い気は城内まで広がってる。\n嫌な予感がする。",
  ui_story_5075_50750702_5_dialog_content = "何か方法はないかな…",
  ui_story_5075_50750702_6_dialog_content = "あるわ。",
  ui_story_5075_50750702_7_dialog_content = "最盛期には及ばないにしても、リン家の力は今の皓津でも健在よ。",
  ui_story_5075_50750702_8_dialog_content = "まずは、あなたたちをリン家の屋敷まで送るわ。",
  ui_story_5075_50750702_9_dialog_content = "そして当主様に事情を話して、\n城内のリン家の力を動員し、解決に協力するようお願いするの。",
  ui_story_5075_50750702_10_dialog_content = "ありがとう！でも、どうして原因もいきさつも聞かずに助けてくれるの？",
  ui_story_5075_50750702_11_dialog_content = "そもそもリン家にとって、これは他人事じゃないのよ…",
  ui_story_5075_50750702_12_dialog_content = "それに、あなたを助けるのに理由などいる？",
  ui_story_5075_50750702_13_dialog_content = "PlayerName、待ってくれ。",
  ui_story_5075_50750702_14_dialog_content = "ラショウ、どうかしたの？",
  ui_story_5075_50750702_15_dialog_content = "ネズ公のこと、頼んでいいか？",
  ui_story_5075_50750702_16_dialog_content = "もちろんだよ。忘れるところだった。アテイもおいで。",
  ui_story_5075_50750702_17_dialog_content = "シンゲイはまだ戻らないし、\nまずは黒い気の浸食をくい止めてあげるね。",
  ui_story_5075_50750702_18_dialog_content = "ガォ…",
  ui_story_5075_50750702_19_dialog_content = "アテイ？",
  ui_story_5075_50750702_20_dialog_content = "俺たちは別行動するよ。",
  ui_story_5075_50750702_21_dialog_content = "え、どうして君まで？",
  ui_story_5075_50750702_22_dialog_content = "黒い気が皓津に広がったとなれば、\n他の祟霊も感染してるに違いない。",
  ui_story_5075_50750702_23_dialog_content = "祟霊は悪いやつらじゃない。ただ山で育ったから、\n本能的に獣の習性にまかせて行動しちまうだけなんだ。",
  ui_story_5075_50750702_24_dialog_content = "今の街の住民たちは祟霊に対して過激な考え方を持ってる。",
  ui_story_5075_50750702_25_dialog_content = "黒い気に感染して、祟霊たちがまた暴れ出して、誰かを傷つけでもしたら、\nおそらくヒトと祟霊の関係は修復不可能になるだろう。",
  ui_story_5075_50750702_26_dialog_content = "だから、取り返しのつかないことになる前に、\n感染した祟霊たちを捕まえたいんだ。",
  ui_story_5075_50750702_27_dialog_content = "ヒトに恨みを持つ祟霊も確かにいる。",
  ui_story_5075_50750702_28_dialog_content = "だが、こんな形で強制的に敵対させられるのは違う。",
  ui_story_5075_50750702_29_dialog_content = "そうだろ、アテイ？",
  ui_story_5075_50750702_30_dialog_content = "お前が間違ったことをすれば、俺はおしおきするし、\nいいことをすれば、褒めもする。",
  ui_story_5075_50750702_31_dialog_content = "だが何をするにしても、\n最後に決めるのはお前自身だ。",
  ui_story_5075_50750702_32_dialog_content = "俺と、一緒に来るか？",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>ラショウはかがみこんで、アテイをじっと見つめた。</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>地面に臥せっていたアテイは身体を起こし、\nふらつきながらも立ち上がった。</color>",
  ui_story_5075_50750702_35_dialog_content = "ガオー！",
  ui_story_5075_50750702_36_dialog_content = "さすがは、俺の相棒だ。",
  ui_story_5075_50750702_37_dialog_content = "でも、アテイの今の状態じゃ…",
  ui_story_5075_50750702_38_dialog_content = "シンゲイが…龍女様がいれば…",
  ui_story_5075_50750702_39_dialog_content = "おいおい、あんた何様のつもりだ？",
  ui_story_5075_50750702_40_dialog_content = "頼めば、必ず出てきてくれる神様がいると思うか？",
  ui_story_5075_50750702_41_dialog_content = "親兄弟だって、頼み事を断るし、\n嫌味の一つや二つも言うもんだ。神様ならなおさらだよ。",
  ui_story_5075_50750702_42_dialog_content = "うん、それもそうだね。",
  ui_story_5075_50750702_43_dialog_content = "神や仏に祈るのも、結局は人の身勝手だろ。",
  ui_story_5075_50750702_44_dialog_content = "だったら神や仏にも、選ぶ権利はある。",
  ui_story_5075_50750702_45_dialog_content = "生きていくうえで、結局一番頼りになるのは自分の拳だけさ！",
  ui_story_5075_50750702_46_dialog_content = "拳さえあれば、どんなに大きな壁も打ち破れるんだ。",
  ui_story_5075_50750702_47_dialog_content = "ガオォーン！",
  ui_story_5075_50750702_48_dialog_content = "じゃあな。",
  ui_story_5075_50750702_49_dialog_content = "順調を祈ってるよ。",
  ui_story_5075_50750702_50_dialog_content = "私たちも行きましょう。",
  ui_story_5075_50750702_51_dialog_content = "リン家の屋敷に戻るわよ。",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>済の国、王宮</color>",
  ui_story_5075_50750801_2_dialog_content = "大王様、鄴の国からまた知らせが参りました。",
  ui_story_5075_50750801_3_dialog_content = "鄴の国から<color=#FFB400>沿岸砲</color>が届いたか？",
  ui_story_5075_50750801_4_dialog_content = "い、いいえ…",
  ui_story_5075_50750801_5_dialog_content = "なに？先頃値を上げおったが、\nその後こちらへ送ったのではなかったか？",
  ui_story_5075_50750801_6_dialog_content = "鄴の国の使いは確かにそのように申しておりました。",
  ui_story_5075_50750801_7_dialog_content = "しかし、あれからすでに半月が経つというのに、物が届かず、\n我々から便りを出し、催促したところ…",
  ui_story_5075_50750801_8_dialog_content = "ふむ、察しはつく。再び値を上げおったな？",
  ui_story_5075_50750801_9_dialog_content = "…はい。",
  ui_story_5075_50750801_10_dialog_content = "信書によりますと、荷を運ぶ隊が山中で連絡を絶ったそうです。",
  ui_story_5075_50750801_11_dialog_content = "済の国が急ぎ必要としている荷のため、\n限りある人手を割き、捜索をするそうですが――",
  ui_story_5075_50750801_12_dialog_content = "それに必要な費用は当方で負担せよとのことです。",
  ui_story_5075_50750801_13_dialog_content = "むろん、5年前鄴が済に借りた金を当ててもよい、とも申してまいりました。",
  ui_story_5075_50750801_14_dialog_content = "私が思うに、捜索だの何だのというのも、\n値を上げるためのこじつけでございましょう。",
  ui_story_5075_50750801_15_dialog_content = "しかし、我々が支払いを拒否すれば、\n沿岸砲は永遠に捜索中となり――",
  ui_story_5075_50750801_16_dialog_content = "おそらく…見つかることもないでしょう。",
  ui_story_5075_50750801_17_dialog_content = "なんと小賢しい！",
  ui_story_5075_50750801_18_dialog_content = "妖魔が怪しい動きを見せ始めた頃に誂えたというに、\n再三納期を延ばしたうえ――",
  ui_story_5075_50750801_19_dialog_content = "此度は荷を運んでいた者らが失踪したと？\n次は沿岸砲が自ら姿を消したとでも言う気か？",
  ui_story_5075_50750801_20_dialog_content = "便りを返せ。これ以上調子に乗るようならば、\n両国の取り引きを全て取り消すと！",
  ui_story_5075_50750801_21_dialog_content = "しかし大王様、このところ妖魔は以前にも増して暴れております。",
  ui_story_5075_50750801_22_dialog_content = "特に沿岸部一帯では、宮中からの応援を望む声が高まっております。",
  ui_story_5075_50750801_23_dialog_content = "鄴の国の沿岸砲の到着がこれ以上遅れれば、\n防衛線を守りきれなくなる恐れがございます。",
  ui_story_5075_50750801_24_dialog_content = "守り切れなくなると？",
  ui_story_5075_50750801_25_dialog_content = "龍州は、鄴の国だけで成り立っているわけではあるまい。",
  ui_story_5075_50750801_26_dialog_content = "わが済は物産豊かで、暮らしは穏やか、\n商業も発達し、日々数えきれぬほどの富を生み出しておる。",
  ui_story_5075_50750801_27_dialog_content = "海運がままならずとも、河川水運がある。\n鄴の国との交易が成らぬなら、他国と交易すればよい。",
  ui_story_5075_50750801_28_dialog_content = "金は万能だ。それに見合った金を出せば、\n央京の軍とて、わが済のために動かせる。",
  ui_story_5075_50750801_29_dialog_content = "では、鄴の国の要求は…",
  ui_story_5075_50750801_30_dialog_content = "突き返せ。",
  ui_story_5075_50750801_31_dialog_content = "かしこまりました。",
  ui_story_5075_50750801_32_dialog_content = "ふん。今や鄴の国までもが余を相手に小賢しい手を使うか。",
  ui_story_5075_50750801_33_dialog_content = "当初わが済に金の融通を頼んだ時の窮地を忘れたとみえる。",
  ui_story_5075_50750801_34_dialog_content = "そういえば、灼華もあの年済にやってきたのだったな。",
  ui_story_5075_50750801_35_dialog_content = "国師よ、そなたはどう思う？灼華が余の息子の嫁になるというのなら、\n金の件は考えてやってもよいのだが。",
  ui_story_5075_50750801_36_dialog_content = "大王様、さようことを軽々しくおっしゃってはなりませぬ。\n灼華郡主は志の高い女子でございます。",
  ui_story_5075_50750801_37_dialog_content = "ふん、分かっておる。",
  ui_story_5075_50750801_38_dialog_content = "しかし、世継ぎが言う事を聞く者はそう滅多におらぬ…",
  ui_story_5075_50750801_39_dialog_content = "大王様、その件は目下重要ではございませぬ。\n今や世は乱れ、動揺しております。何か策はおありですか？",
  ui_story_5075_50750801_40_dialog_content = "済の国は長い間商業に力を入れ、農事、機巧術の類はみな、\n他国との交易に頼ってまいりました。",
  ui_story_5075_50750801_41_dialog_content = "再び此度の鄴のような態度に出る国があれば…",
  ui_story_5075_50750801_42_dialog_content = "わが済は数百年もの間、商業を礎としてきた。\n策と申しても、そうたやすいことではない。",
  ui_story_5075_50750801_43_dialog_content = "かつ妖魔の災いが長く続くとも限らぬ。",
  ui_story_5075_50750801_44_dialog_content = "また話すとしよう。",
  ui_story_5075_50750801_45_dialog_content = "余は疲れた。帰って休む。",
  ui_story_5075_50750801_46_dialog_content = "…はい。",
  ui_story_5075_50750801_47_dialog_content = "先生？こちらにいらしたのですね。",
  ui_story_5075_50750801_48_dialog_content = "城外の海岸では、妖魔の力がまた増していると聞きました。\n祟霊の件もまだ原因が分かっておりませぬ。",
  ui_story_5075_50750801_49_dialog_content = "しかも、あの日宮中でお別れして以来、\nPlayerNameから連絡がないのでございます。",
  ui_story_5075_50750801_50_dialog_content = "先生は、何かご存じですか？",
  ui_story_5075_50750801_51_dialog_content = "ご安心ください。あの若者は無事ですよ。\n彼に託した件も順調に進んでおります。",
  ui_story_5075_50750801_52_dialog_content = "ただ…お聞きになりたいのは、それだけではありませぬな？",
  ui_story_5075_50750801_53_dialog_content = "先生は何もかもお見通しでいらっしゃるのですね。\nならば、単刀直入にお聞きします。",
  ui_story_5075_50750801_54_dialog_content = "先生はあの時PlayerNameに公に動くなと、\n宮中の者にも話すなとおっしゃいました。",
  ui_story_5075_50750801_55_dialog_content = "それは…宮中によからぬことを企む者がいると、\n疑っていらっしゃるからですか？",
  ui_story_5075_50750801_56_dialog_content = "その件は、私に尋ねるより、\nご自分の護衛にお尋ねになった方がよいのでは？",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>キュウ</color>のことをおっしゃっているのですか？\nキュウは今…",
  ui_story_5075_50750801_58_dialog_content = "言わなくて結構ですよ。私もこの歳です。\nあなた方のような若い娘さんのことはよく分かりませぬ。",
  ui_story_5075_50750801_59_dialog_content = "ご自分で判断なさることです。",
  ui_story_5075_50750801_60_dialog_content = "…分かりました。お導きに感謝いたします。",
  ui_story_5075_50750801_61_dialog_content = "そういえば、お詫びしなければならないことがありました。",
  ui_story_5075_50750801_62_dialog_content = "次に会った時、あの若者にもお詫びをお伝えください。",
  ui_story_5075_50750801_63_dialog_content = "少し前郡主のお名前で、贈り物をいたしました。",
  ui_story_5075_50750801_64_dialog_content = "役に立っているとよいのですが。",
  ui_story_5075_50750801_65_dialog_content = "（先生はやはり宮中の者を警戒しておられるようじゃ）",
  ui_story_5075_50750801_66_dialog_content = "（じゃが…いったい誰じゃ？先生がかように慎重になるとは…）",
  ui_story_5075_50750801_67_dialog_content = "（もし、キュウが今調べておる事と関係があるとすれば…）",
  ui_story_5075_50750801_68_dialog_content = "（そういえば、城内にはあやしき密偵が動いておったはずじゃ。\nなにゆえ宮中に何の動きもないのじゃ？）",
  ui_story_5075_50750801_69_dialog_content = "（キュウだけが気づいたということか？それとも…\n何者かがあえてキュウに気づかせたか？）",
  ui_story_5075_50750801_70_dialog_content = "（じゃが、キュウはただの人質の護衛にすぎぬし、\nわらわのためにしか動かぬ）",
  ui_story_5075_50750801_71_dialog_content = "（宮中によからぬことを企む者がいたとしても、\nかような手を使う必要はあるまい。あるいは…）",
  ui_story_5075_50750801_72_dialog_content = "（背後にいるのは、済の国の者ではなく、もしや…）",
  ui_story_5075_50750801_73_dialog_content = "ピピッ。",
  ui_story_5075_50750801_74_dialog_content = "おや？<color=#FFB400>璇璣卿</color>の言付け鳥ではないか？",
  ui_story_5075_50750801_75_dialog_content = "性能が悪く、護衛を避けられぬとか申して、\nわらわに言付けしようとせなんだが――",
  ui_story_5075_50750801_76_dialog_content = "やはりたばかっておったのじゃのう。",
  ui_story_5075_50750801_77_dialog_content = "…",
  ui_story_5075_50750801_78_dialog_content = "璇璣卿め、なんと大胆不敵な！",
  ui_story_5075_50750801_79_dialog_content = "宮中を出ねばならぬ。",
  ui_story_5075_50750801_80_dialog_content = "国師様、お申しつけの通り、周囲の護衛を下がらせました。",
  ui_story_5075_50750801_81_dialog_content = "灼華郡主殿下にも言付けをお伝えしました。",
  ui_story_5075_50750801_82_dialog_content = "よし。",
  ui_story_5075_50750902_1_dialog_content = "着いたわ。ここが魚林街のリン家邸よ。",
  ui_story_5075_50750902_2_dialog_content = "え？ここって…紙切れに書いてあった場所だ。",
  ui_story_5075_50750902_3_dialog_content = "紙切れ？",
  ui_story_5075_50750902_4_dialog_content = "ここに来る前、宮中からお菓子が贈られてきて、\nその中の紙切れに、ここの地図が書いてあったんだ。",
  ui_story_5075_50750902_5_dialog_content = "他にも、何に使うか分からない札が入ってた。",
  ui_story_5075_50750902_6_dialog_content = "それは…「巡検司」の札だな。",
  ui_story_5075_50750902_7_dialog_content = "お若いの、済の国には水軍があるのみで、\n陸には常設の軍がなきことはご存じか？",
  ui_story_5075_50750902_8_dialog_content = "要衝を守り、悪しきを抑え、妖魔を排するも皆、\n巡検司の務めである。",
  ui_story_5075_50750902_9_dialog_content = "そして、あなたがお持ちのその札を用いれば、\n巡検司を動かせる。",
  ui_story_5075_50750902_10_dialog_content = "あなたが握っておられるのは、\n王宮の近衛兵を除いた皓津にある力の中で、最も強大な力だ。",
  ui_story_5075_50750902_11_dialog_content = "僕はそんな重要な物を持ち歩いてたの！？",
  ui_story_5075_50750902_12_dialog_content = "あれ？あなたは…",
  ui_story_5075_50750902_13_dialog_content = "当主様、なぜここに？",
  ui_story_5075_50750902_14_dialog_content = "外で何やら音がしたのでな。様子を見に来たのだ。",
  ui_story_5075_50750902_15_dialog_content = "そなたが客人を連れていたのは予想外だったがな。",
  ui_story_5075_50750902_16_dialog_content = "このお若いのが、PlayerNameであろう？",
  ui_story_5075_50750902_17_dialog_content = "シュウ大兄やリンセイ、ユエから常々話は聞いておったが、\n顔を合わせるのは初めてだ。",
  ui_story_5075_50750902_18_dialog_content = "しかし、今は挨拶などしておる時ではあるまい。",
  ui_story_5075_50750902_19_dialog_content = "お若いの、私を見て何故さように驚かれるのか、お聞かせ願えるか？",
  ui_story_5075_50750902_20_dialog_content = "あ、すみません。ただ…どこかでお会いした気がして。",
  ui_story_5075_50750902_21_dialog_content = "海の中で…黒い気を操っていた祟霊の記憶の中で、\nあなたを見たような気がしたんです。",
  ui_story_5075_50750902_22_dialog_content = "イヨウのことか？",
  ui_story_5075_50750902_23_dialog_content = "おそらくそうだと思います。",
  ui_story_5075_50750902_24_dialog_content = "当主さんもイヨウを知っていて、イヨウはリン家を憎んでいる…\nお二人の間に、いったい何があったんですか？",
  ui_story_5075_50750902_25_dialog_content = "話すと長くなる。",
  ui_story_5075_50750902_26_dialog_content = "まずは中へ入られよ。",
  ui_story_5075_50750902_27_dialog_content = "私は他にやることがある。\nユエ、ひとまずそなたにもてなしを頼むとしよう。",
  ui_story_5075_50750902_28_dialog_content = "はい、承知いたしました。",
  ui_story_5075_50750902_29_dialog_content = "何か飲む？",
  ui_story_5075_50750902_30_dialog_content = "いや、大丈夫だよ。",
  ui_story_5075_50750902_31_dialog_content = "そう。じゃ、飲まずに話しましょ。",
  ui_story_5075_50750902_32_dialog_content = "あはは…そういえば忘れてたけど、ユエってこんな感じだったね。",
  ui_story_5075_50750902_33_dialog_content = "？",
  ui_story_5075_50750902_34_dialog_content = "いや、何でもないよ。\n実際うわべだけの礼儀とか必要ないし。",
  ui_story_5075_50750902_35_dialog_content = "本題に入ろう…イヨウとリン家の間に、\nいったい何があったの？",
  ui_story_5075_50750902_36_dialog_content = "リン家と祟霊の関係の始まりは、\nずいぶんと昔までさかのぼるわ。",
  ui_story_5075_50750902_37_dialog_content = "その頃のリン家はまだ小さな商会にすぎず、\n経営もうまく行かず、連年の赤字で、廃業寸前だった。",
  ui_story_5075_50750902_38_dialog_content = "リン家の先祖は家業の危機を救うため、全財産を一隻の商船に換え、\n海の外の世界に活路を見出そうとした。",
  ui_story_5075_50750902_39_dialog_content = "そして、成功した。",
  ui_story_5075_50750902_40_dialog_content = "それがリン家のアストラ交易の始まりよ。",
  ui_story_5075_50750902_41_dialog_content = "その話はカレンから聞いたことがあるよ。\n双閣港の繁栄もその頃から始まったんだよね。",
  ui_story_5075_50750902_42_dialog_content = "だったら余計な話は省けるわね。",
  ui_story_5075_50750902_43_dialog_content = "大事なのは、ご先祖様の乗った船は帰航時、\n誤って死の海と呼ばれていた海域に入ってしまったこと。",
  ui_story_5075_50750902_44_dialog_content = "その時のリン家には、まだ渾天儀はなく、\nセンキョクのように窮地を脱する術を持つ機巧師も同行していなかった。",
  ui_story_5075_50750902_45_dialog_content = "濃い霧の中で迷い、漂流すること半年、\n物資も食糧も尽きてしまった。",
  ui_story_5075_50750902_46_dialog_content = "まさにその時、ミズチウオの群れが現れたの。",
  ui_story_5075_50750902_47_dialog_content = "シンゲイが話してくれたよ。\nミズチウオは毎年冬になると群れを作って龍州に戻り、産卵するって。",
  ui_story_5075_50750902_48_dialog_content = "つまり、ご先祖様はミズチウオに助けてもらったの？",
  ui_story_5075_50750902_49_dialog_content = "ええ。",
  ui_story_5075_50750902_50_dialog_content = "吉祥の兆しと言われるミズチウオに付いていき、\nご先祖様はようやく死の海を抜け、龍州に戻ることができた。",
  ui_story_5075_50750902_51_dialog_content = "それからというもの、アストラ交易の際には、\n必ず冬を選んで帰航するようになったのよ。",
  ui_story_5075_50750902_52_dialog_content = "リン家はミズチウオにたくさんの食べ物を与え、\nミズチウオは海中からリン家の商船を導く。",
  ui_story_5075_50750902_53_dialog_content = "そうして、ミズチウオはリン家の象徴となったの。",
  ui_story_5075_50750902_54_dialog_content = "ここもその所縁で、魚林街と名付けられた。",
  ui_story_5075_50750902_55_dialog_content = "だけど、当時のご先祖様が亡くなって、子孫の代になると、\nリン家商会はますます大きくなっていった。",
  ui_story_5075_50750902_56_dialog_content = "年に1度の航海では、足りなくなっていったの。",
  ui_story_5075_50750902_57_dialog_content = "そこで後代の当主たちは、ミズチウオに航海の回数を増やせないかと相談した。",
  ui_story_5075_50750902_58_dialog_content = "え？待って。お魚に相談したの？",
  ui_story_5075_50750902_59_dialog_content = "私を見ていて、何か気づかない？",
  ui_story_5075_50750902_60_dialog_content = "当時のミズチウオのヌシは<color=#FFB400>祟霊</color>だったのよ。",
  ui_story_5075_50750902_61_dialog_content = "リン家のミズチウオの血統もその頃から始まったの。",
  ui_story_5075_50750902_62_dialog_content = "けれど、そのうちリン家は当初の約束を破り、\nミズチウオの習性を無視した航海を強行するようになって――",
  ui_story_5075_50750902_63_dialog_content = "両者の関係は徐々に悪化していった。",
  ui_story_5075_50750902_64_dialog_content = "さらには、リン家の船がミズチウオの棲息地を破壊してしまったの。",
  ui_story_5075_50750902_65_dialog_content = "そのことで、今のミズチウオのヌシを完全に怒らせてしまい、\nヌシはリン家との協力を中止すると言ってきたわ。",
  ui_story_5075_50750902_66_dialog_content = "人の姿に化けられるようになったイヨウが屋敷に乗り込み、\n私を卑怯者と罵った時の情景は今でもよく覚えておる。",
  ui_story_5075_50750902_67_dialog_content = "当主様、おかえりなさいませ。",
  ui_story_5075_50750902_68_dialog_content = "当主さん、あの…",
  ui_story_5075_50750902_69_dialog_content = "ハハハ、二人の会話が聞こえてな。",
  ui_story_5075_50750902_70_dialog_content = "かようなことは、まだお若いあなたには\n理解しがたいだろう。",
  ui_story_5075_50750902_71_dialog_content = "私も言い訳をするつもりはない。\n先人が信義に背く行いをしたことは確かだ。",
  ui_story_5075_50750902_72_dialog_content = "しかし、商人たる私は同時によく承知もしている。\nリン家はこれにより莫大な利益を得、皓津の商業界の頂点に立った。",
  ui_story_5075_50750902_73_dialog_content = "当時、私が当主の座にあったとしても、\n同じ決断をしていたろう。",
  ui_story_5075_50750902_74_dialog_content = "すでに渾天儀に関する知らせを得ていなければ、\nリン家もそうたやすく手放しはしなかった。",
  ui_story_5075_50750902_75_dialog_content = "監禁して道案内の道具としたやもしれん。",
  ui_story_5075_50750902_76_dialog_content = "イヨウは私を憎み、リン家を憎んでおる。\n当然のことだ。",
  ui_story_5075_50750902_77_dialog_content = "かつてリン家は信義に背き、恩をあだで返した。",
  ui_story_5075_50750902_78_dialog_content = "今の状況はその報いであろう。",
  ui_story_5075_50750902_79_dialog_content = "沿岸に妖魔が出没しておるというのに、\n済の国には安定した防衛線を敷く力もない。",
  ui_story_5075_50750902_80_dialog_content = "鄴の国から購入したという沿岸砲は、届く様子もなく――",
  ui_story_5075_50750902_81_dialog_content = "リン家の商船はすでに長い間海に出ておらず、\n沿岸の商売もそれゆえ活気を失った。まさに災難続きだ。",
  ui_story_5075_50750902_82_dialog_content = "船舶府から戻ると、私はシュウ大兄の忠告も聞かず、\n恥知らずにもイヨウを訪ねた。",
  ui_story_5075_50750902_83_dialog_content = "リン家が再び航路を拓き、商船を往来させるのを手伝ってほしいと願い出たが、\n当然のことながら追い返されてしまった。",
  ui_story_5075_50750902_84_dialog_content = "だが、PlayerNameの話から推測するに、\nイヨウは結局、事の次第を調べに海へ向かったようだ…",
  ui_story_5075_50750902_85_dialog_content = "それでクロミズチの怨念に浸食され、徐々に狂暴化し、\n周りの祟霊たちの怨念にも火をつけてしまったんですね。",
  ui_story_5075_50750902_86_dialog_content = "…リン家の犯した罪よ。リン家が必ず解決してみせるわ。",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>バンッ――！</color>",
  ui_story_5075_50750902_88_dialog_content = "祟霊を追い出せ！",
  ui_story_5075_50750902_89_dialog_content = "外で何かあったんでしょうか？",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>ラショウは道の中央に立ちはだかり、\n怒る人々から地面で気を失っている祟霊たちを守っていた</color>",
  ui_story_5075_50751001_2_dialog_content = "みんな落ち着くんだ！この祟霊たちに人を傷つける気はない！",
  ui_story_5075_50751001_3_dialog_content = "俺がもう大人しくさせた。\nこいつらに憑りついている力を祓いさえすれば――",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>人混みの中から石が1つ、\nラショウに向かって投げつけられた</color>",
  ui_story_5075_50751001_6_dialog_content = "ガオー！",
  ui_story_5075_50751001_7_dialog_content = "アテイ！落ち着くんだ！",
  ui_story_5075_50751001_8_dialog_content = "俺は平気だ。今、みんなと争っちゃいけない。",
  ui_story_5075_50751001_9_dialog_content = "ケガ人が出た後に、そのつもりはなかったと主張したところで何の意味がある！？",
  ui_story_5075_50751001_10_dialog_content = "だから、祟霊はろくなもんじゃないってんだ！\n物を盗むだけならまだしも、人殺しまで始めやがって！",
  ui_story_5075_50751001_11_dialog_content = "皓津はこの数百年の間ずっと平和だったってのに、\n今じゃ妖魔まで城内に現れやがった！",
  ui_story_5075_50751001_12_dialog_content = "祟霊のせいに決まってんだろ！\n祟霊も妖魔も邪な存在なんだ！",
  ui_story_5075_50751001_13_dialog_content = "あんたらは法術を使えるから、高尚ぶったことも言えるだろうが――",
  ui_story_5075_50751001_14_dialog_content = "俺たちは違う！",
  ui_story_5075_50751001_15_dialog_content = "そんな縁起の悪いもんを城内にはびこらせるわけにはいかない！\n全部追い出せ！",
  ui_story_5075_50751001_16_dialog_content = "追い出せ！追い出せ！",
  ui_story_5075_50751001_17_dialog_content = "ラショウを助けなきゃ――",
  ui_story_5075_50751001_18_dialog_content = "待って。何の準備もなしに行っても無駄よ。",
  ui_story_5075_50751001_19_dialog_content = "あの人たちは今、頭に血が上って冷静じゃない。\n何を言っても聞く耳を持たないわ。",
  ui_story_5075_50751001_20_dialog_content = "強大な力を示すか、全員が心から納得できるような約束をしない限りね。",
  ui_story_5075_50751001_21_dialog_content = "あの札があるよ！あの札をつかえば、巡検司を動かせるんでしょ？",
  ui_story_5075_50751001_22_dialog_content = "巡検司はおそらく、城内のあちこちで妖魔退治に当たっているわ。",
  ui_story_5075_50751001_23_dialog_content = "それに、もし巡検司を動かせば…\n群衆との溝が深まるだけだわ。",
  ui_story_5075_50751001_24_dialog_content = "でも、他に方法が…",
  ui_story_5075_50751001_25_dialog_content = "言ったでしょ？私、もしくはリン家なら解決できると。",
  ui_story_5075_50751001_26_dialog_content = "当主様、お聞きになりましたか？",
  ui_story_5075_50751001_27_dialog_content = "私ユエに、皓津<color=#FFB400>リン家当主代行</color>の身分をお授けくださるよう、\nここにお願い申し上げます。",
  ui_story_5075_50751001_28_dialog_content = "リン家の物資と人手を動かす権利を与え、\n私にこの件の処理を任せてください。",
  ui_story_5075_50751001_29_dialog_content = "いかにして解決するのだ？",
  ui_story_5075_50751001_30_dialog_content = "今のリン家商会には数年前ほどの権勢はありませんが、\n何代にもわたる商いで、人々の間に大きな名声を築いています。",
  ui_story_5075_50751001_31_dialog_content = "リン家の名の下に、この件は必ず解決すると約束し、\n医者とその他の人手を出して被害を受けた人々を助けます。",
  ui_story_5075_50751001_32_dialog_content = "その言葉の重みと万が一の時リン家が失うものが何か、\n承知したうえで申しておるのか？",
  ui_story_5075_50751001_33_dialog_content = "リン家の家業は確かに大きいが、\n一城の市民と軽々しく約束を交わせるまでの力はない。",
  ui_story_5075_50751001_34_dialog_content = "しかも、少し前に密輸の濡れ衣を着せられ、\nようやく冤罪を晴らしたばかりだ。",
  ui_story_5075_50751001_35_dialog_content = "商いは戦いも同じ。裏で多少の駆け引きをするのは構わぬが、\n表向きは潔白でなければならん。",
  ui_story_5075_50751001_36_dialog_content = "リン家として祟霊の安全を約束すれば、\n何かあった時、矢面に立たされるのはリン家ぞ。",
  ui_story_5075_50751001_37_dialog_content = "十分承知しております。",
  ui_story_5075_50751001_38_dialog_content = "ですが、祟霊が人を襲うのはイヨウが操っているからです。\nそして、イヨウの人への恨みはリン家が植え付けたもの。",
  ui_story_5075_50751001_39_dialog_content = "リン家が責任を取らねばなりません。",
  ui_story_5075_50751001_40_dialog_content = "今や世も変わったものだな。",
  ui_story_5075_50751001_41_dialog_content = "済の国は商いを重んじ、商人は利を追い求める。",
  ui_story_5075_50751001_42_dialog_content = "私が若かりし頃は、いかなる小利も人々は血眼になって追い求め、\n物乞いの粗末な飯にさえ群がらんばかりであった。",
  ui_story_5075_50751001_43_dialog_content = "リン家は、代々崇めてきたミズチウオさえ見捨てた。",
  ui_story_5075_50751001_44_dialog_content = "それを今「責任」というきれいごとのために、\n長年苦労し築き上げてきたすべてを賭けよというのか？",
  ui_story_5075_50751001_45_dialog_content = "やり遂げれば、きれいごとではありません。",
  ui_story_5075_50751001_46_dialog_content = "ちょっと待ってください。\n内輪もめしてる場合じゃないでしょう？今は…",
  ui_story_5075_50751001_47_dialog_content = "旦那でも簡単に覚えられる、いい呪文があるんです。",
  ui_story_5075_50751001_48_dialog_content = "今の呪文を唱えれば、どんな争いごとも、\nあっという間に円満解決できますよ。",
  ui_story_5075_50751001_49_dialog_content = "（あまり信用できないけど、試してみても損はないよね！）",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>と…<size=45>年越しなんだから！</size></color>",
  ui_story_5075_50751001_51_dialog_content = "…",
  ui_story_5075_50751001_52_dialog_content = "…",
  ui_story_5075_50751001_53_dialog_content = "ハハハ…年越し、か。",
  ui_story_5075_50751001_54_dialog_content = "古きを捨てて、新しきを迎え、一切を新たにする。",
  ui_story_5075_50751001_55_dialog_content = "何やかやと準備に忙しくしていたが、\nあと1日もすれば、元日か。",
  ui_story_5075_50751001_56_dialog_content = "はい。",
  ui_story_5075_50751001_57_dialog_content = "年越し料理そのほかもろもろ、準備はできておるのか？",
  ui_story_5075_50751001_58_dialog_content = "おおかたの食材は氷室に運び込みました。\n野菜等も注文は済み、当日届くのを待つのみです。",
  ui_story_5075_50751001_59_dialog_content = "商会の帳簿も先日確認を終えました。\n結果を取りまとめたものは書斎にお届けしてあります。",
  ui_story_5075_50751001_60_dialog_content = "今年リン家の商いは、困難続きだったので、\n勝手ながら護衛と手伝いをした者たちに2カ月分の給金を支払いました。",
  ui_story_5075_50751001_61_dialog_content = "そなたはよく気が回る。",
  ui_story_5075_50751001_62_dialog_content = "海の状況は目まぐるしく変わります。\n航海中、迅速な判断を下すことは船長の務めです。",
  ui_story_5075_50751001_63_dialog_content = "追い風かと思えば、次の瞬間には波が押し寄せる――\n変化が起こった瞬間、的確な行動を起こさなければ、取り返しがつきません。",
  ui_story_5075_50751001_64_dialog_content = "では、今のこの状況をそなたは「追い風」と見るか？",
  ui_story_5075_50751001_65_dialog_content = "その確信があるのならば、そなたの願いを聞き入れよう。",
  ui_story_5075_50751001_66_dialog_content = "よかった…",
  ui_story_5075_50751001_67_dialog_content = "<size=45>確信はありません。</size>",
  ui_story_5075_50751001_68_dialog_content = "ブーッ…ゲホッゴホゴホ…",
  ui_story_5075_50751001_69_dialog_content = "ですが、本格的な荒波が押し寄せた後では、\n舵を取る者にいかなる巧妙な策や技あろうと、何の役にも立ちません。",
  ui_story_5075_50751001_70_dialog_content = "船を支えられるのは結局、揺らぐことのない、\nまっすぐと伸びた竜骨でしかないのです。",
  ui_story_5075_50751001_71_dialog_content = "竜骨がゆがむことがあってはなりません。",
  ui_story_5075_50751001_72_dialog_content = "…",
  ui_story_5075_50751001_73_dialog_content = "そなたの判断が正しいのやもしれぬ。\nしかし私は結局、古き時代の遺物だ。",
  ui_story_5075_50751001_74_dialog_content = "私に言わせれば、そなたの行いは過激にすぎる。",
  ui_story_5075_50751001_75_dialog_content = "当主様――",
  ui_story_5075_50751001_76_dialog_content = "しかし、蜃風号の船長はそなただ。\nリン家の命ともいえる船と航路を司る者。",
  ui_story_5075_50751001_77_dialog_content = "他の者からすれば、そなたの言葉はリン家の言葉そのものだ。",
  ui_story_5075_50751001_78_dialog_content = "どういう意味でしょう？",
  ui_story_5075_50751001_79_dialog_content = "私は遺物にすぎん。だがそれ以前に商人だ。\n多角的に物を考え、利害を測る。",
  ui_story_5075_50751001_80_dialog_content = "そなたは新時代の機巧船を司る船長だ。\n己の考えに従い、行動するがよい。",
  ui_story_5075_50751001_81_dialog_content = "成し遂げれば、リン家のため功を上げた者として、\n龍州近海の航路もそなたに預けよう。",
  ui_story_5075_50751001_82_dialog_content = "だが、成し遂げられなければ、\n当主の命に背き、身勝手な行いをした罪人となる。",
  ui_story_5075_50751001_83_dialog_content = "そうなった時には、リン家はそなたをリン家から追放し、\n今後一切リン家の名を口にすることは許さん。",
  ui_story_5075_50751001_84_dialog_content = "この条件を、受け入れるか？",
  ui_story_5075_50751001_85_dialog_content = "<size=45>受け入れます。</size>",
  ui_story_5075_50751001_86_dialog_content = "PlayerName、行きましょ。",
  ui_story_5075_50751001_87_dialog_content = "うん…あ、ちょっと待って。",
  ui_story_5075_50751001_88_dialog_content = "当主さん、この札を預かってもらってもいいですか？",
  ui_story_5075_50751001_89_dialog_content = "かように大事な物を私に？",
  ui_story_5075_50751001_91_dialog_content = "私は信義に背いた者だということをお忘れか？",
  ui_story_5075_50751001_92_dialog_content = "あはは…確かにまったく不安じゃないと言ったらウソになります。",
  ui_story_5075_50751001_93_dialog_content = "でも、僕にはこの札を使う機会はないし、\n札と一緒に入っていた地図には、リン家が示されていました。",
  ui_story_5075_50751001_94_dialog_content = "当主さんは自分で自分を信用ならないと言ってますが、\nユエもシュウさんも当主さんのことを信頼してます。",
  ui_story_5075_50751001_95_dialog_content = "僕は2人を信じます。",
  ui_story_5075_50751001_96_dialog_content = "僕には感知能力があるので分かるんです。\n当主さんが本当に何か悪い事をしようとしたとしても、止めてくれる人がいるって。",
  ui_story_5075_50751001_97_dialog_content = "ならば、預かるとしよう。",
  ui_story_5075_50751001_98_dialog_content = "お願いします。",
  ui_story_5075_50751001_99_dialog_content = "ユエ、行こう――",
  ui_story_5075_50751001_100_dialog_content = "まったく…若者はこれだから困る。",
  ui_story_5075_50751001_101_dialog_content = "なにゆえ危険ばかり好んで冒すのか…沈着さが足りん。\nリン家の将来が心配でならん。",
  ui_story_5075_50751001_102_dialog_content = "そうは見えぬな。",
  ui_story_5075_50751001_103_dialog_content = "「これでリン家も安泰だ」と言わんばかりの顔だ。",
  ui_story_5075_50751001_104_dialog_content = "ハハハ、シュウ大兄の目はごまかせぬな。",
  ui_story_5075_50751001_105_dialog_content = "過去のしがらみや怨恨は私の代で終わらせ、\n後を継ぐ者には清らかなリン家を残そうと思っておったのだが――",
  ui_story_5075_50751001_106_dialog_content = "後生おそるべしというべきか、\n私が動く前に、その重荷を自ら背負っていきおった。",
  ui_story_5075_50751001_107_dialog_content = "それはそうと、大兄は影から見守るのみで、\n手助けはせぬおつもりか？",
  ui_story_5075_50751001_108_dialog_content = "PlayerNameは気づいていたようだが。",
  ui_story_5075_50751001_109_dialog_content = "ご当主も同じであろう？",
  ui_story_5075_50751001_110_dialog_content = "PlayerNameが巡検司の札を持ってきたというに、\n国師との約束のことは一切口にせぬ。",
  ui_story_5075_50751001_111_dialog_content = "約束通り、PlayerNameが到着するやいなや、\nそれがしにリン家の護衛を動かす準備をさせたというのに――",
  ui_story_5075_50751001_112_dialog_content = "なにゆえ、小芝居を？",
  ui_story_5075_50751001_113_dialog_content = "古だぬきどものお節介など、若者が知る必要はなかろう。",
  ui_story_5075_50751001_114_dialog_content = "古きを捨て、新しきを迎える春新節の儀式とでも思えばよい。",
  ui_story_5075_50751001_115_dialog_content = "しかも、まだ元日も迎えておらぬというに、\n素晴らしい言葉を多く聞けたではないか。",
  ui_story_5075_50751001_116_dialog_content = "幸先がよい。",
  ui_story_5075_50751001_117_dialog_content = "無駄話はやめだ！こいつは祟霊をかばってる！\nろくなもんじゃない！",
  ui_story_5075_50751001_118_dialog_content = "今ならまだ間に合うぞ。\nそこを退け！妖を追い出す！邪魔をするな！",
  ui_story_5075_50751001_119_dialog_content = "さもなければ、いくら法術を使えるからって、\n俺たちも容赦はしないぞ！",
  ui_story_5075_50751001_120_dialog_content = "みんなが不安に思うのも分かるが、\n何事も感情的になってはいけない――",
  ui_story_5075_50751001_121_dialog_content = "全員ひっくるめて追い出せ！",
  ui_story_5075_50751001_122_dialog_content = "追い出せ――！",
  ui_story_5075_50751001_123_dialog_content = "チュー！",
  ui_story_5075_50751001_124_dialog_content = "まずい。まだ大人しくさせてねー祟霊が…",
  ui_story_5075_50751001_125_dialog_content = "蛟龍巻渦！",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>鋭利な刃物のように、\nユエはすっと祟霊たちの中に飛び降りた。</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>見ている者が反応する間もなく、\nつい先ほどまで暴れていた祟霊は意識を失い、傍らの地面に倒れ込んだ。</color>",
  ui_story_5075_50751002_3_dialog_content = "あ…あれは誰だ？なんて技だ？",
  ui_story_5075_50751002_4_dialog_content = "リン家商会のユエ船長だ。",
  ui_story_5075_50751002_5_dialog_content = "だが、あの尻尾は…祟霊の血を引いてるのか？ということは…",
  ui_story_5075_50751002_6_dialog_content = "今俺たちを助けてくれたばっかりだろ！何てこと言うんだ！？",
  ui_story_5075_50751002_7_dialog_content = "皆さん、少し話を聞いてください。",
  ui_story_5075_50751002_8_dialog_content = "今日の事で皆さんが不安を抱き、\nケガされた方も、損失を被った方もいることは承知しております。",
  ui_story_5075_50751002_9_dialog_content = "私も怒りを覚えています。",
  ui_story_5075_50751002_10_dialog_content = "ですが、事の元凶はここにいる祟霊たちではなく、\nこの者らを利用して、人を傷つけようとしている者です。",
  ui_story_5075_50751002_11_dialog_content = "やみくもに祟霊を敵視しては、相手の思うツボです。",
  ui_story_5075_50751002_12_dialog_content = "あんたも同じ祟霊の血筋だろ？\nだから、そんなことが言えるんだ！",
  ui_story_5075_50751002_13_dialog_content = "ですが、私には皆さんと同じ光霊の血筋が流れています。\nリン家の商いもまた人を相手にしており、祟霊ではありません。",
  ui_story_5075_50751002_14_dialog_content = "人に不利なことをする理由があるでしょうか？",
  ui_story_5075_50751002_15_dialog_content = "…",
  ui_story_5075_50751002_16_dialog_content = "言葉だけでは、信じていただけないのは当然です。",
  ui_story_5075_50751002_17_dialog_content = "ですが、リン家商会の名に誓って、\n私が必ずや証拠を見つけ、真相を明らかにしてみせます。",
  ui_story_5075_50751002_18_dialog_content = "皆さんも悪しき者に利用され、\nその張本人がのうのうと暮らしているのは許せないはずです。",
  ui_story_5075_50751002_19_dialog_content = "そんなこと言われてもよ…",
  ui_story_5075_50751002_20_dialog_content = "（やっぱり、なかなか疑いは消えないよね…\nかといって、証拠もないし…そうだ！）",
  ui_story_5075_50751002_21_dialog_content = "強制感知！",
  ui_story_5075_50751002_22_dialog_content = "（お願い！ほんの少しでもいいから、\n僕が見たことを他の皆にも伝えて…）",
  ui_story_5075_50751002_23_dialog_content = "皆さん、この祟霊たちを見てください！",
  ui_story_5075_50751002_24_dialog_content = "あ、あれは…何だ！？",
  ui_story_5075_50751002_25_dialog_content = "黒幕が祟霊を操るのに使っている力です。",
  ui_story_5075_50751002_26_dialog_content = "この力が存在するかぎり、\nいくら祟霊たちを追い払っても無駄なんです。",
  ui_story_5075_50751002_27_dialog_content = "嘘を言ってるわけじゃ…なさそうだが…",
  ui_story_5075_50751002_28_dialog_content = "確かに俺たちは長いこと、\nリン家のおかげで安泰に暮らしてきたが…",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>人々は小声でしばらく相談していた。\nその後、1人の代表が進み出てきた</color>",
  ui_story_5075_50751002_30_dialog_content = "ひとまず、信用してやる。",
  ui_story_5075_50751002_31_dialog_content = "今日はもう遅いし、俺たちもここでいつまでも油を売ってるわけにはいかない。",
  ui_story_5075_50751002_32_dialog_content = "だが、城内にはまだたくさんの祟霊がうろついてる。\nあんたたちが調査している間に何かあってもおかしくない。",
  ui_story_5075_50751002_33_dialog_content = "だから、こっちにも条件がある。",
  ui_story_5075_50751002_34_dialog_content = "春新節までに必ず解決して、いい年を越させてくれ。",
  ui_story_5075_50751002_35_dialog_content = "分かりました。",
  ui_story_5075_50751002_36_dialog_content = "そうそう、年越しなんだから、一刻も早く解決しましょう！",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>ユエが人手を増やし、人々の説得に当たらせたおかげで、\n集まっていた人々も次々と立ち去っていった。</color>",
  ui_story_5075_50751002_38_dialog_content = "手助けに感謝する。",
  ui_story_5075_50751002_39_dialog_content = "あれだけの人数とやり合うのは、\n俺1人じゃ、さすがに大変だった。",
  ui_story_5075_50751002_40_dialog_content = "「やり合う」って…本当に殴り合うつもりだったの…？",
  ui_story_5075_50751002_41_dialog_content = "それにしても、春新節はもう2日後だよね。\nそんなに時間はないよ。",
  ui_story_5075_50751002_42_dialog_content = "幸い、手がかりはたくさんつかんでるけど。",
  ui_story_5075_50751002_43_dialog_content = "事の発端は、誰かがシンゲイの封印を解いたことだよね。\nそのせいで、かつてクロミズチを操っていた力があふれ出てきた。",
  ui_story_5075_50751002_44_dialog_content = "その力は特別なものではあったけど、\n本質的には暗力と変わらない。",
  ui_story_5075_50751002_45_dialog_content = "暗力は大量の暗鬼を海辺に引き寄せる。\nそのせいでリン家は商船を出航できず、商売ができなくなった。",
  ui_story_5075_50751002_46_dialog_content = "やむなく当主さんは昔リン家に協力してくれていた祟霊のイヨウを訪ね、\n暗鬼が集まった理由を調べてもらえるよう頼んだ。",
  ui_story_5075_50751002_47_dialog_content = "でも、調査に向かったイヨウは黒い気に浸食されて、\n今はリン家への強い恨みだけを残してる。",
  ui_story_5075_50751002_48_dialog_content = "一方、黒い気は憑りつく器を見つけたことで、動きがより活発になり、\n周りの祟霊にも影響を及ぼし始めた。",
  ui_story_5075_50751002_49_dialog_content = "さらには、皓津の城内まで広がってしまった。",
  ui_story_5075_50751002_50_dialog_content = "つまり、とにかくイヨウを見つけて、\n憑りついた黒い気を祓わなきゃいけないってことだね。",
  ui_story_5075_50751002_51_dialog_content = "その後は、シンゲイが昔そうしたように黒い気の力を封印すればいい。",
  ui_story_5075_50751002_52_dialog_content = "だったら、さっさと出発するぞ！",
  ui_story_5075_50751002_53_dialog_content = "チュー！",
  ui_story_5075_50751002_54_dialog_content = "守祟浄火！",
  ui_story_5075_50751002_55_dialog_content = "くそっ！城内にかなり黒い気が広がってやがる。\n次から次へと祟霊たちが影響を受けてるぞ。",
  ui_story_5075_50751002_56_dialog_content = "ラショウ、君はここに残って。",
  ui_story_5075_50751002_57_dialog_content = "祟霊たちには君の助けが必要だよ。",
  ui_story_5075_50751002_58_dialog_content = "そうだな。だが、その前に――",
  ui_story_5075_50751002_59_dialog_content = "え、なに…？",
  ui_story_5075_50751002_60_dialog_content = "拳を合わせようぜ。",
  ui_story_5075_50751002_61_dialog_content = "これで、俺たちは苦難を共にしたダチだ。",
  ui_story_5075_50751002_62_dialog_content = "戻ったら、新鮮な菱の実を食わせてやるよ。",
  ui_story_5075_50751002_63_dialog_content = "うん！",
  ui_story_5075_50751002_64_dialog_content = "じゃ、俺は黒い気に浸食された祟霊たちを探すことにする。\nあんたらも頑張れよ！",
  ui_story_5075_50751002_65_dialog_content = "僕もユエに…あれ？",
  ui_story_5075_50751002_66_dialog_content = "使者様！ようやく見つけましたよ！",
  ui_story_5075_50751002_67_dialog_content = "あなたという方はまったく…行動的というか…",
  ui_story_5075_50751002_68_dialog_content = "管理官さん…ど、どうしてここに？",
  ui_story_5075_50751002_69_dialog_content = "もちろん、使者様の安全をお守りするためです。\n今城内には妖がはびこっているのです。",
  ui_story_5075_50751002_70_dialog_content = "私どもと共に迎賓館へお戻りくださいませ。",
  ui_story_5075_50751002_71_dialog_content = "大事な用事があるんです。今はまだ帰れません。",
  ui_story_5075_50751002_72_dialog_content = "困ります。あなた様は海の向こうの大陸から\nいらした賓客でいらっしゃいますよ。",
  ui_story_5075_50751002_73_dialog_content = "あなた様に何かあれば、私どもの首が飛ぶのです。\nどうか、お察しください。",
  ui_story_5075_50751002_74_dialog_content = "使者様を迎賓館へ！",
  ui_story_5075_50751002_75_dialog_content = "ちょっと待ってください！放して…うう。",
  ui_story_5075_50751002_76_dialog_content = "PlayerName、戻ったわ。",
  ui_story_5075_50751002_77_dialog_content = "…PlayerName？",
  ui_story_5075_50751101_1_dialog_content = "花よ、乱れ咲け！",
  ui_story_5075_50751101_2_dialog_content = "うう…",
  ui_story_5075_50751101_3_dialog_content = "見たところ、刺客のようじゃが、\nしつこく攻撃するわりには、一向に殺意が感じられぬのう。",
  ui_story_5075_50751101_4_dialog_content = "目的は、わらわの足止めか？",
  ui_story_5075_50751101_5_dialog_content = "…",
  ui_story_5075_50751101_6_dialog_content = "わらわが急所を突く素振りを見せたというに、\nお主らは反撃しようとせなんだ。",
  ui_story_5075_50751101_7_dialog_content = "これまで幾人にもケガを負わせておきながら、\nわらわにはかすり傷一つ付けようとせぬ。",
  ui_story_5075_50751101_8_dialog_content = "ふむ。ようやくPlayerNameの言ったことが分かったぞ。",
  ui_story_5075_50751101_9_dialog_content = "これまでわらわが何事もなく過ごしてこられたのは、\n確かに奇妙じゃ。",
  ui_story_5075_50751101_10_dialog_content = "そして、奇妙な事の裏には、必ず理由があるものじゃ。",
  ui_story_5075_50751101_11_dialog_content = "璇璣卿の言付け、キュウが別れ際に申したこと、\nそれから先生の言葉…",
  ui_story_5075_50751101_12_dialog_content = "かほどに手がかりがありながら、事の真相が分からぬようでは、ただの愚か者じゃ。",
  ui_story_5075_50751101_13_dialog_content = "お主ら、鄴の国の密偵であろう。",
  ui_story_5075_50751101_14_dialog_content = "！",
  ui_story_5075_50751101_15_dialog_content = "殿下、お察しの通りでございます。\nならば、私どもに危害を加える気はないことはお分かりと存じます。",
  ui_story_5075_50751101_16_dialog_content = "皓津城内には、何者がおるか分かりません。\nどうか殿下、宮中にお戻りください。",
  ui_story_5075_50751101_17_dialog_content = "わらわが宮中におらぬと、お主らの計画の妨げになるのか？",
  ui_story_5075_50751101_18_dialog_content = "わが国と済の国は往来も多く、\n裏でも表でも駆け引きや闘いを繰り返すのが常。",
  ui_story_5075_50751101_19_dialog_content = "殿下はお心の清らかなお方です。\n<color=#FFB400>殿</color>も殿下を窮地に追い込みたくはないのです。どうかお帰りを。",
  ui_story_5075_50751101_20_dialog_content = "…<color=#FFB400>殿</color>か。",
  ui_story_5075_50751101_21_dialog_content = "殿下がお戻りにならないのならば、\n私どもも失礼を働くほかございません。",
  ui_story_5075_50751101_22_dialog_content = "かかれ！",
  ui_story_5075_50751101_23_dialog_content = "風よ――",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5075_50751101_25_dialog_content = "殿下、おケガはございませんか。",
  ui_story_5075_50751101_26_dialog_content = "キュウ？お主は引き離されて、当分戻らぬものと思っておったぞ。",
  ui_story_5075_50751101_27_dialog_content = "キュウの使命は殿下をお守りすることでございます。",
  ui_story_5075_50751101_28_dialog_content = "殿下がこのキュウをご入用の際には、\nいつであろうと、どこであろうと必ず馳せ参じます。",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>1本の腕が突然キュウの足首をつかんだ。</color>",
  ui_story_5075_50751101_30_dialog_content = "霜刃…様…いけません…",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5075_50751101_32_dialog_content = "どうやら、お主には聞かねばならぬことが多そうじゃのう。",
  ui_story_5075_50751101_33_dialog_content = "じゃが、今は急がねばならぬことがある。\nわらわと共にPlayerNameのもとへ行くのじゃ。",
  ui_story_5075_50751101_34_dialog_content = "殿下はPlayerName様がどちらにおいでかご存じなのですか？",
  ui_story_5075_50751101_35_dialog_content = "慌てて出てきてしもうたからのう。まだ…",
  ui_story_5075_50751101_36_dialog_content = "前途の風水はいかに、乾坤と陰陽の卦象はいかに？\n知りたいことがあるのなら、一つ占ってみてはいかがです？",
  ui_story_5075_50751101_37_dialog_content = "…テンカンか。",
  ui_story_5075_50751101_38_dialog_content = "お主、見ておったのか？",
  ui_story_5075_50751101_39_dialog_content = "何をおっしゃってるんですかねぇ？\nアメ細工を売り終わったところ、突然何かが降りてきましてね。",
  ui_story_5075_50751101_40_dialog_content = "この方向に進めば、貴人に会えると感じたもんですから、\n運試しと思って来ただけです。",
  ui_story_5075_50751101_41_dialog_content = "見ちゃいけないものは何一つ、見ちゃいませんよ。",
  ui_story_5075_50751101_42_dialog_content = "もうよい、こやつに構ってはおれぬ。",
  ui_story_5075_50751101_43_dialog_content = "はぁ…新しいお客さんを見つけるってのは難しいもんですねぇ。\nやはりPlayerNameの旦那はいい人です。何を言っても信じてくれますからねぇ。",
  ui_story_5075_50751101_44_dialog_content = "…PlayerNameに会うたのか？",
  ui_story_5075_50751101_45_dialog_content = "もちろんですよ。梅の花のアメ細工と詩を1篇贈ったんです。",
  ui_story_5075_50751101_46_dialog_content = "お礼はご無用ですよ。",
  ui_story_5075_50751101_47_dialog_content = "もっともじゃ。なにゆえわらわがお主に感謝せねばならぬ？",
  ui_story_5075_50751101_48_dialog_content = "じゃが、PlayerNameがどこにいるのか教えるならば、\nお主にも感謝せねばならぬのう。",
  ui_story_5075_50751101_49_dialog_content = "旦那なら魚林街ですよ。\nただ、お急ぎになった方がいいですねぇ。",
  ui_story_5075_50751101_50_dialog_content = "他の何者かに奪われでもしたら、大変ですからねぇ。",
  ui_story_5075_50751101_51_dialog_content = "…キュウ、行くぞ。",
  ui_story_5075_50751101_52_dialog_content = "お待ちください。今日は1日アメ細工を売っていたもんで、\nちとうずうずしてたんです。",
  ui_story_5075_50751101_53_dialog_content = "今日の一番のお客さんですから、タダで占って差し上げましょう。",
  ui_story_5075_50751101_54_dialog_content = "占いによれば、これから東南の方角に行くことになるでしょう。\nそこで、ある貴人に会えますよ。",
  ui_story_5075_50751101_55_dialog_content = "魚林街はこの東南にある。お主が自分で言うたのじゃろ。",
  ui_story_5075_50751101_56_dialog_content = "でも、殿下は魚林街に行くかどうか、\nおっしゃってなかったと思いますがね。",
  ui_story_5075_50751101_57_dialog_content = "お主の戯言を聞いておる暇はない。",
  ui_story_5075_50751101_58_dialog_content = "「命」というのは、そういうもんです。",
  ui_story_5075_50751101_59_dialog_content = "タンドウ殿下、卦ってもんは命を天地に問い、\n神明に問うもんです。",
  ui_story_5075_50751101_60_dialog_content = "でも、最も当たる方法は「己に問う」ことなんですねぇ。",
  ui_story_5075_50751101_61_dialog_content = "己が思い、欲し、成せば、それが「命」となるんです。",
  ui_story_5075_50751101_62_dialog_content = "おや、知らぬ間にだいぶ殿下のお時間を割いてしまったようです。\nお話はここまでにしましょう。お気をつけて。",
  ui_story_5075_50751101_63_dialog_content = "…",
  ui_story_5075_50751101_64_dialog_content = "感謝する。",
  ui_story_5075_50751101_65_dialog_content = "どういたしまして。またいらしてください。",
  ui_story_5075_50751101_66_dialog_content = "安心するがよい。二度と来ぬ。",
  ui_story_5075_50751102_1_dialog_content = "うう…",
  ui_story_5075_50751102_2_dialog_content = "ここは…迎賓館じゃないよね？",
  ui_story_5075_50751102_3_dialog_content = "賓客だなんだって言っておきながら、\nその賓客を気絶させて誘拐する人なんて初めてだよ。",
  ui_story_5075_50751102_4_dialog_content = "大人しくしていてくだされば、\nこんな手荒な真似をするつもりはなかったんですよ。",
  ui_story_5075_50751102_5_dialog_content = "迎賓館の管理官という身分は何かと便利でしたからね。\nそのまま変わらずにいられたら、よかったんですが。",
  ui_story_5075_50751102_6_dialog_content = "でも、まさかあなたがここまで有能とは思いませんでした。\nリン家まで動かせるとはね。",
  ui_story_5075_50751102_7_dialog_content = "このままでは、苦労して起こした騒ぎも、\nあなたに解決されてしまいます。",
  ui_story_5075_50751102_8_dialog_content = "つまり、全部君たちの仕業だってこと？",
  ui_story_5075_50751102_9_dialog_content = "クロミズチの封印を解いて、黒い気を城内に蔓延させ、\n人と祟霊の対立をあおったのも、全部君たちなの？",
  ui_story_5075_50751102_10_dialog_content = "いったい何がしたいの？",
  ui_story_5075_50751102_11_dialog_content = "あなたには関係のないことです。",
  ui_story_5075_50751102_12_dialog_content = "ここでしばらくお休みになっていてください。\nすべて片が付いたら、<color=#FFB400>我々</color>が開放しに参りますよ。",
  ui_story_5075_50751102_13_dialog_content = "<color=#FFB400>「我々」</color>って、済の朝廷内にいる仲間のこと？",
  ui_story_5075_50751102_14_dialog_content = "国師に言われたんですね？",
  ui_story_5075_50751102_15_dialog_content = "あの古だぬきは、我々の存在にまだ気づかぬうちから、\n再三にわたって邪魔をしてきたんですが――",
  ui_story_5075_50751102_16_dialog_content = "それも、もう長くは続かないでしょうね。",
  ui_story_5075_50751102_17_dialog_content = "それもこれも、あなたのおかげですよ。",
  ui_story_5075_50751102_18_dialog_content = "え、僕？",
  ui_story_5075_50751102_19_dialog_content = "あなたが宮中に上がったあの日、\n国師と郡主とお話しになっているのを聞いたんです。",
  ui_story_5075_50751102_20_dialog_content = "厳格に警備されているようで、\n実は宮中というのは、世の中で最も秘密のない場所なんですよ。",
  ui_story_5075_50751102_21_dialog_content = "我々の手の者が朝廷に入り込んでいるのは知っていても、\nあの古だぬきも、まだ誰だかは分かっていないんです。",
  ui_story_5075_50751102_22_dialog_content = "だから、あなたのようなよそ者を使ったんですよ。",
  ui_story_5075_50751102_23_dialog_content = "でも、そのおかげで、こちらに絶好の好機が訪れました。",
  ui_story_5075_50751102_24_dialog_content = "菓子を贈るふりをして、巡検司の札を入れ物に忍ばせ、\nあなたに渡したでしょう？",
  ui_story_5075_50751102_25_dialog_content = "あなたが本当にあの札を使って、この窮地を解決したとすれば、\n古だぬきの行いは、ただの緊急手段――",
  ui_story_5075_50751102_26_dialog_content = "とがめられたとしても、弁解の余地はあります。",
  ui_story_5075_50751102_27_dialog_content = "しかし、あなたが行動を起こさないまま、\n札だけが発見されたなら…",
  ui_story_5075_50751102_28_dialog_content = "そんな重要な物を国師たる者が、\n他国、しかも海の向こうの大陸の者に渡し――",
  ui_story_5075_50751102_29_dialog_content = "その人物もまた皓津の混乱の中、行方不明となったならば――",
  ui_story_5075_50751102_30_dialog_content = "あなた方2人が結託し、済の国を陥れようとしたという主張を信じない人はいないでしょうね。",
  ui_story_5075_50751102_31_dialog_content = "そうなれば、朝廷は国師を反逆罪で罰することになるでしょう。",
  ui_story_5075_50751102_32_dialog_content = "さてさて…札はどこにやったんですか？\n服の隠しに入れたんですか？それとも袖でしょうか？",
  ui_story_5075_50751102_33_dialog_content = "無駄だよ。僕は持ってない。",
  ui_story_5075_50751102_34_dialog_content = "国師さんから内密に調べるように言われた時、\n僕の近くにいる人たちがあやしいのかもって思った。",
  ui_story_5075_50751102_35_dialog_content = "その後、あのお菓子をもらってから、\nあやしいのは迎賓館にいる人だって確信したんだ。",
  ui_story_5075_50751102_36_dialog_content = "だとしたら、お菓子の入れ物に何が入ってたか、\n隠し通せるとは限らない。",
  ui_story_5075_50751102_37_dialog_content = "だから、一刻も早く迎賓館を離れなきゃって思ったんだ。",
  ui_story_5075_50751102_38_dialog_content = "だからどうしたというんです？\n結局、巡検司を動かす機会を失ったことに変わりはないでしょう？",
  ui_story_5075_50751102_39_dialog_content = "しかも、異邦からやってきたあなたには、この龍州で大した知り合いもいない…",
  ui_story_5075_50751102_40_dialog_content = "郡主とて今は宮中、我々の密偵の監視下にあります。\n連絡を取り合うことはできません。",
  ui_story_5075_50751102_41_dialog_content = "巡検司の札を誰に渡したかくらい、少し調べれば分かることです。",
  ui_story_5075_50751102_42_dialog_content = "ああ、分かりました。リン家ですね。",
  ui_story_5075_50751102_43_dialog_content = "リン家の当主は利益のためなら、\nどんな大きな危険でも冒しますからね。",
  ui_story_5075_50751102_44_dialog_content = "しかし…巡検司の札を前科のある商人に渡すとは…ハハハ！",
  ui_story_5075_50751102_45_dialog_content = "いくら済が商いを重んじる国でも、\nこんな前代未聞の荒唐無稽、断罪するのは簡単です。",
  ui_story_5075_50751102_46_dialog_content = "さっきは一瞬、何か特別な切り札でもあるのかと思いましたが、\nしょせんは世間知らずのお坊ちゃんにすぎなかったようです。",
  ui_story_5075_50751102_47_dialog_content = "私は部下たちの様子を見に行かなきゃならないので、\nこれで失礼しますよ。",
  ui_story_5075_50751102_48_dialog_content = "札をリン家に渡したなんて、一言も言ってないよ。",
  ui_story_5075_50751102_49_dialog_content = "リン家じゃないとしたら、\n前にあなたとつるんでいた2人に渡したんでしょう？",
  ui_story_5075_50751102_50_dialog_content = "庶民も商家も、大した違いはありませんよ。",
  ui_story_5075_50751102_51_dialog_content = "庶民じゃないよ。",
  ui_story_5075_50751102_52_dialog_content = "<size=45><color=#FFB400>灼華郡主</color>だ。</size>",
  ui_story_5075_50751102_53_dialog_content = "おや、私の話を聞いていなかったんですか？\n郡主には監視を付けてあるんです。郡主に札を渡すなど…",
  ui_story_5075_50751102_54_dialog_content = "<size=45>タンドウは必ず来る。</size>",
  ui_story_5075_50751102_55_dialog_content = "巡検司の札、紙切れに記されたリン家の住所、\n国師さんの導き――",
  ui_story_5075_50751102_56_dialog_content = "そして、それが入っていたカイドウの花の炉――",
  ui_story_5075_50751102_57_dialog_content = "これだけのものを動かせるのはタンドウしかいない！",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5075_50751102_59_dialog_content = "少しでも動いてみなさい。首が落ちますよ。",
  ui_story_5075_50751102_60_dialog_content = "PlayerName、大事ないか？",
  ui_story_5075_50751102_61_dialog_content = "タンドウ！キュウ！",
  ui_story_5075_50751102_62_dialog_content = "お、お前たち…な、なぜ、ここに…うわっ！",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>タンドウは力いっぱい管理官の顔を引っ張った。</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>すると、セミの羽のように薄い仮面がはがれ、\nまったく見たことのない、もう1つの顔が現れた。</color>",
  ui_story_5075_50751102_65_dialog_content = "やはり、迎賓館の管理官ではなかったのう。\nただその身分を借りていただけというわけじゃの。",
  ui_story_5075_50751102_66_dialog_content = "…私を捕らえたところで、無駄です。",
  ui_story_5075_50751102_67_dialog_content = "主は智略に長けた御方、我々のような<color=#FFB400>天命を受けし者</color>はいくらでもいるのです。",
  ui_story_5075_50751102_68_dialog_content = "今や計画も完成に近づいている――海の封印は破られ、\n眠りについていた悪夢が解き放たれたんです！",
  ui_story_5075_50751102_69_dialog_content = "皓津の秩序が崩壊すれば、我々がその隙に入り込み、\nいともたやすく、この済の国を我がものにできるでしょう！",
  ui_story_5075_50751102_70_dialog_content = "神仏のご加護でもないかぎり、\nあなたたちなど…ううっ！",
  ui_story_5075_50751102_71_dialog_content = "わらわを呼んだか？",
  ui_story_5075_50751102_72_dialog_content = "ぐっ…ううっ！！",
  ui_story_5075_50751102_73_dialog_content = "シンゲイ？どうしてここに？",
  ui_story_5075_50751102_74_dialog_content = "封印を破りし者を追っていたのじゃが、見失ってしもうてのう。",
  ui_story_5075_50751102_75_dialog_content = "ゆえにやつの匂いをたどって、\nやつが会った者、寄った所を一通り探っていたのじゃ。",
  ui_story_5075_50751102_76_dialog_content = "そうしたら、ここにたどり着いたのじゃ。",
  ui_story_5075_50751102_77_dialog_content = "うう！うぐっ！",
  ui_story_5075_50751102_78_dialog_content = "それと、途中でアメ細工職人に会うてのう。",
  ui_story_5075_50751102_79_dialog_content = "梅の花のアメ細工を作ってくれた人！？",
  ui_story_5075_50751102_80_dialog_content = "そうじゃ！ずいぶんと太っ腹でのう。\n山のようにアメ細工を捧げおったわい。",
  ui_story_5075_50751102_81_dialog_content = "じゃが、願い事はただ1つ。わらわが立ち寄った所に、\nかならず梅の花の枝を挿してほしいとのことじゃった。",
  ui_story_5075_50751102_82_dialog_content = "言う通りにしたの？",
  ui_story_5075_50751102_83_dialog_content = "むろんじゃ。供え物をもろうたのじゃからのう。",
  ui_story_5075_50751102_84_dialog_content = "この外にも挿してきたぞ。",
  ui_story_5075_50751102_85_dialog_content = "よかった…タンドウ！",
  ui_story_5075_50751102_86_dialog_content = "うむ。",
  ui_story_5075_50751102_87_dialog_content = "リン家の当主より、札は受け取った。\nリン家の護衛たちも援護してくれておる。",
  ui_story_5075_50751102_88_dialog_content = "今リン家の護衛たちがシュウ殿の指揮の下、各配置につき、\n妖魔と狂暴化した祟霊を抑えておる。",
  ui_story_5075_50751102_89_dialog_content = "巡検司もこの「天命を受けし者」とやらを片付けた後、\n援護に加わることになっておる。",
  ui_story_5075_50751102_90_dialog_content = "PlayerName…わらわの好きな花を覚えていてくれて、感謝する。",
  ui_story_5075_50751102_91_dialog_content = "あはは、うまくいったなら、それでいいんだ！\n今、外の状況はどうなってるの？",
  ui_story_5075_50751102_92_dialog_content = "城内はひとまず大丈夫じゃ。\n城外はユエに頼まねばならぬ。",
  ui_story_5075_50751102_93_dialog_content = "城外…管理官…いや、この人がさっき、\n計画は完成に近づいてるって言ってたけど…",
  ui_story_5075_50751102_94_dialog_content = "イヨウはたぶん、黒い気と完全に一体化しようとしてる。",
  ui_story_5075_50751102_95_dialog_content = "急いでイヨウと話さなきゃ！",
  ui_story_5075_50751102_96_dialog_content = "それなら、こっちへ。",
  ui_story_5075_50751102_97_dialog_content = "舟を用意したわ。水路なら直接海に出られるわ。",
  ui_story_5075_50751102_98_dialog_content = "城内はタンドウに頼んだよ。\n僕はユエと一緒にイヨウを…え？",
  ui_story_5075_50751102_99_dialog_content = "龍女…様？",
  ui_story_5075_50751102_100_dialog_content = "よく分からぬが、封印を破りし者は、\nわらわの代わりに誰かが罰してくれたのじゃろ？",
  ui_story_5075_50751102_101_dialog_content = "ならば、わらわはおぬしと共に海へ行こう。",
  ui_story_5075_50751102_102_dialog_content = "空の末裔の力だけではおそらく、\n彼の者とイヨウの成す幻に相対するのは難儀であろう。",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_2_dialog_content = "うーん…ごめん、僕、うっかり寝ちゃったみたいだ。\nもう着いたの？ユ…",
  ui_story_5075_50751201_3_dialog_content = "あれ？",
  ui_story_5075_50751201_4_dialog_content = "今、誰を呼ぼうとしてたんだっけ？",
  ui_story_5075_50751201_5_dialog_content = "そういえば、どうしてまた舟に乗ってるんだろう？",
  ui_story_5075_50751201_6_dialog_content = "うっ…頭が痛い。",
  ui_story_5075_50751201_7_dialog_content = "おい、何をぼうっとしてやがんだ！？\nさっさと荷を運びやがれ！船がもうすぐ出ちまうぞ！",
  ui_story_5075_50751201_8_dialog_content = "え？に、荷を運ぶって、僕が？",
  ui_story_5075_50751201_9_dialog_content = "他に誰がいるってんだ？",
  ui_story_5075_50751201_10_dialog_content = "お前が自分で言ったんだろ。ソラなんとかっつー家族が病気だから、\n薬を買うために金を稼がなきゃいけねーんだって。",
  ui_story_5075_50751201_11_dialog_content = "はぁ…それにしても、遠洋航海なんざに出て、\n無事に帰ってこられるもんなんかなぁ。",
  ui_story_5075_50751201_12_dialog_content = "幸い、リン家は小っこい商会とはいえ、報酬をずいぶん弾んでくれたがな。\n手付金として、半分も前払いしてくれた。",
  ui_story_5075_50751201_13_dialog_content = "この金があれば、女房子どもにいいもん食わしてやれるぞ。",
  ui_story_5075_50751201_14_dialog_content = "お前んとこも、薬代はひとまず安心だな。",
  ui_story_5075_50751201_15_dialog_content = "（何かおかしい…でも、確かにそんなことがあった気もする…）",
  ui_story_5075_50751201_16_dialog_content = "（うっ…また頭痛だ）",
  ui_story_5075_50751201_17_dialog_content = "（とにかく…荷物を運ぼう）",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_19_dialog_content = "え？どういうこと？",
  ui_story_5075_50751201_20_dialog_content = "急に周りに霧が立ち込めてきたよ？",
  ui_story_5075_50751201_21_dialog_content = "お前、腹が減りすぎてボケちまったか？\n船はもう半月近くも霧の中をさまよってるじゃねーか。",
  ui_story_5075_50751201_22_dialog_content = "この船も、乗ってる俺たちも、ここで終いだな。",
  ui_story_5075_50751201_23_dialog_content = "女房も子どもも待ってるっつーのに…\n死にたくねえ…",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>そのため息に合わせるかのように、\n辺りから嗚咽が聞こえてきた</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>船員と商人が甲板のあちこちに倒れ、\nその呼吸からは、疲労と絶望が伝わってくる</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5075_50751201_27_dialog_content = "（何かが、船にぶつかった！？）",
  ui_story_5075_50751201_28_dialog_content = "お、おい…見てみろ！",
  ui_story_5075_50751201_29_dialog_content = "魚だ！魚が船を押してくれてるぞ！",
  ui_story_5075_50751201_30_dialog_content = "ミズチウオだ！吉兆だぞ！\n今は冬だから、ミズチウオは龍州に帰る！",
  ui_story_5075_50751201_31_dialog_content = "ミズチウオについていけば、俺たち助かるぞ！",
  ui_story_5075_50751201_32_dialog_content = "おい、見ただろ！？まさに神のご加護だ！\n神様が俺たちを守ってくれたんだ！",
  ui_story_5075_50751201_33_dialog_content = "（錯覚かな？先頭を泳いでるお魚…見覚えがあるような…）",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_35_dialog_content = "ワタシハ…ミズチウオ。",
  ui_story_5075_50751201_36_dialog_content = "海ノ中ヲオヨギ、獲物ヲトラエ、\n時ニ光力術ヲ学ブ同類ニ教エヲ乞ウテイル。",
  ui_story_5075_50751201_37_dialog_content = "毎年冬ニナルト、群ト共ニ生マレ故郷の――龍州ニ戻ル。",
  ui_story_5075_50751201_38_dialog_content = "アル日、ワタシタチハ、海上デ方向ヲ見失ッタ船ヲ見ツケタ。",
  ui_story_5075_50751201_39_dialog_content = "船ハワタシタチト共ニ龍州ニ戻リ、ヌシ様ト約束ヲシダ。",
  ui_story_5075_50751201_40_dialog_content = "ソノ後、毎年ワタシタチハ、\nソノ船ト共ニ故郷ニ帰ルヨウニナッタ。",
  ui_story_5075_50751201_41_dialog_content = "ワタシタチハ、船ヲ導キナガラ帰路ヲ急ギ、\n彼ラハ、ワタシタチニ食ベ物ヲクレル。",
  ui_story_5075_50751201_42_dialog_content = "ソンナ関係ニ、ワタシタチモ喜ンデイタ。",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_44_dialog_content = "またミズチウオを見てたんですか？",
  ui_story_5075_50751201_45_dialog_content = "僕はただ、あのミズチウオ…\nどこか見覚えがあるなって思ってただけだよ。",
  ui_story_5075_50751201_46_dialog_content = "ミズチウオなんてどれも同じでしょう？\n魚なんざ見てないで、こっちを見てくださいよ。",
  ui_story_5075_50751201_47_dialog_content = "今回の航海の給金です。",
  ui_story_5075_50751201_48_dialog_content = "こんなにたくさん！？",
  ui_story_5075_50751201_49_dialog_content = "リン家が遠洋航路を拓いてからというもの、給金は上がる一方です。\nこれくらい大したことありませんよ。",
  ui_story_5075_50751201_50_dialog_content = "もっと稼ぎたくありませんか？",
  ui_story_5075_50751201_51_dialog_content = "もっと…稼ぐ…？",
  ui_story_5075_50751201_52_dialog_content = "出る前に、他の奴らとも話したんですが、\nリン家商会はどんどん大きくなってるでしょう？",
  ui_story_5075_50751201_53_dialog_content = "アストラなんかとの交易も需要は高くなるばかりだし、\n1年に1回の航海じゃ足りませんよ。",
  ui_story_5075_50751201_54_dialog_content = "俺たち連名で、年に2回航海できないか、\n当主に相談しようじゃありませんか。",
  ui_story_5075_50751201_55_dialog_content = "たった2回でいいんですよ。どうです？",
  ui_story_5075_50751201_56_dialog_content = "でも、ミズチウオが龍州に戻るのは、冬の1回だけでしょ？",
  ui_story_5075_50751201_57_dialog_content = "ミズチウオは普段から海ん中を泳ぎ回ってるじゃありませんか？\n龍州に戻るのが1回増えたところで構いやしませんよ。",
  ui_story_5075_50751201_58_dialog_content = "俺たちが稼げば、奴らにだってたくさん食い物をあげられるんです。",
  ui_story_5075_50751201_59_dialog_content = "ミズチウオは食べ物が欲しいわけじゃないよ。",
  ui_story_5075_50751201_60_dialog_content = "チッ、頭が固てぇな。まぁ、いいですよ。他の奴らは賛同してるんだし、\nあんた1人欠けたところでどうってことありません。",
  ui_story_5075_50751201_61_dialog_content = "待ってよ。僕は――",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_63_dialog_content = "ヌシ様ガ言ッタ。コレカラハ、夏モ龍州ニ帰ル、ト。",
  ui_story_5075_50751201_64_dialog_content = "夏ノ海ハ、熱イカラ、嫌イダ。",
  ui_story_5075_50751201_65_dialog_content = "デモ、船ニ乗ル友ダチガ、困ッテイル。",
  ui_story_5075_50751201_66_dialog_content = "ダカラ、夏モ帰ル。",
  ui_story_5075_50751201_67_dialog_content = "タダ、タクサン泳ガナケレバナラナイ。疲レル。",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_69_dialog_content = "今日、皆を呼んだのは他でもない。",
  ui_story_5075_50751201_70_dialog_content = "わがリン家はこの度、央京と商いをすることになった。\nよって、今年は遠洋航海を1回増やすことにする。",
  ui_story_5075_50751201_71_dialog_content = "ちょっと待ってください。ミズチウオとの約束では、\n彼らの助けを得られるのは、年に1回じゃなかったんですか？",
  ui_story_5075_50751201_72_dialog_content = "夏に龍州に戻るだけでも、彼らの習性に反しているのに、\nさらに回数を増やせば――",
  ui_story_5075_50751201_73_dialog_content = "だが、央京との商いは、商会にとって夢にまで見た大仕事だ。",
  ui_story_5075_50751201_74_dialog_content = "これを受けることで、リン家がどれだけの利益を得られるか、\n分かっておるのか？",
  ui_story_5075_50751201_75_dialog_content = "確かにミズチウオには苦労を掛けてしまう。\n今度あらためて、私自ら、かの祟霊に詫びを入れに行く。",
  ui_story_5075_50751201_76_dialog_content = "すでに決まったことだ。",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_78_dialog_content = "今年ハ、3回モ往復シナケレバナラナイ。",
  ui_story_5075_50751201_79_dialog_content = "ヌシ様ガ言ッタ。今年ダケダト。船ニ乗ル友ダチガ、困ッテイル。",
  ui_story_5075_50751201_80_dialog_content = "デモ、次ノ年モ3回ダッタ。\nソノ次ノ年モ3回ダッタ。",
  ui_story_5075_50751201_81_dialog_content = "周リノ同族ガ、イナクナッタ。",
  ui_story_5075_50751201_82_dialog_content = "ヌシ様モ、早ク、死期ヲ迎エタ。",
  ui_story_5075_50751201_83_dialog_content = "コレカラハ、ワタシガヌシ。",
  ui_story_5075_50751201_84_dialog_content = "船ニ乗ル友ダチガ来テ、ワタシヲ陸ニ上ゲタ。\nソシテ、木ノ家ノ中ノ、大キナ水槽ニ入レラレタ。",
  ui_story_5075_50751201_85_dialog_content = "水槽ハ小サイ。自由ニ泳ゲナイ。",
  ui_story_5075_50751201_86_dialog_content = "ツライ。",
  ui_story_5075_50751201_87_dialog_content = "ソノマタ次ノ年モ、3回航海ヲシタ。",
  ui_story_5075_50751201_88_dialog_content = "デモ、ワタシハ海デ泳ゲナカッタ。",
  ui_story_5075_50751201_89_dialog_content = "水槽ゴト、ワタシヲ船ニ乗セテ、毎日食ベルモノヲクレタ。\n同族ニ信号ヲ送レト言ワレタ。",
  ui_story_5075_50751201_90_dialog_content = "友ダチガ言ッタ。\nコレハ、祟霊ヘノ「レイギ」、「マツッテイル」ノダト。",
  ui_story_5075_50751201_91_dialog_content = "人の姿になれるのか？",
  ui_story_5075_50751201_92_dialog_content = "…",
  ui_story_5075_50751201_93_dialog_content = "化けられるようになったばかりで、言葉はまだ話せぬか。",
  ui_story_5075_50751201_94_dialog_content = "言葉を学びたいか？私が教えてあげよう。\n君たちへの…せめてもの償いだ…",
  ui_story_5075_50751201_95_dialog_content = "いや、さようなことを言っても無駄か…",
  ui_story_5075_50751201_96_dialog_content = "私が犯した罪は、それしきのことで償えるものではない…",
  ui_story_5075_50751201_97_dialog_content = "（ワタシニハ分カッタ。コノ者ハ船ノヌシダ）",
  ui_story_5075_50751201_98_dialog_content = "（ワタシニ言葉ヲ教エ、読ミ書キヲ教エテクレタ）",
  ui_story_5075_50751201_99_dialog_content = "（デモ、コノ者ハ、ワルイヤツ。スゴク、ワルイヤツダ）",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>パシャッ</color>",
  ui_story_5075_50751201_101_dialog_content = "4回！？",
  ui_story_5075_50751201_102_dialog_content = "サイ家がこのところ、リン家の御用達の地位を虎視眈々と狙っておる。",
  ui_story_5075_50751201_103_dialog_content = "圧倒的な力を見せつけなければ、おそらく淘汰されるだろう。",
  ui_story_5075_50751201_104_dialog_content = "リン家が100年にわたって築いてきた栄光を\n私の代で終わらせるわけにはいかん。",
  ui_story_5075_50751201_105_dialog_content = "数年前から、ミズチウオの死亡率が\n異常に上がっているのを知ってるでしょう！？",
  ui_story_5075_50751201_106_dialog_content = "それが、何だというのだ？",
  ui_story_5075_50751201_107_dialog_content = "なんてことを…僕には当主さんが何をしたいのか、理解できません！",
  ui_story_5075_50751201_108_dialog_content = "取引量を増やすため、航海を2回にし、\n緊急の入用ができたと言っては、3回まで増やしました。",
  ui_story_5075_50751201_109_dialog_content = "今度はリン家の御用達の地位まで、\nミズチウオに責任を背負わせようと言うんですか！？",
  ui_story_5075_50751201_110_dialog_content = "ミズチウオは僕たちの恩人です。\nそれをリン家は仇で返すんですか！",
  ui_story_5075_50751201_111_dialog_content = "どんな言葉で飾り立てようと、\nそんなのただの貪欲でしかありません！",
  ui_story_5075_50751201_112_dialog_content = "…PlayerName…",
  ui_story_5075_50751201_113_dialog_content = "うっ…今のは…？",
  ui_story_5075_50751201_114_dialog_content = "リン家の飯を食らっておきながら、\nミズチウオにずいぶんと忠心だな。",
  ui_story_5075_50751201_115_dialog_content = "そなたのような者は、リン家にはいらん。出て行け。",
  ui_story_5075_50751201_116_dialog_content = "私は4度目の航海のことで話し合いをせねばならんのだ。\n自分で番頭の所へ行き、今日までの給金を受け取るがよい。",
  ui_story_5075_50751201_117_dialog_content = "…どうしても、船を出すんですか？",
  ui_story_5075_50751201_118_dialog_content = "何をするつもりだ？",
  ui_story_5075_50751201_119_dialog_content = "ミズチウオのヌシを海に返します。",
  ui_story_5075_50751201_120_dialog_content = "あった！この水槽だ！",
  ui_story_5075_50751201_121_dialog_content = "ごめんね。少しの間だけ水から離れるけど、がまんしてね。\n海辺についたら、すぐ…",
  ui_story_5075_50751201_122_dialog_content = "行かせてはならん！",
  ui_story_5075_50751201_123_dialog_content = "どうして急にこんなたくさん…何とかしないと…",
  ui_story_5075_50751201_124_dialog_content = "強制感知！",
  ui_story_5075_50751201_125_dialog_content = "うわぁああ！",
  ui_story_5075_50751201_126_dialog_content = "…あれ？感知…？",
  ui_story_5075_50751201_127_dialog_content = "PlayerName！",
  ui_story_5075_50751201_128_dialog_content = "シン…ゲイ？",
  ui_story_5075_50751201_129_dialog_content = "ようやく気がついたか。",
  ui_story_5075_50751201_130_dialog_content = "舟が海に入った途端、おぬしもユエも眠ってしもうての。\nいくら突いても起きなんだ。",
  ui_story_5075_50751201_131_dialog_content = "わらわ1人ではつまらぬ。早く起きい。",
  ui_story_5075_50751201_132_dialog_content = "思い出した！\n舟が海に入った途端、一面の黒い気が襲ってきたんだ。",
  ui_story_5075_50751201_133_dialog_content = "つまり、黒い気の力が僕たちを夢に…\nいや、幻に引き込んだってことかな？",
  ui_story_5075_50751201_134_dialog_content = "うーむ…同じことじゃ。",
  ui_story_5075_50751201_135_dialog_content = "ずいぶんテキトーだね！",
  ui_story_5075_50751201_136_dialog_content = "構わぬであろう。さしたることでもあるまい。",
  ui_story_5075_50751201_137_dialog_content = "それよりも、急ぎユエを起こしてやった方がよいぞ。",
  ui_story_5075_50751201_138_dialog_content = "ずいぶんと苦しそうじゃ。",
  ui_story_5075_50751201_139_dialog_content = "黒い気に犯されたの…？シンゲイ…",
  ui_story_5075_50751201_140_dialog_content = "できぬことはないが、手助けはここまでじゃ。",
  ui_story_5075_50751201_141_dialog_content = "どうして…",
  ui_story_5075_50751201_142_dialog_content = "万事神に助けを求めるは、よき習いとは言えぬのう。",
  ui_story_5075_50751201_143_dialog_content = "己のことは、己で解決せよ。",
  ui_story_5075_50751201_144_dialog_content = "…分かったよ。",
  ui_story_5075_50751201_145_option_content = "感知！",
  ui_story_5075_50751201_146_dialog_content = "ユエ！いったいどこに…？",
  ui_story_5075_50751201_147_dialog_content = "PlayerName。",
  ui_story_5075_50751201_148_dialog_content = "このミズチウオが…ユエ！？",
  ui_story_5075_50751201_149_dialog_content = "止まれ！",
  ui_story_5075_50751201_150_dialog_content = "また！？",
  ui_story_5075_50751201_151_dialog_content = "…とにかく、まずは海へ逃げよう！",
  ui_story_5075_50751201_152_dialog_content = "はぁ…はぁ…やっと、着いたね。",
  ui_story_5075_50751201_153_dialog_content = "どうして幻の中なのに、こんなに疲れるんだろう？",
  ui_story_5075_50751201_154_dialog_content = "ユエ、君はまず海の中へ…",
  ui_story_5075_50751201_155_dialog_content = "ユエ！？",
  ui_story_5075_50751201_156_dialog_content = "（海に入った途端、姿が見えなくなっちゃった…）",
  ui_story_5075_50751201_157_dialog_content = "（海の中は…黒い気が充満してる！）",
  ui_story_5075_50751201_158_dialog_content = "…",
  ui_story_5075_50751201_159_dialog_content = "（ツカレタ…ヌシ様…ハラヘッタ…ヌシ様…ツライ…）",
  ui_story_5075_50751201_160_dialog_content = "（モウ、イヤダ…カエリタイ…ヌシ様…ヌシ様…タスケテ）",
  ui_story_5075_50751201_161_dialog_content = "（タスケテ…タスケテ…ヌシ様…）",
  ui_story_5075_50751201_162_dialog_content = "（同族タチノ、信号）",
  ui_story_5075_50751201_163_dialog_content = "（バラバラノ、声。デモ、ゼンブ…ミズチウオノ、心ノ声）",
  ui_story_5075_50751201_164_dialog_content = "ソノ、コエガ。",
  ui_story_5075_50751201_165_dialog_content = "マイニチ、ヒビイテイル。",
  ui_story_5075_50751201_166_dialog_content = "ズット、ヒビイテル。",
  ui_story_5075_50751201_167_dialog_content = "ミンナ、ニクンデル。",
  ui_story_5075_50751201_168_dialog_content = "イヨウ。",
  ui_story_5075_50751201_169_dialog_content = "そういうことだったのね。",
  ui_story_5075_50751201_170_dialog_content = "私が見たものは、あなたの記憶だったのね。",
  ui_story_5075_50751201_171_dialog_content = "リン、ケ。",
  ui_story_5075_50751201_172_dialog_content = "ウラギリ、モノ。",
  ui_story_5075_50751201_173_dialog_content = "ヒトハ、シンジラレナイ。",
  ui_story_5075_50751201_174_dialog_content = "オマエモ、サカナ。",
  ui_story_5075_50751201_175_dialog_content = "オマエモ、ニクメ！",
  ui_story_5075_50751201_176_dialog_content = "ユエ！僕の声が聞こえる？",
  ui_story_5075_50751201_177_dialog_content = "今、行くよ！",
  ui_story_5075_50751201_178_dialog_content = "PlayerName、必要ないわ。",
  ui_story_5075_50751201_179_dialog_content = "えっ？",
  ui_story_5075_50751201_180_dialog_content = "リン家は、イヨウにむごいことをした。",
  ui_story_5075_50751201_181_dialog_content = "今、私はリン家の代表としてここにいるの。\nだから、イヨウが私を憎み、私に報復して当然よ。",
  ui_story_5075_50751201_182_dialog_content = "…",
  ui_story_5075_50751201_183_dialog_content = "黒い気が…止まった？",
  ui_story_5075_50751201_184_dialog_content = "チガ…ウ…",
  ui_story_5075_50751201_185_dialog_content = "チガウ…",
  ui_story_5075_50751201_186_dialog_content = "イヨウは…どうしちゃったの？急に苦しそうにしてるよ…",
  ui_story_5075_50751201_187_dialog_content = "イヨウ本人の意志じゃないからよ。",
  ui_story_5075_50751201_188_dialog_content = "私の知っているイヨウは、同族と友を思いやる子だった。\n自分の憎しみのために、他の祟霊を巻き込んだりしないわ。",
  ui_story_5075_50751201_189_dialog_content = "それに、今生きている人全員が\nリン家の先祖のようにひどい事をしたわけじゃない。",
  ui_story_5075_50751201_190_dialog_content = "さっきPlayerNameがしてくれたことも、見たでしょう？",
  ui_story_5075_50751201_191_dialog_content = "あの時、PlayerNameがリン家にいたら…\nきっと同じことをしたわ。",
  ui_story_5075_50751201_192_dialog_content = "…",
  ui_story_5075_50751201_193_dialog_content = "あなたは長い間、リン家に囚われてきた。",
  ui_story_5075_50751201_194_dialog_content = "だからこれ以上、あなたが他人から押し付けられた憎しみに\n囚われるのを見たくないの。",
  ui_story_5075_50751201_195_dialog_content = "ミズチウオの声は、私も聞いたわ。",
  ui_story_5075_50751201_196_dialog_content = "私が、あなたを助けてあげる。",
  ui_story_5075_50751201_197_dialog_content = "チ、ガウ！",
  ui_story_5075_50751201_198_dialog_content = "コノ、ニクシミハ、ワタシノモノ！",
  ui_story_5075_50751201_199_dialog_content = "オマエモ、オナジ！",
  ui_story_5075_50751201_200_dialog_content = "<size=45>ウラギリモノ！</size>",
  ui_story_5075_50751202_1_dialog_content = "よしよし、ようやく目覚めたようじゃのう。\n寝坊ばかりしておると、背が伸びぬぞ。",
  ui_story_5075_50751202_2_dialog_content = "そうなの…？だったら今日から早寝早起きすれば、\n背が伸びるかな？",
  ui_story_5075_50751202_3_dialog_content = "わらわを拝めばよいじゃろ。",
  ui_story_5075_50751202_4_dialog_content = "ユエも拝むがよい。",
  ui_story_5075_50751202_5_dialog_content = "私はもう、子どもじゃありません。",
  ui_story_5075_50751202_6_dialog_content = "わらわと比べれば、子どもじゃ。",
  ui_story_5075_50751202_7_dialog_content = "そう眉をしかめるでない。\nイヨウがおぬしと喧嘩せずに逃げてしもうただけのことじゃろ。",
  ui_story_5075_50751202_8_dialog_content = "水の中にいるならば、いつでも呼び出せるじゃろが。",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>シンゲイが突然手を挙げ、\n海に向かって一筋に金色の光を放った</color>",
  ui_story_5075_50751202_10_dialog_content = "今、君が何をしたか…聞かない方がよさそうだね…",
  ui_story_5075_50751202_11_dialog_content = "どうせもう使いものにならぬのじゃ。\n残りの封印も解いたぞ。",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>ついさっきまで穏やかだったはずの水面が\n突如うねりを上げ、大きな波が起こった</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>海の中から1つの影が空中に飛び上がり</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>海面を引き裂く無数の渦の中から、\n黒い気が果てしなく立ち上っていく</color>",
  ui_story_5075_50751202_16_dialog_content = "あやつがおぬしらの言っていたイヨウか？幼いのう。",
  ui_story_5075_50751202_17_dialog_content = "オマエノコト、シッテル。",
  ui_story_5075_50751202_18_dialog_content = "リュウ、オウ。",
  ui_story_5075_50751202_19_dialog_content = "怨念の中に込められし意識で知ったのか？\nよく覚えておったの。",
  ui_story_5075_50751202_20_dialog_content = "ワタシハ、フクシュウ、スル。",
  ui_story_5075_50751202_21_dialog_content = "テダシ、スルナ。",
  ui_story_5075_50751202_22_dialog_content = "サモナケレバ…",
  ui_story_5075_50751202_23_dialog_content = "マチヲ、シズメル。",
  ui_story_5075_50751202_24_dialog_content = "おぬしは、もしや…",
  ui_story_5075_50751202_25_dialog_content = "（シンゲイがこんな厳しい顔をするの、初めて見た）",
  ui_story_5075_50751202_26_dialog_content = "（シンゲイでも、イヨウをどうしようもないのかな…？）",
  ui_story_5075_50751202_27_dialog_content = "つまり、シンゲイが手を出したら、\n皓津城ごと水没させるってこと？",
  ui_story_5075_50751202_28_dialog_content = "皓津城の住民全員を人質にする気ね。",
  ui_story_5075_50751202_29_dialog_content = "うむ。やはりな…",
  ui_story_5075_50751202_30_dialog_content = "わらわを脅しておるのじゃな！",
  ui_story_5075_50751202_31_dialog_content = "えっ？",
  ui_story_5075_50751202_32_dialog_content = "この何百年というもの、わらわを脅す者などおらんかった。\n実に新鮮じゃ！",
  ui_story_5075_50751202_33_dialog_content = "しかし、よく考えてみれば、\nこの件とわらわとは何の関わりもない。",
  ui_story_5075_50751202_34_dialog_content = "色々と複雑な事情があるようじゃが、\nわらわにはよく分からぬ。",
  ui_story_5075_50751202_35_dialog_content = "じゃが、封印を破りし者のは人じゃ。\nイヨウの憎しみも人と祟霊の関わりの中で生まれしもの。",
  ui_story_5075_50751202_36_dialog_content = "ならば、人と祟霊が己で解決すればよい。",
  ui_story_5075_50751202_37_dialog_content = "うむ。筋が通っておる！",
  ui_story_5075_50751202_38_dialog_content = "こんな時に、筋なんてこだわらなくていいんだけど…",
  ui_story_5075_50751202_39_dialog_content = "しかし、新鮮といえど、\n脅されるというのはいい気分でないのう。",
  ui_story_5075_50751202_40_dialog_content = "ゆえに――",
  ui_story_5075_50751202_41_dialog_content = "（え？シンゲイ？どうして急に飛んでいっちゃったの？\nしかもイヨウの所に…？）",
  ui_story_5075_50751202_42_dialog_content = "トントン。",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>シンゲイは拳を上げ、イヨウの頭を軽くたたいた</color>",
  ui_story_5075_50751202_44_dialog_content = "手出ししたぞ。いかがするのじゃ？",
  ui_story_5075_50751202_45_dialog_content = "シンゲイ！？",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>イヨウの代わりに怒りを示すかのように、\n海面が突如大きな音を立て、波をうねり上げた</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>次から次へと起こる大波は、四方にしぶきの音を響かせながら、\n水面へ落ちることなくますます高く昇ってゆく</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>僕たちの立っていた砂浜もあっという間に水に埋もれてしまった</color>",
  ui_story_5075_50751202_50_dialog_content = "このままじゃ、溺れちゃう！",
  ui_story_5075_50751202_51_dialog_content = "大丈夫よ。私は泳ぎが得意なの。\n溺れたら呼んでちょうだい。引き上げてあげるわ。",
  ui_story_5075_50751202_52_dialog_content = "溺れる前に助けてほしいんだけど！",
  ui_story_5075_50751202_53_dialog_content = "おお、おぬしらもいたな。忘れておった。",
  ui_story_5075_50751202_54_dialog_content = "（身体が、浮いた！？）",
  ui_story_5075_50751202_55_dialog_content = "どうじゃ？わらわの神通力、便利であろう？",
  ui_story_5075_50751202_56_dialog_content = "イヨウはどこ？",
  ui_story_5075_50751202_57_dialog_content = "言っておったじゃろ？街を<color=#FFB400>沈める</color>と。\nあやつは今、皓津に向かっておる。",
  ui_story_5075_50751202_58_dialog_content = "そ、それって最悪の方向に進んでるってことじゃないの！？",
  ui_story_5075_50751202_59_dialog_content = "シンゲイ、どうしてイヨウを刺激するようなことを…",
  ui_story_5075_50751202_60_dialog_content = "PlayerNameよ、そう急くでない。",
  ui_story_5075_50751202_61_dialog_content = "わらわは長いこと生きてきた。\n龍州に生きる者たちのことも、長いこと見てきた。",
  ui_story_5075_50751202_62_dialog_content = "イヨウも、おぬしも――",
  ui_story_5075_50751202_63_dialog_content = "あやつらの力を知らなすぎる。",
  ui_story_5075_50751301_1_dialog_content = "急急如律――",
  ui_story_5075_50751301_2_dialog_content = "グア！",
  ui_story_5075_50751301_3_dialog_content = "おいおい。1匹大人しくなったかと思えば、\n今度は別のが目を覚ましちまう。",
  ui_story_5075_50751301_4_dialog_content = "城内の黒い気もどんどん濃くなってるな。\nこんなもん見えなかった時が懐かしいぜ。",
  ui_story_5075_50751301_5_dialog_content = "縄だけじゃ狂暴化した祟霊は抑えられねーし、\n俺もこいつらに憑いた怨念を祓えればいいんだが…",
  ui_story_5075_50751301_6_dialog_content = "はい、どいてどいて！薬が通るよ！",
  ui_story_5075_50751301_7_dialog_content = "お、お前…祟霊に薬を飲ませてんのか？",
  ui_story_5075_50751301_8_dialog_content = "見れば分かるでしょ？",
  ui_story_5075_50751301_9_dialog_content = "だが、こいつらが狂暴化したのは病気のせいじゃない。\n怨念に浸食されて――",
  ui_story_5075_50751301_10_dialog_content = "キミは、医者は病気しか治せないと思ってるの？",
  ui_story_5075_50751301_11_dialog_content = "怨念だろうと何だろうと、\n体内に入らなきゃ力を発揮できないなら、毒と同じなんだよ。",
  ui_story_5075_50751301_12_dialog_content = "毒には必ず、解毒法があるんだ。",
  ui_story_5075_50751301_13_dialog_content = "今黒い気は皓津城内の隅々まで広がってる。\nチビシッポ…兄さんも影響を受けちゃったんだ。",
  ui_story_5075_50751301_14_dialog_content = "でも、師匠から体内の光力を整える薬をもらって飲ませたら、\n症状がだいぶ収まったんだよ。",
  ui_story_5075_50751301_15_dialog_content = "だから、こうやって手伝いに来たんだ。",
  ui_story_5075_50751301_16_dialog_content = "ニャー！",
  ui_story_5075_50751301_17_dialog_content = "兄さんだって…？そうか、お前も<color=#FFB400>祟霊</color>なのか。",
  ui_story_5075_50751301_18_dialog_content = "それがどうしたの？祟霊じゃいけないの？",
  ui_story_5075_50751301_19_dialog_content = "いや、そうじゃねーよ！\nすげえ医者だなって思っただけさ！",
  ui_story_5075_50751301_20_dialog_content = "ほんとにそう思う？ふふ～ん、キミ見る目あるじゃないか。",
  ui_story_5075_50751301_21_dialog_content = "でも、そんなにすごくないよ…",
  ui_story_5075_50751301_22_dialog_content = "薬は持ってきたけど、みんな動き回るから、\n飲ませようにも飲ませられないんだ。",
  ui_story_5075_50751301_23_dialog_content = "だったら、俺に任せろ！",
  ui_story_5075_50751301_24_dialog_content = "祟霊を見かけたら、俺が気絶させて、お前んとこに連れて来てやる！",
  ui_story_5075_50751301_25_dialog_content = "シーッ！大きな声を出さないでよ！",
  ui_story_5075_50751301_26_dialog_content = "ボク、黙って出てきちゃったんだ。\n見つかったら、怒られちゃうよ。",
  ui_story_5075_50751301_27_dialog_content = "おお、そうか！俺もガキの頃はよくそんなことしてたな。",
  ui_story_5075_50751301_28_dialog_content = "俺が見ててやるから、安心しろ。\n誰にも見つかりやしねーよ。",
  ui_story_5075_50751301_29_dialog_content = "俺はラショウ、こっちはアテイ。俺の相棒だ。",
  ui_story_5075_50751301_30_dialog_content = "ガオー！",
  ui_story_5075_50751301_31_dialog_content = "ボクはリンセイ。こっちはチビシッポ、ボクの兄さんなんだ。",
  ui_story_5075_50751301_32_dialog_content = "ニャ―！",
  ui_story_5075_50751301_33_dialog_content = "よろしくな！/よろしくね！",
  ui_story_5075_50751301_34_dialog_content = "ガオー！/ニャー！",
  ui_story_5075_50751301_35_dialog_content = "チュー！",
  ui_story_5075_50751301_36_dialog_content = "リンセイ先生はここで待っててくれ！俺が見てくる！",
  ui_story_5075_50751301_37_dialog_content = "あ、待ってよ――",
  ui_story_5075_50751301_38_dialog_content = "せっかちだなぁ。",
  ui_story_5075_50751301_39_dialog_content = "た…助けてくれ――！",
  ui_story_5075_50751301_40_dialog_content = "く、来るな！近づいたら、な、殴ってやるからな！",
  ui_story_5075_50751301_41_dialog_content = "ガァ！",
  ui_story_5075_50751301_42_dialog_content = "この、妖怪どもめ！調子に乗るなよ！はぁっ――！",
  ui_story_5075_50751301_43_dialog_content = "やめろ！うっ――",
  ui_story_5075_50751301_44_dialog_content = "ラショウ！",
  ui_story_5075_50751301_45_dialog_content = "何やってるんだよ！間に入れば、自分がケガするでしょ？",
  ui_story_5075_50751301_46_dialog_content = "やれやれ。肩も、お腹もケガしちゃったじゃないか。",
  ui_story_5075_50751301_47_dialog_content = "ははっ、ついつい身体が動いちまってな。",
  ui_story_5075_50751301_48_dialog_content = "俺は何ともない。祟霊はちゃんと捕まえたから、\nまずはこいつに薬をやってくれ。",
  ui_story_5075_50751301_49_dialog_content = "…まったく、ガサツなんだか、ガサツじゃないんだか。",
  ui_story_5075_50751301_50_dialog_content = "す、すまない…君を殴る気はなかったんだ…",
  ui_story_5075_50751301_51_dialog_content = "構わないさ。俺が自分で飛び出してきたんだからな。",
  ui_story_5075_50751301_52_dialog_content = "だ、だが…あいつは祟霊だぞ？かばってどうするんだ？",
  ui_story_5075_50751301_53_dialog_content = "なんで、自分をかばってくれたとは思わないの？",
  ui_story_5075_50751301_54_dialog_content = "あ…",
  ui_story_5075_50751301_55_dialog_content = "突然祟霊に襲われれば、誰だって反撃する。\nだが、祟霊もヒトを襲いたくって襲ってるわけじゃないんだ。",
  ui_story_5075_50751301_56_dialog_content = "みんな被害者なんだよ。",
  ui_story_5075_50751301_57_dialog_content = "誰も間違ってないなら、誰も傷ついちゃいけない。",
  ui_story_5075_50751301_58_dialog_content = "それが道理ってもんだろ？",
  ui_story_5075_50751301_59_dialog_content = "はい、薬を飲ませたよ。少し良くなったみたいだ。",
  ui_story_5075_50751301_60_dialog_content = "もう皓津城の半分は回ったよね。\n大部分の祟霊は処置できたんじゃないかな。",
  ui_story_5075_50751301_61_dialog_content = "チュー。",
  ui_story_5075_50751301_62_dialog_content = "見ただろ？祟霊は悪い力に操られてたから、ヒトを傷つけてたんだ。\n元に戻れば、そんなことはもうしない。",
  ui_story_5075_50751301_63_dialog_content = "…他の誰かに言われても、信じなかったろうが――",
  ui_story_5075_50751301_64_dialog_content = "君の言うことなら、信じるよ。",
  ui_story_5075_50751301_65_dialog_content = "助けてくれてありがとう！他の皆にも話して、\n祟霊が人を傷つけてるのを見たら、君らを呼ぶように伝えるよ。",
  ui_story_5075_50751301_66_dialog_content = "本当か？それはありがたい！",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>ゴォォン――！</color>",
  ui_story_5075_50751301_68_dialog_content = "どうしたんだ？空が急に暗くなったぞ？",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>ポタッ…</color>",
  ui_story_5075_50751301_70_dialog_content = "雨かな？",
  ui_story_5075_50751301_71_dialog_content = "ちょっと待って。これは雨じゃないよ。",
  ui_story_5075_50751301_72_dialog_content = "<size=45>空が暗くなったんじゃない。大きな波が空を覆ってるんだ</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>これじゃ、皓津城が沈んじゃうよ！？</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>慌てふためき、逃げ回る人々で街はごった返した</color>",
  ui_story_5075_50751302_2_dialog_content = "妖魔だ！妖魔が洪水を起こして、俺たちを溺死させるつもりだ！",
  ui_story_5075_50751302_3_dialog_content = "逃げろ――",
  ui_story_5075_50751302_4_dialog_content = "龍女様、どうか私たちをお守りください。龍女様…",
  ui_story_5075_50751302_5_dialog_content = "これはもう、人が解決できる程度を越えてるよ。",
  ui_story_5075_50751302_6_dialog_content = "シンゲイ！僕たちを下ろして！\nせめて皆が無事に避難できるように助けなきゃ！",
  ui_story_5075_50751302_7_dialog_content = "龍女様。",
  ui_story_5075_50751302_8_dialog_content = "うむ…その必要はないじゃろ。",
  ui_story_5075_50751302_9_dialog_content = "でも――",
  ui_story_5075_50751302_10_dialog_content = "PlayerName、よく耳を澄ますのじゃ。",
  ui_story_5075_50751302_11_dialog_content = "うわ！レンガにつまづいちゃった…イタタタタ。",
  ui_story_5075_50751302_12_dialog_content = "ここはどこ…？父ちゃんは？母ちゃんはどこ？",
  ui_story_5075_50751302_13_dialog_content = "ぐすっ…",
  ui_story_5075_50751302_14_dialog_content = "グア！",
  ui_story_5075_50751302_15_dialog_content = "あ！た、助けて――！",
  ui_story_5075_50751302_16_dialog_content = "チュー！",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>暗鬼の攻撃が当たるかと思われたその瞬間、\n祟霊が飛び出し、暗鬼を跳ね飛ばした</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>攻撃もずれ、男の子には当たらなかった</color>",
  ui_story_5075_50751302_19_dialog_content = "君は…",
  ui_story_5075_50751302_20_dialog_content = "これじゃ足りないよ。もっと鳴らそう！",
  ui_story_5075_50751302_21_dialog_content = "祟獣も悪運も、飛んでけ～！",
  ui_story_5075_50751302_22_dialog_content = "チュー…",
  ui_story_5075_50751302_23_dialog_content = "君は…あの時の…",
  ui_story_5075_50751302_24_dialog_content = "グア！",
  ui_story_5075_50751302_25_dialog_content = "あぶない！",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>男の子は勢いよく祟霊に覆いかぶさると、\n祟霊を抱いたまま、泥だらけの地面に転がった</color>",
  ui_story_5075_50751302_27_dialog_content = "アテイ、行け！",
  ui_story_5075_50751302_28_dialog_content = "ぐうう…",
  ui_story_5075_50751302_29_dialog_content = "お？お前…こないだのガキじゃないか？",
  ui_story_5075_50751302_30_dialog_content = "み、水が…落ちてくる――！",
  ui_story_5075_50751302_31_dialog_content = "チュー！",
  ui_story_5075_50751302_32_dialog_content = "待ってよ！僕を置いてかないで――",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>天が崩壊するかのように――</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>轟音と共に、大きな波が空から落ちて来た</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>圧倒的な力を前に、光霊が地上に築いた小さな都市は\nなす術もなく、まるで芥のごとく飲み込まれようとしていた</color>",
  ui_story_5075_50751302_36_dialog_content = "うわああああ――！",
  ui_story_5075_50751302_37_dialog_content = "…",
  ui_story_5075_50751302_38_dialog_content = "あ、あれ？何ともない…なんで？",
  ui_story_5075_50751302_39_dialog_content = "…上を見てみろ。",
  ui_story_5075_50751302_40_dialog_content = "チュー！",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>祟霊は宙に飛び上がり、人々の頭上に障壁を築いた</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>すぐ目の前まで迫っていた波はせき止められた</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>重くのしかかる圧力に、その身体は震えていたが、\nそれでも祟霊は小さな手をかかげ、懸命に障壁を支えている</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>そして、その近くには、また別の障壁が築かれていた</color>",
  ui_story_5075_50751302_45_dialog_content = "ガオー！",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>そのまた向こうにも別の障壁が築かれ――</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>祟霊たちの築いた障壁がつながって、\n一つの大きな障壁ができあがっていた</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>巨大な波はうねりを上げ、重くのしかかるが、\n皓津の上空に留まったまま、先へ進めずにいる</color>",
  ui_story_5075_50751302_49_dialog_content = "あれは…",
  ui_story_5075_50751302_50_dialog_content = "この土地にはのう、古来光霊だけが住まっているわけではないのじゃ。",
  ui_story_5075_50751302_51_dialog_content = "祟霊も、我が家を守りたいのじゃ。",
  ui_story_5075_50751302_52_dialog_content = "リン家の当主に頼まれずとも、\nイヨウが友のため封印を調べに行ったのと同じことじゃ。",
  ui_story_5075_50751302_53_dialog_content = "光霊たちが認めずとも、\nその足元の大地は祟霊たちのものでもあるのじゃよ。",
  ui_story_5075_50751302_54_dialog_content = "PlayerName、聞こえたかの？",
  ui_story_5075_50751302_55_dialog_content = "うん、聞こえたよ。",
  ui_story_5075_50751302_56_dialog_content = "皆にも、聞こえたはずだよ。",
  ui_story_5075_50751302_57_dialog_content = "言葉を伝えるだけでは、手助けとは言えんじゃろ。\nわらわもちと力を貸そうかの。",
  ui_story_5075_50751302_58_dialog_content = "来るがよい――",
  ui_story_5075_50751302_59_option_content = "感知！",
  ui_story_5075_50751302_60_dialog_content = "2本脚の生き物は、悪いヤツだ。\n我らを見かけると、蹴り飛ばす。",
  ui_story_5075_50751302_61_dialog_content = "でも、2本脚の生き物は、いいヤツだ。\nおいしい獲物を捕まえる。",
  ui_story_5075_50751302_62_dialog_content = "時々、我らにも分けてくれる。",
  ui_story_5075_50751302_63_dialog_content = "い、今のはなんだ？",
  ui_story_5075_50751302_64_dialog_content = "祟霊の…声か？",
  ui_story_5075_50751302_65_dialog_content = "熱いものをかけられる。おそろしい。",
  ui_story_5075_50751302_66_dialog_content = "追い出される。おそろしい。",
  ui_story_5075_50751302_67_dialog_content = "この土地は、我らの家でもあるのに。",
  ui_story_5075_50751302_68_dialog_content = "で、でも…俺たちだっておそろしいんだ！\nお前たちは何かというと、物を盗むし、食糧をダメにする。",
  ui_story_5075_50751302_69_dialog_content = "よく分からない法術も使うし…俺たちには手に負えない！",
  ui_story_5075_50751302_70_dialog_content = "2本脚の生き物は、愚かだ。\n落とし物が見つからないと、我らのせいにする。",
  ui_story_5075_50751302_71_dialog_content = "2本脚の生き物は、愚かだ。\n食べ物を印もつけずに置いておけば、誰かに食われて当たり前。",
  ui_story_5075_50751302_72_dialog_content = "でも、2本脚の生き物は、賢い。\n足をケガした時、板で挟んでもらったら、よくなった。",
  ui_story_5075_50751302_73_dialog_content = "俺たち…すごくひどいことしてたんじゃないか…？",
  ui_story_5075_50751302_74_dialog_content = "そうだな。祟霊とはいっても、実際は普通より賢い動物にすぎない。",
  ui_story_5075_50751302_75_dialog_content = "愚かで、賢い。悪いヤツで、いいヤツ。\n我らを傷つけるが、我らに謝る。2本脚の生き物は、よく分からない。",
  ui_story_5075_50751302_76_dialog_content = "でも、仕方ない。",
  ui_story_5075_50751302_77_dialog_content = "仕方ないな。",
  ui_story_5075_50751302_78_dialog_content = "同じ家に住んでいるのだから。",
  ui_story_5075_50751302_79_dialog_content = "水がやってきた。ヤツらは逃げられない。",
  ui_story_5075_50751302_80_dialog_content = "水がやってきた。家も逃げられない。",
  ui_story_5075_50751302_81_dialog_content = "大きな波は悪いヤツ。どっか行け――",
  ui_story_5075_50751302_82_dialog_content = "絶対に入れない…",
  ui_story_5075_50751302_83_dialog_content = "ここは<size=45>我らの家だ！</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>皓津城を覆っていた障壁の上を突然金色の光が走り、\nせき止められていた波は、突然爆発した力により粉々にされてしまった</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>そして、雨となって、音もなく皓津の街に降り注いだ</color>",
  ui_story_5075_50751302_86_dialog_content = "今の雨は…シンゲイが降らせたの？",
  ui_story_5075_50751302_87_dialog_content = "何のことじゃ～？",
  ui_story_5075_50751302_88_dialog_content = "いや…何でもないよ。",
  ui_story_5075_50751302_89_dialog_content = "祟霊たち、本当にすごいね。",
  ui_story_5075_50751302_90_dialog_content = "あとは、イヨウだけだ。",
  ui_story_5075_50751302_91_dialog_content = "…",
  ui_story_5075_50751302_92_dialog_content = "君も聞いたでしょ？街の人たちと祟霊たちの声を。",
  ui_story_5075_50751302_93_dialog_content = "光霊と祟霊の間には誤解も、いざこざも、\n色々な理由でお互いに傷つけ合うこともあるけど――",
  ui_story_5075_50751302_94_dialog_content = "それでも協力して、助け合って、同じ家で一緒に暮らしてるんだ。",
  ui_story_5075_50751302_95_dialog_content = "同じ龍州に生まれた生き物なんだ。\n最初から相手に敵意や悪意を持って生まれてきたわけじゃない。",
  ui_story_5075_50751302_96_dialog_content = "だから、祟霊と光霊はこうして今まで、\n徹底的に対立することなく生きてこられたんだ。",
  ui_story_5075_50751302_97_dialog_content = "それに…",
  ui_story_5075_50751302_98_dialog_content = "さっきの声の中には、君に謝る声もあったんじゃないかな？",
  ui_story_5075_50751302_99_dialog_content = "イヨウ。",
  ui_story_5075_50751302_100_dialog_content = "すまなかった。",
  ui_story_5075_50751401_1_dialog_content = "アヤマル。",
  ui_story_5075_50751401_2_dialog_content = "ドウシテ？",
  ui_story_5075_50751401_3_dialog_content = "コウカイ…",
  ui_story_5075_50751401_4_dialog_content = "シテイナイクセニ。",
  ui_story_5075_50751401_5_dialog_content = "ウッ…ウウ…！",
  ui_story_5075_50751401_6_dialog_content = "海へ戻って行ったよ！追いかけよう！",
  ui_story_5075_50751401_7_dialog_content = "イヨウ！",
  ui_story_5075_50751401_8_dialog_content = "たった一言二言で揺らぐとは、この役立たずめ！",
  ui_story_5075_50751401_9_dialog_content = "ウッ…ウウ…！",
  ui_story_5075_50751401_10_dialog_content = "お前の恨みはその程度か！？\nならば、身体を我にあけ渡すがいい！",
  ui_story_5075_50751401_11_dialog_content = "イヨウは自分で…気の支配から抜け出そうとしてるんだ！",
  ui_story_5075_50751401_12_dialog_content = "（今なら、いけるかもしれない！）",
  ui_story_5075_50751401_13_dialog_content = "ふん。身体はなかなかのものだが、心が弱すぎる。",
  ui_story_5075_50751401_14_dialog_content = "祟霊ともあろう者が光霊の言いなりになるなど、恥を知れ！",
  ui_story_5075_50751401_15_dialog_content = "久しぶりだな、シンゲイ。",
  ui_story_5075_50751401_16_dialog_content = "そうか？久しぶりと言うほどでもなかろう。\n居眠り程度の時しか経っておらぬぞ。",
  ui_story_5075_50751401_17_dialog_content = "相変わらずだな。",
  ui_story_5075_50751401_18_dialog_content = "われらのような者は、変わろうにも変われまい。",
  ui_story_5075_50751401_19_dialog_content = "しかし、人の世はずいぶんと変わったぞ。\nおぬしは海の中におったから、知らぬじゃろうがの。",
  ui_story_5075_50751401_20_dialog_content = "勝手に人探しをするからくり鳥や色とりどりの西洋画、\n己の力で大海原を渡る船――",
  ui_story_5075_50751401_21_dialog_content = "ふん…いかに大そうな物を造り出そうと、\n下級の生き物であることは変わりない。",
  ui_story_5075_50751401_22_dialog_content = "寿命の長い短いで、さようなことを申しておるのか？",
  ui_story_5075_50751401_23_dialog_content = "ならば、おかしいとは思わぬか？",
  ui_story_5075_50751401_24_dialog_content = "光霊の寿命は短いにも関わらず、今この大陸のあちこちに\n住まっているのは、光霊たちじゃ。",
  ui_story_5075_50751401_25_dialog_content = "それに引き換え、おぬしの言う、われらのような上級の生物はわずかしかおらぬ。",
  ui_story_5075_50751401_26_dialog_content = "なぜ、そう自分を貶める？",
  ui_story_5075_50751401_27_dialog_content = "我々祟霊は皆<color=#FFB400>「始祖」</color>の直系、\nこの上なく高貴な存在だ。卑しい光霊とは比べものにならん！",
  ui_story_5075_50751401_28_dialog_content = "今や、何の力も持たぬ光霊までもが、\n祟霊をもてあそび、辱めておる。",
  ui_story_5075_50751401_29_dialog_content = "同族がかような目に遭っているというに、\nお前は見てみぬふりをするというか！",
  ui_story_5075_50751401_30_dialog_content = "祟霊の力も血統も、光霊の上のなのだ！",
  ui_story_5075_50751401_31_dialog_content = "なにゆえ、高貴なわれわれが\n龍州を奴らと分かち合わねばならんのだ！",
  ui_story_5075_50751401_32_option_content = "強制感知！",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5075_50751401_34_dialog_content = "強制感知！",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5075_50751401_36_dialog_content = "（ダメだ…かすかに本物のイヨウの存在は感じられるけど、\n意識がつながらない）",
  ui_story_5075_50751401_37_dialog_content = "PlayerName、私の言葉をイヨウに伝えられるかしら？",
  ui_story_5075_50751401_38_dialog_content = "やってみるよ！ただ、今のイヨウに僕たちの声が\n聞こえるかは分からないよ。",
  ui_story_5075_50751401_39_dialog_content = "構わないわ。",
  ui_story_5075_50751401_40_dialog_content = "深い海の中を自由に泳ぎ回るミズチウオが\n簡単に「溺れる」わけないわ。",
  ui_story_5075_50751401_41_dialog_content = "そうだね。じゃあ、準備はいい？",
  ui_story_5075_50751401_42_option_content = "強制感知！",
  ui_story_5075_50751401_43_dialog_content = "イヨウ、聞こえる？",
  ui_story_5075_50751401_44_dialog_content = "…",
  ui_story_5075_50751401_45_dialog_content = "ここに来る前、当主様が言っていたわ。\nこれまで自分の口からあなたに詫びを入れたことは一度もないと。",
  ui_story_5075_50751401_46_dialog_content = "詫びを入れれば、あなたにその寛容さと包容力で\n己の卑劣さを許すよう強いることになってしまうから。",
  ui_story_5075_50751401_47_dialog_content = "当主は過ちだと分かっていながら罪を犯し、罪のもたらした繁栄を享受した。\n許しを乞う資格などない。",
  ui_story_5075_50751401_48_dialog_content = "リン家も同じよ。",
  ui_story_5075_50751401_49_dialog_content = "ミズチウオの血統を引きながら、リン家に仕える私を裏切者だと言うなら、\n当然、私もあなたの復讐の対象よ。",
  ui_story_5075_50751401_50_dialog_content = "受け入れるわ。",
  ui_story_5075_50751401_51_dialog_content = "だけど、復讐するのはイヨウでなきゃいけないわ。\n誰にも操られていない、あなた自身が復讐してちょうだい。",
  ui_story_5075_50751401_52_dialog_content = "あなたの、ミズチウオの一族の憎しみは、\n他人に預けてしまえるほど軽いものだったの！？",
  ui_story_5075_50751401_53_dialog_content = "チ…ガウ…！",
  ui_story_5075_50751401_54_dialog_content = "反応があったよ！",
  ui_story_5075_50751401_55_dialog_content = "イヨウ、これから僕が君を操ってる怨念を何とかして追い出してみる。",
  ui_story_5075_50751401_56_dialog_content = "だから、協力して。",
  ui_story_5075_50751401_57_dialog_content = "PlayerNameもユエものろまじゃのう。",
  ui_story_5075_50751401_58_dialog_content = "何か言ったか？",
  ui_story_5075_50751401_59_dialog_content = "おぬしのようなつまらぬ者とのおしゃべりはやめじゃ。",
  ui_story_5075_50751401_60_dialog_content = "なんだと…？",
  ui_story_5075_50751401_61_dialog_content = "もうよい。おぬしはわが同族ではない。",
  ui_story_5075_50751401_62_dialog_content = "おぬしはわが同族ではないのう。",
  ui_story_5075_50751401_63_dialog_content = "！",
  ui_story_5075_50751401_64_dialog_content = "目を覚ました時、わらわは同族に合図を送ったのじゃが――",
  ui_story_5075_50751401_65_dialog_content = "みな眠っておってのう。近くの者も、遠くの者も、\n龍州の者も、雲島の者もほとんど返りがなかったのじゃ。",
  ui_story_5075_50751401_66_dialog_content = "ゆえに、仕方なくクロミズチのふりをするおぬしと\n話しておっただけじゃ。",
  ui_story_5075_50751401_67_dialog_content = "おぬしはクロミズチではない。憑りついた器の記憶を盗みし、\n鬱屈とした感情の塊にすぎぬ。",
  ui_story_5075_50751401_68_dialog_content = "おぬしは、クロミズチには傲慢だけを、\nイヨウには憎しみだけを残した。",
  ui_story_5075_50751401_69_dialog_content = "そもそも、おぬしにはそれしかないからのう。",
  ui_story_5075_50751401_70_dialog_content = "二言目には「同族」と言うわりに、\n祟霊には少しの憐みの心も持たぬ。",
  ui_story_5075_50751401_71_dialog_content = "己を「高貴」と言うが、死を恐れ、生に貪欲な、\n卑劣な私欲しか持っておらぬ。",
  ui_story_5075_50751401_72_dialog_content = "己の人格さえ持たず、憑りついた器の影に隠れ、生きておる。",
  ui_story_5075_50751401_73_dialog_content = "かようなおぬしが、真に高貴な命といえるかのう？",
  ui_story_5075_50751401_74_dialog_content = "人格がないから何だというのだ！？\n我こそ真の不死の存在だ！",
  ui_story_5075_50751401_75_dialog_content = "お前たちのような神でさえ、我ほど長き寿命を持たぬ！我は…",
  ui_story_5075_50751401_76_dialog_content = "今だ！感情が乱れた！",
  ui_story_5075_50751401_77_option_content = "強制感知！",
  ui_story_5075_50751401_78_dialog_content = "ワタシノ、カラダダ。",
  ui_story_5075_50751401_79_dialog_content = "デテ、イケ！",
  ui_story_5075_50751401_80_dialog_content = "くっ――！",
  ui_story_5075_50751401_81_dialog_content = "なにっ！？",
  ui_story_5075_50751401_82_dialog_content = "ありがとう、シンゲイ。君があいつの注意をそらしてくれたから、\nイヨウとつながれたんだ！",
  ui_story_5075_50751401_83_dialog_content = "あとは、黒い気の力をイヨウの体内から取り出せば…",
  ui_story_5075_50751401_84_dialog_content = "そうはいかんぞ！",
  ui_story_5075_50751402_1_dialog_content = "キキキキキッ…役に立たぬ身体を捨てたところで何だというのだ。",
  ui_story_5075_50751402_2_dialog_content = "ここは、我が本体が葬られし場所。",
  ui_story_5075_50751402_3_dialog_content = "憑りつく器がなくなったところで、そうたやすくどうこうできぬぞ！",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>遠くの海が再びうねりを上げた</color>",
  ui_story_5075_50751402_5_dialog_content = "（僕はもう、皓津が水の中に沈むのを見たくない）",
  ui_story_5075_50751402_6_dialog_content = "シンゲイ、前に言ってたよね？\nこの金の飾りで、1つだけ願いをかなえてくれるって。",
  ui_story_5075_50751402_7_dialog_content = "おお？",
  ui_story_5075_50751402_8_dialog_content = "施主よ、いかなる願いか？",
  ui_story_5075_50751402_9_dialog_content = "あいつは光霊でもなく、祟霊でもなく、\nさらには暗鬼でもない。",
  ui_story_5075_50751402_10_dialog_content = "悪意が固まった、存在価値のない怨念です。",
  ui_story_5075_50751402_11_dialog_content = "心優しい龍王様、どうかあの怨念を祓い、\nこの世に太平をもたらしてください。",
  ui_story_5075_50751402_12_dialog_content = "確かに聞き届けた。",
  ui_story_5075_50751402_13_dialog_content = "キキキキキッ！800年ぞ。お前のその龍王様は\n皓津が水に沈もうとしていた時でさえ手助けしようとしなかった。",
  ui_story_5075_50751402_14_dialog_content = "おおかた、人々の信仰が薄らぎ、力が衰えたのであろ――",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>その瞬間、光輝く金の蓮が浮かびあがった</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>水晶のごとく清く美しい影が海と空の間に浮かび――</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>金色の光がさざ波のように広がると、\n光の至る所、妖魔が消滅していった</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>皓津城内</color>",
  ui_story_5075_50751402_19_dialog_content = "グゥ――",
  ui_story_5075_50751402_20_dialog_content = "城内の妖魔が…消えた？",
  ui_story_5075_50751402_21_dialog_content = "おい、見ろ！上だ！",
  ui_story_5075_50751402_22_dialog_content = "龍女様よ！龍女様がおいでになったんだわ！\n妖魔を祓ってくださったのよ！",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>クロミズチの姿を借りた怨念は背を向けて逃げ出したが――</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>水晶のごとく美しい影は軽く指をはじくと、\n怨念はそれ以上動けなくなってしまった</color>",
  ui_story_5075_50751402_25_dialog_content = "わらわの力は衰えたと申しておったではないか。\nなにゆえ恐れる？",
  ui_story_5075_50751402_26_dialog_content = "キキ…キキキキキッ！",
  ui_story_5075_50751402_27_dialog_content = "今もまだ、これ程の力を持っていたとは。",
  ui_story_5075_50751402_28_dialog_content = "だが、勝ち誇るのはまだ早い！",
  ui_story_5075_50751402_29_dialog_content = "暗鬼の太祖の力が存在するかぎり、\n我は永遠に滅びることはない！",
  ui_story_5075_50751402_30_dialog_content = "この怨念を祓ったところで、\n力は再び集まり、我は復活するであろう。",
  ui_story_5075_50751402_31_dialog_content = "1度や2度ならまだしも、何千回何万回と我を滅ぼせるのか？",
  ui_story_5075_50751402_32_dialog_content = "我は――",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>怨念が話し終えるのを待たず――</color>",
  ui_story_5075_50751402_34_dialog_content = "心も姿も持たぬ者、この世に存在する意味はない。",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>影は怨念をひねりつぶした</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>次の瞬間、海面に再び黒い霧が起こった</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>怨念と暗力は黒い霧の真ん中で濁った核となり、急速に再生し始めた</color>",
  ui_story_5075_50751402_38_dialog_content = "認めたくはないけど、あいつの言った通りだ。\n僕たちもずっとここで見張ってることはできない。",
  ui_story_5075_50751402_39_dialog_content = "長期的な解決方法がなければ、\n次もそのまた次も、被害を止めることはできない…",
  ui_story_5075_50751402_40_dialog_content = "PlayerName、おぬしはなにゆえ、己を低く見るのじゃ？",
  ui_story_5075_50751402_41_dialog_content = "でも…",
  ui_story_5075_50751402_42_dialog_content = "人々は、この何千年何百年、\nわらわが船を護ってきたと申すが―",
  ui_story_5075_50751402_43_dialog_content = "わらわが先に目覚めたのは100年以上も前のことじゃ。\nしかし、その間この海には船が絶えず行き交っていた。",
  ui_story_5075_50751402_44_dialog_content = "神の加護などなくとも、人々は己を守れるのじゃよ。",
  ui_story_5075_50751402_45_dialog_content = "その通りよ！",
  ui_story_5075_50751402_46_dialog_content = "この声は…",
  ui_story_5075_50751402_47_dialog_content = "センキョク！",
  ui_story_5075_50751402_48_dialog_content = "PlayerName、久しぶりね。",
  ui_story_5075_50751402_49_dialog_content = "夜昼となく頑張って、何とか最後の最後には間に合ったみたいね。",
  ui_story_5075_50751402_50_dialog_content = "鄴の国の最新のカラクリを見せてあげるわ！",
  ui_story_5075_50751402_51_dialog_content = "動力は安定、目標に照準、最大出力に設定して――",
  ui_story_5075_50751402_52_dialog_content = "<size=45>発射！</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>目もくらむばかりの金色の光が海面を引き裂き、\n人工の雷光が黒い気の真ん中を貫いた</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>再び集まり始めた黒い気は、\n裂けた穴をふさぎ終わらぬうちに再び打ち砕かれた</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>豪快な雷光の砲撃がひとしきり続いた後、\n海面はようやく元の穏やかさを取り戻した</color>",
  ui_story_5075_50751402_61_dialog_content = "もう再生しないのかな？",
  ui_story_5075_50751402_62_dialog_content = "うむ。あやつ、反応する間もなく祓われてしまったの。",
  ui_story_5075_50751402_63_dialog_content = "その大砲も、わらわが眠っている間にできたものか？",
  ui_story_5075_50751402_64_dialog_content = "砲筒に頭を突っ込んじゃダメだって！",
  ui_story_5075_50751402_65_dialog_content = "大丈夫よ！動力は切ってあるから。",
  ui_story_5075_50751402_66_dialog_content = "鄴の国に戻ってたんじゃなかったの？",
  ui_story_5075_50751402_67_dialog_content = "そうよ。でも、まだ用事も済んでないのに、\nタンドウ様に呼ばれちゃって。",
  ui_story_5075_50751402_68_dialog_content = "こっちの状況はかなり緊迫してるみたいだったから、\n急いで最高規格の<color=#FFB400>機巧砲</color>を持って駆け付けたってわけ。",
  ui_story_5075_50751402_69_dialog_content = "それなのに、タンドウ様ったら迎えにも来てくれないのよ…",
  ui_story_5075_50751402_70_dialog_content = "まあ、PlayerNameに会えたことだし、満足よ。",
  ui_story_5075_50751402_71_dialog_content = "タンドウは城内だよ。",
  ui_story_5075_50751402_72_dialog_content = "ちょうどイヨウのことも解決したし、\nセンキョクも一緒に戻って皓津で春新節を過ごそうよ。",
  ui_story_5075_50751402_73_dialog_content = "ああ！確か皓津の獣祓いの儀式って、\nすごくにぎやかで、面白いのよね。",
  ui_story_5075_50751402_74_dialog_content = "でも、残念だわ。急いで鄴の国に戻って、\nやらなきゃいけないことがあるの。",
  ui_story_5075_50751402_75_dialog_content = "あなたも急いで城内に戻るといいわ。\n年越しが終わっちゃうわよ。また日を改めましょ。",
  ui_story_5075_50751402_76_dialog_content = "タンドウ様によろしく伝えておいてね。",
  ui_story_5075_50751402_77_dialog_content = "うん、分かった。用事があるなら仕方ないね。",
  ui_story_5075_50751402_78_dialog_content = "何かあれば、からくり鳥で連絡して！",
  ui_story_5075_50751402_79_dialog_content = "はぁ、なんだか損した気分だわ。",
  ui_story_5075_50751402_80_dialog_content = "鄴の国から、遠路はるばる機巧砲を持って駆け付けたのに、\n出番がたったこれだけなんて。",
  ui_story_5075_50751402_81_dialog_content = "ま、誰も迎えに来てはくれなかったけど、\nなかなか威勢のいい退場だったわね。",
  ui_story_5075_50751402_82_dialog_content = "センキョク様。",
  ui_story_5075_50751402_83_dialog_content = "許可なく高規格の秘密兵器をお使いになりましたね？",
  ui_story_5075_50751402_84_dialog_content = "しかも他国に持ち込むとは。これは反逆と見られて当然の行いです。",
  ui_story_5075_50751402_X84_dialog_content = "あはは。あなたたちが鄴の国の者かどうかは置いとくとして…",
  ui_story_5075_50751402_85_dialog_content = "大王様の命で来たの？",
  ui_story_5075_50751402_86_dialog_content = "はい。<color=#FFB400>鄴王</color>様の密命を受け、\n我々はあなたを逮捕いたします。命に背くおつもりですか？",
  ui_story_5075_50751402_87_dialog_content = "…そんなつもりはないわ。",
  ui_story_5075_50751402_88_dialog_content = "私は鄴の国の者よ。かつては鄴の国の官職に就く要人だった。",
  ui_story_5075_50751402_89_dialog_content = "鄴の国の利益を損なう者の命には従わないけど、\nわが国の君主の命には決して背かないわ。",
  ui_story_5075_50751402_90_dialog_content = "罪を認めるわ。",
  ui_story_5075_50751402_91_dialog_content = "…",
  ui_story_5075_50751402_92_dialog_content = "ちょっと、そんな顔しないでくれる？",
  ui_story_5075_50751402_93_dialog_content = "私、初めて牢で年を越すの。\n何か至らない所があっても、どうか許してちょうだい。",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>バンッ！バンッ！</color>",
  ui_story_5075_50751501_2_dialog_content = "わあ、花火だ！",
  ui_story_5075_50751501_3_dialog_content = "一晩離れてただけなのに、\n城内がすっかりにぎやかになってるね。",
  ui_story_5075_50751501_4_dialog_content = "妖魔は退治され、祟霊との誤解もとけた。",
  ui_story_5075_50751501_5_dialog_content = "明日の春新節は、安心して過ごせるわね。",
  ui_story_5075_50751501_6_dialog_content = "イヨウも海へ戻ったのかな？",
  ui_story_5075_50751501_7_dialog_content = "ええ。独りで考えたいって言っていたわ。\nこれからどうするか、自分に何ができるのかをね。",
  ui_story_5075_50751501_8_dialog_content = "イヨウ…本当にリン家に復讐するのかな？",
  ui_story_5075_50751501_9_dialog_content = "分からないわ。",
  ui_story_5075_50751501_10_dialog_content = "ただ、少なくとも過去の清算はできたわ。\nこれから先のことは…",
  ui_story_5075_50751501_11_dialog_content = "明日以降、また考えましょ。",
  ui_story_5075_50751501_12_dialog_content = "「年越し」だもの。そうでしょ？",
  ui_story_5075_50751501_13_dialog_content = "テンカンの言ってたことはウソじゃなかったんだね。\nこの呪文、すごく効果がある！",
  ui_story_5075_50751501_14_dialog_content = "？",
  ui_story_5075_50751501_15_dialog_content = "…ふふ。",
  ui_story_5075_50751501_16_dialog_content = "え！？ユエが笑った？僕、今何かおかしなこと言った！？",
  ui_story_5075_50751501_17_dialog_content = "いいえ。",
  ui_story_5075_50751501_18_dialog_content = "確かにすごい呪文ね。",
  ui_story_5075_50751501_19_dialog_content = "私はリン家に戻って、昨日の後始末をするわ。\nここで失礼するわね。",
  ui_story_5075_50751501_20_dialog_content = "うん、またね。",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>パパパパーンッ！</color>",
  ui_story_5075_50751501_22_dialog_content = "ええ？なに？",
  ui_story_5075_50751501_23_dialog_content = "獣祓いの行列が来たのじゃ。",
  ui_story_5075_50751501_24_dialog_content = "シンゲイ、今までどこに行ってたの…？",
  ui_story_5075_50751501_25_dialog_content = "…って、いつの間にそんなにたくさんのお菓子を！？",
  ui_story_5075_50751501_26_dialog_content = "角を出したまま、一回りしたらの、\n店の主人らが熱心に食べ物を捧げてきたのじゃ。",
  ui_story_5075_50751501_27_dialog_content = "ああ、そうじゃった。\nPlayerNameには角も尻尾もなかったのう。",
  ui_story_5075_50751501_28_dialog_content = "気に病むことはない。半分やろう。",
  ui_story_5075_50751501_29_dialog_content = "ありがとう。ただ、気に病んではいないけどね…",
  ui_story_5075_50751501_30_dialog_content = "おや、見よ。ラショウも獣祓いの行列に加わっておるぞ。",
  ui_story_5075_50751501_31_dialog_content = "本当だ。しかも、祟霊がたくさん参加してる。",
  ui_story_5075_50751501_32_dialog_content = "妖魔も悪運も、爆竹と一緒に飛んでけ～！",
  ui_story_5075_50751501_33_dialog_content = "吉兆も新春も、笑顔と一緒に咲き誇れ～！",
  ui_story_5075_50751501_34_dialog_content = "あれ？でも待って。これって獣祓いの儀式だよね？\nどうして祟霊が祓いの行列に加わってるの？",
  ui_story_5075_50751501_35_dialog_content = "今年から儀式が新しくなったんだよ。\n祓うのは祟霊ではなく、妖魔になったのさ。",
  ui_story_5075_50751501_36_dialog_content = "昨日の晩、龍女様が現れたのを見なかったのかい？\n龍女様は妖魔をことごとく祓ったんだが、祟霊は何ともなかった。",
  ui_story_5075_50751501_37_dialog_content = "つまり、祟霊は人を害しないって、\n龍女様は考えてらっしゃるってことだろ？",
  ui_story_5075_50751501_38_dialog_content = "いいか、よく聞け！\n強大な敵を前にした時には、力を合わせなきゃならない。",
  ui_story_5075_50751501_39_dialog_content = "それぞれが自分の個性を活かし、協力し合えば、\n何倍もの力になるんだ！",
  ui_story_5075_50751501_40_dialog_content = "アテイ、新しい仲間との合体技をみんなに見せてやれ！",
  ui_story_5075_50751501_41_dialog_content = "ガオー！/チュー！",
  ui_story_5075_50751501_42_dialog_content = "ニャー！",
  ui_story_5075_50751501_43_dialog_content = "僕の見間違いかな？",
  ui_story_5075_50751501_44_dialog_content = "行列の中に見覚えのあるネコがいた気がしたんだけど…",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>パパパパーンッ！</color>",
  ui_story_5075_50751501_46_dialog_content = "妖魔も悪運も、爆竹と一緒に…わっ！",
  ui_story_5075_50751501_47_dialog_content = "ごめんなさい。前をよく見てなくて…あ。",
  ui_story_5075_50751501_48_dialog_content = "おや？",
  ui_story_5075_50751501_49_dialog_content = "あ、君はこの間祟霊をイジメてた子だね？",
  ui_story_5075_50751501_50_dialog_content = "あ、あの…お姉ちゃんも祟霊だよね？",
  ui_story_5075_50751501_51_dialog_content = "このアメ、あげる！",
  ui_story_5075_50751501_52_dialog_content = "それから…この前僕たちがイジメてた祟霊を知ってるなら、\nごめんねって伝えといて！",
  ui_story_5075_50751501_53_dialog_content = "行っちゃった…",
  ui_story_5075_50751501_54_dialog_content = "街の人たちの祟霊に対する見方が、本当に変わったみたいだね。",
  ui_story_5075_50751501_55_dialog_content = "うむ…あぐっ。",
  ui_story_5075_50751501_56_dialog_content = "うむ、甘い。",
  ui_story_5075_50751501_57_dialog_content = "この状況にシンゲイは大喜びするのかと思ったけど。",
  ui_story_5075_50751501_58_dialog_content = "わらわは、喜んでおるぞ。",
  ui_story_5075_50751501_59_dialog_content = "でも、なんだか…",
  ui_story_5075_50751501_60_dialog_content = "昨日のシンゲイと、もっといえば、一昨日のシンゲイと\n今のシンゲイは同じ気がする。",
  ui_story_5075_50751501_61_dialog_content = "世の中とは、かようなものじゃ。",
  ui_story_5075_50751501_62_dialog_content = "昨日は恐れのあまり、祟霊に悪意を向け、\n今日は後悔のあまり、祟霊に好意を向ける。",
  ui_story_5075_50751501_63_dialog_content = "明日はまた、別の理由で祟霊に悪意を向けるやもしれぬ。",
  ui_story_5075_50751501_64_dialog_content = "昨日の菓子はうまくても、今日の菓子はうまくない。\n明日の菓子は、またうまくなるやもしれぬ。",
  ui_story_5075_50751501_65_dialog_content = "いつでも、良きものがあり、悪いものがある。\n良くもないが、悪くもない。",
  ui_story_5075_50751501_66_dialog_content = "それで、よいのじゃ。",
  ui_story_5075_50751501_67_dialog_content = "僕には…シンゲイの言う意味があまりよく分からない。",
  ui_story_5075_50751501_68_dialog_content = "でも、色々あって、少し分かった気がする。",
  ui_story_5075_50751501_69_dialog_content = "シンゲイにとっては、人と祟霊だけじゃなく、\nこの大陸に生きる、ありとあらゆる生き物が同等の存在なんだね。",
  ui_story_5075_50751501_70_dialog_content = "どの命にも、それぞれ存在する意義がある。",
  ui_story_5075_50751501_71_dialog_content = "シンゲイは、その存在意義を尊重するからこそ、\n軽々しく干渉はしないんだ。",
  ui_story_5075_50751501_72_dialog_content = "何も気に掛けていないように見えるけど、\n実際にはあらゆる生き物を平等に気に掛けてるんだね。",
  ui_story_5075_50751501_73_dialog_content = "そういう意味では、一緒に過ごしたここ数日のことも、\nシンゲイにとっては、小さな出来事にすぎないんだろうな。",
  ui_story_5075_50751501_74_dialog_content = "ちょっと…悔しい気もするけど。",
  ui_story_5075_50751501_75_dialog_content = "シンゲイは、これからどうするの？",
  ui_story_5075_50751501_76_dialog_content = "わらわは、起こされたゆえ出てきたのじゃ。",
  ui_story_5075_50751501_77_dialog_content = "少ししたら、戻ってまた眠ることにする。",
  ui_story_5075_50751501_78_dialog_content = "そんなすぐに？",
  ui_story_5075_50751501_79_dialog_content = "使者様、大王様より宮中に上がるようお達しがございました。",
  ui_story_5075_50751501_80_dialog_content = "あ、分かりました。",
  ui_story_5075_50751501_81_dialog_content = "シンゲイ、僕と一緒に…あれ？",
  ui_story_5075_50751501_82_dialog_content = "もう帰っちゃったのか…",
  ui_story_5075_50751501_83_dialog_content = "PlayerName、ご苦労であった。",
  ui_story_5075_50751501_84_dialog_content = "此度は――",
  ui_story_5075_50751501_85_dialog_content = "PlayerName！PlayerName！",
  ui_story_5075_50751501_86_dialog_content = "タンドウより聞いたぞ。\nそなたは危機を前に任を受け、知勇に優れた働きをしたと。",
  ui_story_5075_50751501_87_dialog_content = "済の国の朝廷に潜んでいた奸臣を捕らえただけでなく、\n昨日の洪水をいちはやく治めたのも、そなたの功労だというではないか！",
  ui_story_5075_50751501_88_dialog_content = "お世継ぎ、わらわはかように大げさな言い方はしておりませぬぞ。",
  ui_story_5075_50751501_89_dialog_content = "いずれにせよ、PlayerNameは英雄だ！",
  ui_story_5075_50751501_90_dialog_content = "英雄は素晴らしい！\n<size=45>僕はPlayerNameと結婚する！</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>…へ？</size>",
  ui_story_5075_50751501_92_dialog_content = "夫婦は一体と言うであろう。\nそなたのように素晴らしい許嫁がおれば、僕も将来必ずや英雄になれるぞ！",
  ui_story_5075_50751501_93_dialog_content = "<size=45>コホン！</size>",
  ui_story_5075_50751501_94_dialog_content = "誰か、急ぎ世継ぎを下がらせよ！",
  ui_story_5075_50751501_95_dialog_content = "師傅に伝えよ。世継ぎに夫婦とは何か、しかと正しき知識を教えよと。\nまったく…戯言ばかりを言いおって…",
  ui_story_5075_50751501_96_dialog_content = "だが、他の話は真であるな。",
  ui_story_5075_50751501_97_dialog_content = "皓津の此度の危機は、余の誤算であった。\nそなたの働きにより切り抜けることができた。",
  ui_story_5075_50751501_98_dialog_content = "何か望みがあるのなら、申すがよい。\n余がかなえてやろう。",
  ui_story_5075_50751501_99_dialog_content = "では、僕とタンドウの二大陸間の交流に関する計画を聞いてもらえませんか？",
  ui_story_5075_50751501_100_dialog_content = "それだけか？金銀財宝や地位権勢は要らぬと申すか？",
  ui_story_5075_50751501_101_dialog_content = "正直なことを言えば、欲しくないわけではありません。\nでも、僕はアストラ大陸の使者として、この龍州に来ました。",
  ui_story_5075_50751501_102_dialog_content = "使命を果たすことが一番の大事です。",
  ui_story_5075_50751501_103_dialog_content = "ははは、実に優れた若者だ。\nなおさら帰したくなくなったぞ。",
  ui_story_5075_50751501_104_dialog_content = "だが、そなたに龍州に留まる気はない。\nならば――",
  ui_story_5075_50751501_105_dialog_content = "そなたに済の国栄誉国民の称号を授けよう。",
  ui_story_5075_50751501_106_dialog_content = "今後、そなたがいずこに向かおうと、何を成そうと、\n済の国はいつでもそなたを歓迎するぞ。",
  ui_story_5075_50751501_107_dialog_content = "ありがとうございます！",
  ui_story_5075_50751501_108_dialog_content = "はぁ…ずいぶん長いこと宮中にいたんだなぁ。\nもうこんな時間だ。",
  ui_story_5075_50751501_109_dialog_content = "管理官が捕まった後、迎賓館には侍女も護衛もいなくなったから…",
  ui_story_5075_50751501_110_dialog_content = "ここで1人で過ごすのは初めてだなぁ。",
  ui_story_5075_50751501_111_dialog_content = "…静かだ。",
  ui_story_5075_50751501_112_dialog_content = "いざ暇になってみると、何をすればいいか、分からなくなる…",
  ui_story_5075_50751501_113_dialog_content = "そうだ。明日は春新節だった。",
  ui_story_5075_50751501_114_dialog_content = "龍州の人たちは今夜みんなで集まって、\n夜通しでおしゃべりしながらご飯を食べるんだよね。",
  ui_story_5075_50751501_115_dialog_content = "過ぎた1年にお別れして、新しい年を迎えるんだ。",
  ui_story_5075_50751501_116_dialog_content = "僕もやってみようかな…やっぱり、よそう。\n1人で夜通し起きてても、面白くないし。",
  ui_story_5075_50751501_117_dialog_content = "みんな今頃、何してるのかな…",
  ui_story_5075_50751501_118_dialog_content = "おぬしが気づくのを待っておるぞ。",
  ui_story_5075_50751501_119_dialog_content = "へ！？い、いつ入ってきたの？",
  ui_story_5075_50751501_120_dialog_content = "おぬしが戻る前からおったぞ。",
  ui_story_5075_50751501_121_dialog_content = "だというのに、PlayerNameは1人何やらうろついてばかりで、\nわらわには一向に気づかぬ。仕方なく出てきたのじゃ。",
  ui_story_5075_50751501_122_dialog_content = "見てたの…？",
  ui_story_5075_50751501_123_dialog_content = "もう帰っちゃったのかと思ってたよ。",
  ui_story_5075_50751501_124_dialog_content = "少ししたら、海に戻るって言ってたから。",
  ui_story_5075_50751501_125_dialog_content = "そうじゃ。長居はせぬ。",
  ui_story_5075_50751501_126_dialog_content = "数十年くらいで、帰ろうかのう。",
  ui_story_5075_50751501_127_dialog_content = "え、待って…君の言う「少し」って数十年なの？",
  ui_story_5075_50751501_128_dialog_content = "短いかのう？",
  ui_story_5075_50751501_129_dialog_content = "PlayerNameと遊ぶのは楽しいからな。",
  ui_story_5075_50751501_130_dialog_content = "おぬしが望むなら、100年でも200年でも構わぬぞ。",
  ui_story_5075_50751501_131_dialog_content = "…そうだった。祟霊の時間の感覚は普通と違うんだった…",
  ui_story_5075_50751501_132_dialog_content = "それにしても、ここは寂しいのう。",
  ui_story_5075_50751501_133_dialog_content = "今宵は年越し料理を食べねばならぬというに。",
  ui_story_5075_50751501_134_dialog_content = "あはは、ごめん、用意してなくて。",
  ui_story_5075_50751501_135_dialog_content = "仕方ないのう。今さっきもろうた千重春巻きじゃ。\nおぬしにやろう。",
  ui_story_5075_50751501_136_dialog_content = "ありがとう…千重春巻き？",
  ui_story_5075_50751501_137_dialog_content = "PlayerName――シンゲイ――",
  ui_story_5075_50751501_138_dialog_content = "どこだぁ？",
  ui_story_5075_50751501_139_dialog_content = "ラショウ？",
  ui_story_5075_50751501_140_dialog_content = "ラショウ！こっちだよ！",
  ui_story_5075_50751501_141_dialog_content = "PlayerName、シンゲイ！やっとみつけた。",
  ui_story_5075_50751501_142_dialog_content = "俺はそそっかしくてな。\n別れ際にあんたらの住所を聞き忘れちまった。",
  ui_story_5075_50751501_143_dialog_content = "まさか、僕たちの名前を大声で叫びながら\n街じゅうを探したわけじゃないよね？",
  ui_story_5075_50751501_144_dialog_content = "ははっ、一見遠回りのようだが、こうして見つかったろ？",
  ui_story_5075_50751501_145_dialog_content = "一緒に戦った仲だ。一緒に年越しして構わねーだろ？",
  ui_story_5075_50751501_146_dialog_content = "もちろんだよ！",
  ui_story_5075_50751501_147_dialog_content = "そりゃ、よかった。",
  ui_story_5075_50751501_148_dialog_content = "そういや、さっき荷物を運ぶの手伝ったら、\nおばさんがミツバをくれたんだ。",
  ui_story_5075_50751501_149_dialog_content = "年越し料理を1品増やせるぜ。",
  ui_story_5075_50751501_150_dialog_content = "おやまぁ、ここは僕の占い屋よりも寂しいですねぇ。",
  ui_story_5075_50751501_151_dialog_content = "テンカン？どうしてここに？",
  ui_story_5075_50751501_152_dialog_content = "そりゃあタダ飯を…いえ、異邦で年越しなんて、\n旦那が困ってるんじゃないかと思いましてねぇ。",
  ui_story_5075_50751501_153_dialog_content = "案の定、年越し料理も用意してないじゃありませんか。\n来てよかったですねぇ。",
  ui_story_5075_50751501_154_dialog_content = "さ、お年賀です。",
  ui_story_5075_50751501_155_dialog_content = "ありがとう。でも、どうして山菜なの？",
  ui_story_5075_50751501_156_dialog_content = "ただの山菜じゃありませんよ。これはナズナといいましてね。\n冬はなかなか手に入らないんです。",
  ui_story_5075_50751501_157_dialog_content = "数日間アメ細工を売った収入をはたいて、\nようやく屋内で育てたナズナを1カゴ買えたんです。",
  ui_story_5075_50751501_158_dialog_content = "撫でて汚れを祓う、と言いましてね。縁起のいいもんなんです。\nこれを食べれば、来年もいい年になりますよ。",
  ui_story_5075_50751501_159_dialog_content = "おや、千重春巻きもあるんですねぇ。\n縁起がいいですねぇ。千代栄えるって意味です。",
  ui_story_5075_50751501_160_dialog_content = "ミツバも縁起がいいんです。縁を結びますからねぇ。\n幸先がいいですね。",
  ui_story_5075_50751501_161_dialog_content = "PlayerName、手伝ってちょうだい――",
  ui_story_5075_50751501_162_dialog_content = "商会からレンコンが車1台分送られてきたんだけど、\nあなたの所には食材もないだろうから、持ってきたわ。",
  ui_story_5075_50751501_163_dialog_content = "車1台分！？",
  ui_story_5075_50751501_164_dialog_content = "受け取るといいですよ。レンコンも縁起もんです。",
  ui_story_5075_50751501_165_dialog_content = "レンコンは「先を見通せる」といいましてね。\n万事順調に運ぶって言われてるんです。",
  ui_story_5075_50751501_166_dialog_content = "どんなものでも、君にかかれば縁起物になっちゃうんだね。",
  ui_story_5075_50751501_167_dialog_content = "年越しですから。何事も縁起よくなくっちゃねぇ。",
  ui_story_5075_50751501_168_dialog_content = "遠くまでテンカンの戯言が聞こえておるぞ。",
  ui_story_5075_50751501_169_dialog_content = "じゃが、年越しじゃ。縁起のよい言葉は大歓迎じゃ。",
  ui_story_5075_50751501_170_dialog_content = "PlayerName様、お久しゅうございます。",
  ui_story_5075_50751501_171_dialog_content = "タンドウ、キュウ！宮中にいなくていいの？",
  ui_story_5075_50751501_172_dialog_content = "本来ならば、宮中で過ごすべきなのじゃが――",
  ui_story_5075_50751501_173_dialog_content = "PlayerNameが見事功を立てたのでな。\n大王様より特別な命を受けて参ったのじゃ。",
  ui_story_5075_50751501_174_dialog_content = "よい年越しを過ごさせるように、とな。",
  ui_story_5075_50751501_175_dialog_content = "宮中より食材も賜った。\nわらわ自ら腕を振るい、年越し料理を振る舞おう。",
  ui_story_5075_50751501_176_dialog_content = "それはそうと、皆食材を祝いの品としたようじゃな。\nならば、わらわも食材を贈ろうかの。",
  ui_story_5075_50751501_177_dialog_content = "この美しい黄色の金針菜を贈り――",
  ui_story_5075_50751501_178_dialog_content = "お主の前途を祝そう。",
  ui_story_5075_50751501_179_dialog_content = "では、私はこちらのエンドウ豆の葉をお贈りいたします。\n枝一杯の春という意味があり、縁起がよいものです。",
  ui_story_5075_50751501_180_dialog_content = "わ、すごい人だね。",
  ui_story_5075_50751501_181_dialog_content = "PlayerNameが1人で年越ししてるんじゃないかって心配してきたのに。",
  ui_story_5075_50751501_182_dialog_content = "友が多きは良きことだ。",
  ui_story_5075_50751501_183_dialog_content = "シュウさん、リンセイ！来てくれたんだね！",
  ui_story_5075_50751501_184_dialog_content = "食材がいっぱいだね。あ、そうか！",
  ui_story_5075_50751501_185_dialog_content = "十宝菜を作るつもりだね？",
  ui_story_5075_50751501_186_dialog_content = "十宝菜って何？",
  ui_story_5075_50751501_187_dialog_content = "済の国の伝統料理だ。\n10種以上の野菜を千切りにして炒め、一つの料理を作る。",
  ui_story_5075_50751501_188_dialog_content = "さすれば、それぞれの食材の持つ吉祥の意も一つになる。",
  ui_story_5075_50751501_189_dialog_content = "済の国の春新節には欠かせぬ料理なのだ。",
  ui_story_5075_50751501_190_dialog_content = "だが、今ある食材では足らぬようだな。",
  ui_story_5075_50751501_191_dialog_content = "ならば各位の万事発展を願い、それがしからカラシナを贈ろう。",
  ui_story_5075_50751501_192_dialog_content = "じゃ、ボクはスベリヒユをあげる。",
  ui_story_5075_50751501_193_dialog_content = "スベリヒユは野菜としてだけじゃなく、\n解熱解毒の薬としても使われるんだよ。",
  ui_story_5075_50751501_194_dialog_content = "皆の持ち寄った食材、実にさまざまじゃのう。\nわらわの腕が試されるわ。",
  ui_story_5075_50751501_195_dialog_content = "これしきのこと、殿下には何でもありません。",
  ui_story_5075_50751501_196_dialog_content = "キュウまでわらわをおだてるとは。\nならば、共に料理の腕を振るってもらおうか。",
  ui_story_5075_50751501_197_dialog_content = "僕も手伝うよ。",
  ui_story_5075_50751501_198_dialog_content = "味見なら、喜んで手伝いますよ――",
  ui_story_5075_50751501_199_dialog_content = "味見係はわらわじゃ！",
  ui_story_5075_50751501_200_dialog_content = "おや、では僕の出番はなさそうですねぇ。お譲りしますよ。",
  ui_story_5075_50751501_201_dialog_content = "俺は外に置いてある食材を見てこよう。\n使うもんを中に運んでやるよ。",
  ui_story_5075_50751501_202_dialog_content = "飾りも持ってきたわ。部屋の飾りつけをしましょ。",
  ui_story_5075_50751501_203_dialog_content = "それはいいね！何だか雰囲気が足りないと思ってたんだ。",
  ui_story_5075_50751501_204_dialog_content = "皆の食材を集めて作った十宝菜ぞ。",
  ui_story_5075_50751501_205_dialog_content = "少ししたら、龍女廟の鐘が鳴る。\nそうすれば、新しい年の到来じゃ…",
  ui_story_5075_50751501_206_dialog_content = "PlayerName、この1年世話になった。\n心より礼を申す。",
  ui_story_5075_50751501_207_dialog_content = "私は文に長けておりませんので、ただただ感謝を申し上げます。",
  ui_story_5075_50751501_208_dialog_content = "僕も今年は旦那にお世話になりましたねぇ。\n来年もぜひ、占いに来てくださいよ。",
  ui_story_5075_50751501_209_dialog_content = "先頃の旅では、貴公には真に助けられた。\n新しい年も貴公の前途が順調であることを祈っておるぞ。",
  ui_story_5075_50751501_210_dialog_content = "とにかく、いろいろありがとう。\n来年も健康に過ごすんだよ。ボクの手を煩わせないでね。",
  ui_story_5075_50751501_211_dialog_content = "知り合ったばかりだが、あんたはもうダチだ！",
  ui_story_5075_50751501_212_dialog_content = "来年も健康に丈夫で過ごせよ。\n妖魔やあやかしを見かけたら、とにかくぶっ飛ばせ！",
  ui_story_5075_50751501_213_dialog_content = "明けましておめでとう！乾杯！",
  ui_story_5075_50751501_214_dialog_content = "ゴク――",
  ui_story_5075_50751501_215_dialog_content = "おやおや、まだ新年じゃありませんよ。\nもう飲んでしまいましたか！？せっかちですねぇ…",
  ui_story_5075_50751501_216_dialog_content = "PlayerName、PlayerName。",
  ui_story_5075_50751501_217_dialog_content = "シンゲイ？どうしたの？",
  ui_story_5075_50751501_218_dialog_content = "下を向くがよい。",
  ui_story_5075_50751501_219_dialog_content = "分かった。でも、何をするの？",
  ui_story_5075_50751501_220_dialog_content = "なでなで。",
  ui_story_5075_50751501_221_dialog_content = "PlayerNameが日々楽しく、万事順調に暮らせるように。",
  ui_story_5075_50751501_222_dialog_content = "神自ら願うてやったのじゃ。必ずかなうじゃろう。",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>ゴーン――ゴーン――</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>南山の龍女廟の鐘の音が城内に鳴り響いた</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>108回の鐘の音が人々の煩悩を祓い、\n安寧と吉祥をもたらす</color>",
  ui_story_5075_50751501_226_dialog_content = "鐘が鳴ったってことは、春新節…新年を迎えたってことだね。",
  ui_story_5075_50751501_227_dialog_content = "PlayerName。",
  ui_story_5075_50751501_228_dialog_content = "PlayerName様。",
  ui_story_5075_50751501_229_dialog_content = "PlayerName。",
  ui_story_5075_50751501_230_dialog_content = "PlayerName。",
  ui_story_5075_50751501_231_dialog_content = "PlayerName。",
  ui_story_5075_50751501_232_dialog_content = "PlayerName。",
  ui_story_5075_50751501_233_dialog_content = "PlayerName。",
  ui_story_5075_50751501_234_dialog_content = "PlayerName。",
  ui_story_5075_50751501_235_dialog_content = "<size=45>明けまして、おめでとう</size>"
}
return config
